/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220310-3","meetingId":"r04-c-budget","date":"2022年3月10日","dateIso":"2022-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を171件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年度品川区一般会計予算","agenda":"令和４年度品川区一般会計予算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"おはようあります。本日もよろしくお願いいたします。私からは、２８７ページ、犬の登録、時間があれば、３０５ページの商店街活性化事業についてお伺いします。犬の登録について、殺処分ゼロに向けて区にどういったことができるのかということを幾つかお伺いしたいと思います。","respondent":"鈴木生活衛生課長","answer":"犬の登録ですが、大きく２つ、事業者、ブリーダーやペットショップの事業者の場合と、一般の区民の方とで多少情報が異なりますが、基本的には、飼い主の名前、住所、犬の種類、それから特徴というようなところを登録をします。","voiceIndex":4,"id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"そうすると、基本的にこれは義務化されていると認識していますので、区内の犬の情報というのは、おおむね１００％把握できているという認識でよろしいのでしょうか。結局は粘り強く交渉して何とかなったのですが、区内で無許可のブリーダーが多頭飼育崩壊になった場合に、品川区として、どういった対応をとられるのかも併せてお聞かせください。","respondent":"鈴木生活衛生課長","answer":"お尋ねの無許可のオーナー等の不適切な飼育に関してですが、これはまずは一義的には、区の保健所のほうで、通報なり相談なりを受けた時点で現地を確認いたしまして、通常の適正飼育の指導で済むような内容であれば区のほうで対応いたしますが、虐待と考えられたり、また。","voiceIndex":6,"id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問・要望","question":"それを防ぐためにということで非常に効果が期待されているところですが、これから品川区としてどういった対応をとるのかということをお聞かせいただきたいのですが、情報へのアクセス権、マイクロチップの情報へのアクセス権を持っていらっしゃるのかお聞かせいただきたいのと、アクセス権があるとすれば、先ほどの例えと同じように、ワンルームマンションとかで異常な数が登録されているという場合に。","respondent":"鈴木生活衛生課長","answer":"マイクロチップに関してですが、新しくこの６月に開始される予定のワンストップサービスへの登録制度に自治体として参加をすれば、こちらからアクセスするのではなくて、登録業務を国から指定された団体から、毎月データで情報が送られてくるということになっております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"関連して、地域猫についてもお伺いいたしますが、そもそも、この地域猫の品川区としての扱いとしては、これからどんどん頭数を減らしていこうというような思いでやっていらっしゃるというふうに認識をしています。今、モデル地区を、小山のほうでやっていらっしゃると思うのですが、そこからの広がり、全区的にどういった対応をとられているのかお聞かせください。","respondent":"鈴木生活衛生課長","answer":"制度が開始されて、今、１３年ぐらいたちますが、９地区は対応完了や、担い手がいないというようなことで事業を終了したところがありますので、延べ３０地区で展開されているという現状です。","voiceIndex":10,"id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"このマイクロチップとの関わりについてお伺いしたいのですが、マイクロチップには、飼い主がいるということを証明していくことが１つ方法としてあって、一部のニュースでは、懸念として、飼い主がある意味いないというのが、チップが埋め込まれていないイコール飼い主がいない、そこから虐待なり犯罪につながってしまうというような懸念もあるというふうに伺っていて、例えば、この地域猫に関しても。","respondent":"鈴木生活衛生課長","answer":"ご質問にありましたマイクロチップを使っての動物虐待の防止ですが、現在、国のほうからマイクロチップの登録の仕組みについて示されている中で、飼い主がいない場合の想定が今はございませんので、この場でその対応ができるかどうかは分かりませんが、ご指摘のように。","voiceIndex":12,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問","question":"２８３ページ、定期予防接種、子宮頸がんワクチン、２８３ページ、不妊治療助成事業、２９３ページ、もったいないプロジェクト、２９５ページ、家庭用生ごみ処理機普及事業について、順不同で伺ってまいります。子宮頸がんワクチンについてお伺いいたします。コロナ禍のこの２年の間に急速に進んでまいりました。","respondent":"鷹箸保健予防課長","answer":"定期接種の対象となります５学年分、この４月に小学校６年生になる方から、高校１年生になる方につきましては、ぎりぎりですが、３月末までには確実にお手元に届くように、現在、予診票の印刷、それから封入、あと、２月末ぎりぎりに出ましたが。","voiceIndex":16,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"定期接種の方、そして機会を逃したキャッチアップ接種の方、この２種類があると思います。定期接種の方は約６,８００人、キャッチアップの方が約１万２,０００人ちょっとということで、先日の厚生委員会で確認させていただきました。中にある資料がＱＲコード化されてデータで読み取っておくことができるような、そういう工夫も必要と考えますが、ご見解を伺います。","respondent":"鷹箸保健予防課長","answer":"予診票につきましては、２３区統一で制定するものなのですけれども、その意味では、ある意味、まだ間に合いますので、その封筒に強調するというところも含めまして、今、積極的に対象の方に情報が確実に届くよう、また。","voiceIndex":18,"id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"ぜひよろしくお願いいたします。それから、１点だけ確認です。２０１３年６月から積極的勧奨が中止になりました。１回だけ打って、２回、３回目を打っていない方には、今回、接種券が発送されると伺いましたが、期間が空いてしまっても効果があるものなのか。１回目を打った方は、今回、２回目、３回目だけを打つような流れになるかと思うのですが、効果はどうなのかということをお聞かせください。","respondent":"鷹箸保健予防課長","answer":"ですが、とにかく３回、なるべく早く接種していただきたいというふうに考えてあります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"お問合せも増えることと思いますが、丁寧なご対応とともに、例えば、もし自費でも打ちたいとなれば、それが打つことが可能なのでしょうか。改めて３回打ちたいということで、そうすると、２回分だけは助成対象になって、１回は自費というような、そういうことも含めて、まだ国のほうから指針が出ていないということなのでしょうか。","respondent":"鷹箸保健予防課長","answer":"そうしますと、当然、９価のワクチンのほうが効果が高いので、そこも含めて、打ち控えなど、そういったこともあるのではないかと、今、様々な問題が起きておりますので、その辺、まずは４月から定期接種の対象の人に確実に始めるというところを先にして、一番効果の高い形で。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"もったいないプロジェクトについてお伺いいたします。そういう中で、品川区はもったいないプロジェクトを、７年目になりますでしょうか、進めていただいていることは大変重要なことと思います。７年がたちました。今回も新規予算が計上されておりますけれども、いよいよ事業内容の検証が必要ではないかなと、どれだけの効果があったのか、この事業検証について、区の見解をお伺いします。","respondent":"河内環境課長","answer":"は食品ロスにつきましては、こういった食品の生産、加工、販売などにつきまして、各工程におきまして一定のエネルギーを使うことから、ＣＯ２削減に向けて重要な取組みということで認識しています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区は個店で対応されておりますけれども、何か新しい展開として、品川区の中にも大型スーパーが何店舗かあるかと思いますので、そういうところへの働きかけもぜひ進めていただきたいと思いますが、いかがでしょうか。それが１点。かねてより常設をお願いしておりましたが、いよいよエコルとごしが開設するにあたって、ぜひエコルとごしでのフードドライブの常設を要望いたしますが、お伺いいたします。","respondent":"河内環境課長","answer":"この検討の間、エコルとごし、区の環境課、消費者センターなどでも、年４回程度で、１週間程度の定期的な回収、利用を促進いたしまして対応し、拡大に向けて進めていきたいというふうに考えているところです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"エコルとごしでの段階を踏まえての常設ということを、ぜひご検討いただくよう、よろしくお願いしたいと思います。新年度、拡充されるということですが、どれだけ拡充されて、また、もしこれが予算額に達してしまったときは、さらに増やしていただきたいという思いもあるのですが、事業展開をお知らせください。","respondent":"品川品川区清掃事務所長","answer":"予算の充実というところですけれども、前年度に比べまして、予算上は件数を２倍にしています。状況を見まして、この辺のところも拡充していくかどうするかというところも状況を見ていきたいというふうに考えております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"需要を見極めていただきながら、これは本当にそれぞれ区民が生ごみを絞ることでのＣＯ２削減につながっていく取組みとなりますので、どうぞ前向きにご検討いただきたいと思います。すみません、時間がなくなってしまいました。不妊治療に関しては質問ができません。以上で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-013"},{"speaker":"横山委員","kind":"質問","question":"私からは、２７９ページ、母子健康診査費、２８３ページ、予防接種費、３０３ページ、中小企業活性化事業費、３０１ページ、創業支援施設等経費、就業支援費についてお伺いいたします。１点目に、創業支援施設等経費と就業支援費についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"メンズ・クライシスの関係です。現在、創業支援施設に入居される方ですと、必ず全員と面接をしています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"創業支援の審査の際の面接官の方は、福祉の専門家というわけではないかと思いますので、その辺りもぜひ福祉部門と連携をしていただきながら、商業・ものづくり課と福祉部門とが連携をして、メンズ・クライシスの予防を進めていただきたいというふうに要望いたしますが、改めて区のご見解をお聞かせいただけたらと思います。２点目に、中小企業活性化事業費についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"２点目の中小企業の支援の効果ですけれども、様々なものをやらせていただきまして、一番顕著なものといたしましては、やはり倒産件数が、ここ２年間、毎年減っているという部分で、しっかり支援が行き届いているのかなというふうに考えているところです。","voiceIndex":34,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"中小企業活性化事業費の部分、区のお考えを聞かせていただいて、倒産の件数が減っているということで、ありがとうあります。感染症の影響が長期化する中で、これまでは多くの補助金を受けなくても、何とか自社の中で努力をして持ちこたえてきたような区内事業者から、特にオミクロン株の影響下におきましては、ボディブローのようにじわじわとダメージを与えられているというようなお話をお伺いしました。","respondent":"遠藤商業・ものづくり課長","answer":"来年度もいろいろとメニューをご用意していますし、また必要があれば補正予算等を提案する形になろうかと思いますけれども、引き続き効果的な支援を続けていきたいというふうに考えております。","voiceIndex":36,"id":"exchange-016"},{"speaker":"横山委員","kind":"提案","question":"ぜひ様々な事業者の状況を見ていただきまして、引き続き支援を続けていただきたいというふうに思っております。３点目に、予防接種費、母子健康診査費についてお伺いいたします。母子手帳に関連して、私たちの会派から、これまで様々な要望をさせていただきました。母子手帳に関して、区ではどのような検討がされてきたのでしょうか。今後の展開についてもご説明をお願いいたします。","respondent":"高山健康課長","answer":"母子手帳に関するご質問にお答えいたします。区での検討状況ですが、母子手帳はその前身となります妊産婦手帳を含めまして、日本では約８０年の歴史を誇るといったものでございまして、時代に合わせまして様々変化を続けてきたところです。","voiceIndex":38,"id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"「親子健康手帳」ということを併記していただくですとか、様々これまでも時代に合わせて変化を遂げてきている母子手帳ですけれども、今後もぜひよろしくお願いいたします。赤ちゃんが泣いたときの対応など、やわらかく育児に悩んだときに相談がしやすいような雰囲気で啓発をしておりまして、このような啓発の手法をぜひ取り入れていただきたいというふうに思いますが、区のご見解をお聞かせください。","respondent":"高山健康課長","answer":"ご提案いただいております育児の負担が軽くなるようなアドバイスなど、そういったものも１つ有効な啓発手段と考えますので、今後、内容を精査しつつ、新しいものも取り入れてまいりたいと考えております。","voiceIndex":40,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"２８５ページ、自殺予防対策事業について伺います。このインターネットゲートキーパーの仕組みを、どのように区内の自殺対策に生かすのか、ちょっと分からないので伺いたいというのが１つです。研修を受けたらゲートキーパーになるのでしょうか。新年度、年６回の研修をやると言いますけれども、受講人数の目標を何人ぐらい想定しているのでしょうか。どのように活用されているかについて伺います。","respondent":"鷹箸保健予防課長","answer":"ゲートキーパー研修につきましては、ご指摘のとおり、区の計画を策定後、大幅に内容をランクアップして、それまで初級編を年３回だったところ、中級編、上級編なども実施していますが、具体的な目標を設けているわけではございませんが、幸か不幸かコロナの影響で。","voiceIndex":43,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと伺って、今の区の自殺対策の計画を見たのですけれども、１点は、どちらかといえば、程度の大小はあるけれども、希死念慮を抱いた方への対策のように思います。なぜなら、自殺に至るまでは長く複雑な過程がある。大変勉強になる活かすべき内容の話だったと思います。区が高橋さんを講師に選んだ理由についてですが、どのような中身を期待して高橋さんに講演を依頼したのでしょうか、伺います。","respondent":"鷹箸保健予防課長","answer":"その意味では、この講師の方を選ばれた具体的な理由は、保健予防課のほうでは把握してございませんが、この先生の経歴ですとか、これまでのご活動を拝見いたしますと。","voiceIndex":47,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"講演では、国全体の数字ですけれども、児童・生徒の自殺者数は、コロナ禍で急増、高止まりしていることや、あと未成年の自殺率が、平成元年からこの３０年間を見ると２倍になっていると。これは先進国では韓国と日本だけだということなどが紹介されていました。伺いますが、品川区の子ども若者の自殺率が全国に比較して高い理由について、区はどのように分析されているのでしょうか、伺います。","respondent":"鷹箸保健予防課長","answer":"自殺率の比較の仕方につきましては、ＮＰＯ法人自殺対策支援センターライフリンクのほうで、全国全ての自治体を比べているですが、比べ方にも非常に特徴があるところですが、確かに高いという事実があるというふうに当然認識しておりまして。","voiceIndex":49,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"なかなかなぜというのは難しいと思うのですけれども、ただ、高いという事実はあるということでございました。ですから、もちろん重点施策に入れているということで、本当にそうだと思うのです。変わるべきは大人。伺いますけれども、身近な大人の日常的な対応が、子どもや若者の自殺に向かう生きづらさをつくり出しているとの指摘について、区はどのように受け止めているのでしょうか、伺います。","respondent":"鷹箸保健予防課長","answer":"子どもの自殺の原因が決していじめだけではないということは十分認識しています。様々な原因がある中で、身近な大人や子どもが生きている身近な環境にあるということも十分認識しております。","voiceIndex":51,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"命を大切にとか、自殺は駄目との自殺予防教育だけでは効果があまりないと。２点伺いたいのですが、１つ目は、自殺予防教育についてですが、命を大事に的な道徳型ではなく、誰かに助けを求めることの大切さを学ぶとか、あと、ストレスの対処法、意外とストレスが自分にかかっているということに自覚がない人が多いのです。そのことを対策の中では重視していただきたいのですけれども、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"初めて表紙にあれだけ自殺予防、自殺の対応の重要さを取り上げていただいたところですか、まず寄り添う、相手の言ったことを「死ぬ気で考えれば」などと決して否定したりしないということは、まず一番重要なことだと考えていますので、多くの区民にそれを理解していただくように。","voiceIndex":53,"id":"exchange-023"},{"speaker":"くにば委員","kind":"提案","question":"本日は、２８１ページより、妊婦面談、これはオンラインによる妊娠期面談に関してと、母親学級、二人で子育てに関してです。は妊婦面談についてです。１点目が、２２週以降の切迫早産で安静が必要な方。２点伺います。そしてもう１点が、このオンライン面談の条件を緩和して、希望者全員がオンラインで相談できるようにしてはというご提案です。品川区でも拡充していかがでしょうか。こちらの２点を伺います。","respondent":"柏木品川保健センター所長","answer":"オンラインによる妊娠期面談についてのお問合せです。対象者の「その他」ですが、これは(1)から(3)以外の方で、ご相談の内容によって柔軟に対応するために、その他の(4)の設定をしています。無条件でですが、基本は、妊娠期面談は対面を原則というふうに考えてあります。","voiceIndex":56,"id":"exchange-024"},{"speaker":"くにば委員","kind":"提案","question":"特に今のオミクロンの爆発的な感染という中で、様々、同僚の方々であるとか、区役所の中でも、やはり感染してしまわれる方、意図せずにいると思いますし、そのような方々のご不安も考えて、可能な限り、希望者が少ないとしても、希望者にはそういったオンラインでの面談が受けられるようになればいいのかなというご提案で終わらせていただきます。そちらに関してお考えをお聞かせください。","respondent":"柏木品川保健センター所長","answer":"ただ、今後につきましては、他区の状況、利用者の方の声も聞きながら判断していきたいと考えております。","voiceIndex":58,"id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"２点目におっしゃいました直接のグループワークを通じた仲間づくりができるという部分は、当然考慮がされていて、大田区か横浜市、いずれかホームページ上で、オンラインの場合は、オンラインでグループワーク等をして仲間づくりができますというふうに書いてありました。！しながわ商い活性化事業」を実施しました。そこでお伺いします。そちらの現状の認識をお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"昨年１１月に実施しましたキャッシュレス決済ポイント還元事業です。こちら、ポイント還元率につきまして、予算５億円のうち２億８,２００万円ほどが執行になりまして、執行率といたしましては５６.５％という形になっております。","voiceIndex":60,"id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"現実、品川区でどういった状況なのかが分かりました。もう１点、本当はお伺いしようと思っていたところが、全国で既に実施した３０８の自治体のうち、既に２回目以降のキャンペーンを実施しているところ、実施する予定のところが、約３分の１の１２８に上るのです。","respondent":"遠藤商業・ものづくり課長","answer":"その後、ＰａｙＰａｙとも今回の検証も含めていろいろと相談させていただいて、この後、いろいろな都内でのデータが、２３区でも多くのところがやっていただいているので、そこのところを見ながら、今後どうしていくかという形になるので、ちょっとまだそこの先については。","voiceIndex":62,"id":"exchange-027"},{"speaker":"くにば委員","kind":"意見","question":"ただ、私が実感として感じたのは、これはキャンペーン期間が１か月だったのです。最後に、デジタル地域通貨です。ちょっと時間が短くなってしまいましたが、本区において、改めてデジタル地域通貨の令和４年度、そして令和５年度に向けた取り組みであるとか、事業者との話合いがどういった形で進んでいるのか、最後にお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"今回のＰａｙＰａｙの事業者とのやり取りで、デジタル通貨のいい部分と、なかなかハードルの高い面がいろいろ課題が出てきておりますので、実際に使われる事業者などと、今後もまた検討していければなというふうに考えているところです。","voiceIndex":64,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、２８２ページ、保健予防費から、障害者歯科健診と予防接種費、２９１ページ、環境費の環境指導相談費、２９２ページから２９３ページのリサイクル推進費、３０１ページの産業経済費、就業支援事業について、できるところまで伺います。２月２１日に厚労省から全自治体に通知があったと伺いました。コロナワクチンの３回目接種と子どもの接種に関することだと理解しております。","respondent":"高山健康課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"今後、広くこの障害者歯科健診が必要な方にご利用いただけるよう、引き続き、歯科医師会とも協議を進めながら、よい制度としていきたいと考えております。ただ、今回の５歳から１１歳の小児接種に関しましては、予診から接種までドクターが集団接種会場で行い、そこに看護師もつけるということで、医療従事者を人数を増やして対応するということで、現在、準備を進めておりますので。","voiceIndex":68,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。体調を崩される方からのご相談は、もちろん国も考えてほしいですけれども、区としても、最低限受け止めてほしいという考えでの質問です。生活者ネットとしても、今、その５Ｇ基地局を否定することはできないと考えていますが、少なくとも設置前に説明をしてもらうとか、相談窓口の設置、体調に影響が出た人への対応は、区としても考えていただきたいのですが、その辺について見解を伺います。","respondent":"河内環境課長","answer":"ただ、こういったご相談におきましては、どこにご相談されていいか分からないという場合もありますので、私どもの窓口に来られた方などにつきましても、そういった対応窓口のご案内も含めて対応しています。","voiceIndex":71,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"おっしゃるとおり、これは区としてどうにもできないことだなというのは理解しております。これについては要望にとどめます。次に、香りの害についてです。同じように児童相談費でいいかなと思っています。昨年の決算特別委員会では、教育委員会に対して学校への掲示を求めたところ、各学校には配布されたという答弁を得ました。ぜひ区の公共的な施設での活用を促すべきと考えますが、現状を伺います。","respondent":"河内環境課長","answer":"香りについては、いろいろな嗜好の場合もありますので、そういった周知全般につきましては、お困りの方に対しての非常に有効な手だてとなるとは存じますけれども、そういったところを注意しながら進めていく必要があるということで。","voiceIndex":73,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"私たちとしては、まだまだ内容に不満もありますし、本当に家庭用品品質表示法の指定品目に入れてほしいですけれど、今求めているのはそこではなくて、このポスター、５省庁連名で出されているポスターを区として活用してほしい、教育委員会としては、学校には配ったということなので、区としての活用を求めての質問なのですが、改めて伺います。","respondent":"河内環境課長","answer":"改めまして、活用につきまして検討を進めてまいりたいと考えているところです。","voiceIndex":75,"id":"exchange-032"},{"speaker":"吉田委員","kind":"提案","question":"ぜひ前向きに検討をお願いいたします。プラスチック削減について伺います。今年の１月１９日に、プラスチック使用製品廃棄物の分別収集の手引きが出されました。具体的に区としての分別収集の方策について、いよいよいろいろ考えなければいけないということかと思いますが、今、何か検討されていることがあったら伺いたいと思います。生活者ネットとしても、今どちらにすべきという提案はないのです。","respondent":"品川品川区清掃事務所長","answer":"大切なことは、区民に対していかに負担がかからないような分別をするかというところも大事な観点かと思います。こういったところもいろいろ検討しながら進めていきたいと、このように考えております。","voiceIndex":77,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"やっぱり区民への負担というものも、そういう視点もぜひ考えていただきたいと思います。ぜひその辺の仕組みも明らかにしながら、これから啓発が必要だと思うのですけれども、そういう仕組みも明らかにしながら、拡大生産者責任は区としてもぜひ国に対して主張していただきたいのですが、改めて伺います。","respondent":"品川品川区清掃事務所長","answer":"こういうものもなるべく使っていかないようにということで、これは各企業がいろいろと努力して、今、進めているような状況です。こういった面も総合的に捉えて啓発は進めていきたいと、このように考えております。","voiceIndex":79,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"言うのを忘れました。最後です。産業経済費の就業支援事業の中から、これについては、これまでずっと若者や女性への就業支援の相談について、継続して丁寧にやっていただきたいということを求めております。これまでも求めてきましたが、今の相談の状況、就労につながった実績を、今年度は、まだ３月のものが出ていないかと思いますが、分かるところまで教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"就業相談事業の相談を受けている件数ですけれども、現在のところ、１月の末までという形になりますが、利用人数といたしまして１８７件という形になっていまして、そのうちこちらで把握している就職決定の人数は２６件で、前年に比べますと。","voiceIndex":81,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"相談の件数が落ちているということですか。ここに来れば相談できるよというような周知はちゃんとされていると思いますけれども、落ちているということであれば、ぜひもっと拡充していただきたいと思いますが、コロナの影響もあって相談に来にくいということもあると思いますけれども、その辺の工夫も併せて教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"来年度から、オンラインなどもいろいろ考えて、より相談しやすい体制などを今考えているところですので、若者、女性という形なのですが、来年そういうものも取っ払いまして、いわゆる氷河期世代なども対象にしたものをやっていきたいというふうに考えているところです。","voiceIndex":83,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"私たちも象徴的に若者とか女性とか言いましたけれども、今、困難に陥っている方はたくさんいらっしゃると思います。オンラインは、これからなのですね、ぜひ活用していただきたいと思います。どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-037"},{"speaker":"木村委員","kind":"質問","question":"私からは、２７９ページの上から８行目、受動喫煙防止対策費、３９３万円余からお聞きいたします。お聞きいたします。区でも、法律や条例等に基づいて受動喫煙防止対策を進めていますが、現在の状況はいかがになっているでしょうか。お聞かせください。","respondent":"高山健康課長","answer":"引き続き表示状況を確認しつつ、この割合が限りなく１００％に近付いていくよう、引き続き啓発に努めてまいります。それから、取組みのもう１つとしては、やはり法律に基づく通報などを多数お受けしております。","voiceIndex":87,"id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"たまたまでしょうけれども、本区での歩行喫煙の状況は、どのようになっているのか、守られているのかどうか。お願いいたします。そして、この条例ができ、これを機会に、たばこをやめられて喫煙者数も少なくなったとのうわさもちらほらお聞きしました。自販機を含め、本区での販売量に影響はどのように出ているのか、お聞かせください。","respondent":"高山健康課長","answer":"ピークとなりますのが１９９６年ということで、その当時としては、３,４８３億本ということですので、この当時と比べれば、４分の１程度になっているのではないかというふうに考えておりますので、喫煙環境の減少とともに、たばこの販売件数については。","voiceIndex":89,"id":"exchange-039"},{"speaker":"木村委員","kind":"意見","question":"そして今度は、令和３年度は４７２万円余でしたけれども、令和４年度は３９３万円余の予算が組まれました。昨年より８０万円程度、減額予算ですけれども、健康増進法や受動喫煙防止条例等が、大きく影響していると思われますが、なぜ予算を減額されたのか、お聞かせください。","respondent":"高山健康課長","answer":"禁煙外来助成など、いわゆる卒煙に関する支援事業につきましては、これまでどおりの予算としておりますので、今後、法律や条例などが徹底されることで、こうしたかける経費が徐々に減らしていけるものと考えております。","voiceIndex":91,"id":"exchange-040"},{"speaker":"木村委員","kind":"質問","question":"たばこが売れることで、本区にも売上げの一部が税金として還元されるということですけれども、規則を守ることをぜひお願いしたいと考えています。次に、予防接種費、３７億１,７００万円余からの質問をいたします。ご存じのように、ワクチン接種をしながら、国内では丸２年を超え、今現在も猛威を振るっているところであります。これから先の見通しは、行政としてどのように読んでいるのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今、委員お尋ねの４回目についてです。報道ベースで私も拝見いたしましたが、先日、衆議院の厚生労働委員会で尾身会長が、４回目についても他国の状況を見ながら、これから少し精査をしていくというお話があった以上の情報は、区のほうには現在まだ下りてきておりません。","voiceIndex":93,"id":"exchange-041"},{"speaker":"木村委員","kind":"意見","question":"多分、四度目もあることと思いますけれども、早く収まることを願っております。コロナを抑えるには、医療従事者の協力は大変ですけれども、私は絶対的に国民一人ひとりがコロナとしっかり向かい合い、規則を守ることが大きな力になり、また特効薬になると思いますけれども、最後にそのお考えをお聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"感染が一刻も早く収まることは当然期待はしております。そのためにもワクチン接種、できる限り早く希望する方が打てるように、区としても体制を万全で整えてまいりますので、どうぞご協力のほどよろしくお願いいたします。","voiceIndex":95,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"２８７ページの感染症対策事業についてお聞きします。区が行う感染症対策の目的と役割は何なのかをお答えください。そして、区民の皆様方に対して、何をすべきなのかということもお答えください。","respondent":"鷹箸保健予防課長","answer":"そのために、感染された方の隔離ですとか、感染拡大防止のために、ワクチン接種のお話がありましたけれども、普及啓発、治療、隔離、その辺を含めてしっかり対応していくところが感染症対策の目的、また方法だというふうに考えております。","voiceIndex":98,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"もっと深いところからのお話を私は聞きたかったのですが、いろいろな今おっしゃっていたことは、私は、区民の皆さんの安心して生活ができるための様々な方法論だと思うのです。今、安心して暮らせているのだろうか。では、その安心に対してはいかがですか。","respondent":"鷹箸保健予防課長","answer":"感染症対策と安心・安全ですか。端的にお答えするのが非常に難しいのですけれども、やはり感染症を予防すること、感染症にかからないことによって、これまでどおりの生活を送れること、それが一番重要なことかと思います。","voiceIndex":100,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"この安心というふうに思っていただくために、どういうことが必要なのかということを踏まえて、来年度、令和４年度の保健所の体制強化ということがありますけれども、どういう形で安心を得られるようにしていくのか。今どういうところに一番区民の皆様方は不安に思って、どうしてほしいのかということを、皆さん、どういうふうに思われているのかのお考えをお聞きします。","respondent":"鷹箸保健予防課長","answer":"いま一度、ご指摘のとおり、非常に分かりやすいホームページをつくっている自治体等もありますので、そういったところと、あるいはまた広報広聴課とやはり連携、迅速な頻回な更新とともに、分かりやすくお届けするということを主眼に対応していますが、一方。","voiceIndex":102,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"第一歩なのです。この第一歩をどうすればいいのですか。例えば、どこに問い合わせればいいの、保健所ですか、保健所はしませんよね、かかりつけ医ですか、いや、私、かかりつけ医を持っていません。どこに連絡をするのですか。このみなし陽性は、おかしくないですか。非常に現場のお医者さんも大変だなと私は思っていますけれども、まず最初に、どこにコンタクトをとったらいいのですか。","respondent":"鷹箸保健予防課長","answer":"臨床診断につきましては、コロナに限らず、これまでも多くの感染症、麻しん、風しんでも臨床診断という診断の方法はありますので、決してこのみなし陽性がいいかげんなものというふうには我々は考えてございませんし、このみなし陽性の考え方については。","voiceIndex":104,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"再度お聞きしますけれども、最初に誰に聞いたらいいのですか。熱が出ました、誰に私は相談すればいいのですか。かかりつけ、私はかかりつけ医がいますからかかりつけへ行きますけれども、でも、電話がかからない、どうしたらいいのですかということです。それと、家族の濃厚接触者は、ＰＣＲ検査とか検査しなくていいのですよね。食料が届かないのです。そういう場合はどうしたらいいのですか。","respondent":"鷹箸保健予防課長","answer":"コロナを前提でお話しになっておりますけれども、本来、何か具合が悪ければ、ご自身で判断されて、電話相談をするなり、かかりつけ医がいない方については、近所の医師に相談するなりという本来の対応は、別にコロナ以外でもまずはやっていただきたいと思います。","voiceIndex":106,"id":"exchange-047"},{"speaker":"松澤委員","kind":"質問","question":"私からは、２７５ページ、健康づくり支援事業費の中の健康ポイント事業、そして２８１ページの乳児健康診査、それと母子歯科衛生事業、時間がありましたら、２８５ページのがん検診普及事業について質問いたします。今年１月、厚生労働省から、介護を受けたり、寝たきりになったりせずに、日常生活を送れる期間を示す、いわゆる健康寿命について発表がありました。","respondent":"高山健康課長","answer":"今年度からは、これまで活動量計という高性能な万歩計のようなものを絶えず携帯していただくというところに加えまして、それ以外の方々には、スマートフォンのアプリをお選びいただけるというような。","voiceIndex":110,"id":"exchange-048"},{"speaker":"松澤委員","kind":"質問","question":"今、ご説明の中で、万歩計でしたか、来年度、万歩計からスマートフォンのアプリに参加方法を統一する、そういったようなお話があったと思いましたけれども、スマートフォンのアプリ、要はスマホに統一することによって、どういったメリットがあるのか。そういったサポートが必要な方、そういった対応になると、どういったものがあるのでしょうか。","respondent":"高山健康課長","answer":"これまでも健康課の窓口にお越しいただければ、個別な対応などもしていますので、今後もそうしたお困りになっている方には、丁寧に寄り添った対応をしてまいりたいと考えております。","voiceIndex":112,"id":"exchange-049"},{"speaker":"松澤委員","kind":"質問・要望","question":"コストを抑える、コストを抑えて、また参加人数の上限はフリーなので多くの区民の方が参加できる、そういった事業を目指しているということを確認しました。そういった中で、やっぱりもっと、人はいろいろ望むではないですか。ランニングです。","respondent":"高山健康課長","answer":"ランニングにつきましては、歩数のカウントなどに特段支障がなければ、そういったものも１つ要素としては面白いかなというふうに思いますので、いずれにしましても、一本化することによって、事業についてはいろいろと広がりが出てまいりますので。","voiceIndex":114,"id":"exchange-050"},{"speaker":"松澤委員","kind":"質問・要望","question":"広報を行うとアプリのダウンロード数が伸びる、そういった現状をしっかりと継続して、さらなる充実を要望しまして、次の質問へいきます。次に、２８１ページの乳児健康診査の中から、３歳児健康診査についてお尋ねいたします。これは会派でも長く要望していたものであって感謝しております。そこで、これまでの視力検査とどのような点が変わるのでしょうか。課題などがあればお聞かせください。","respondent":"柏木品川保健センター所長","answer":"現在は、既に屈折検査を導入している複数の自治体を視察しております。今後は、視察の内容を基に屈折検査の方法や順番、あとは導入に向けての課題の整理も含めて検討しまして、品川区医師会、荏原医師会とも相談しながら導入を進めていきたいと考えております。","voiceIndex":120,"id":"exchange-051"},{"speaker":"こんの委員","kind":"質問・要望","question":"昨年の決算特別委員会の総括質疑において、自動判定機能付きフォトスクリーナーを資料提供して、３歳児の健康診査における視力検査の屈折検査の導入を求めて、遡ること２０１８年より求め続けてきて、やっと来年度の予算に新規事業として視覚屈折検査が導入される運びとなったことは大変に評価しております。検査実施に伴う事前の準備、研修、どのようなことが行われて、どのように準備をされているのか。","respondent":"柏木品川保健センター所長","answer":"その整理をした上で、医師会とも相談し、あと、国の補助金が出る予定になっておりますので、ちょっとまだ詳細は不明ですけれども、それを待って機器の購入、それと、実際、検査するときのシミュレーションとか、実際に検査する人の研修等を進めて、下半期。","voiceIndex":125,"id":"exchange-052"},{"speaker":"こんの委員","kind":"確認","question":"それで、周知の方法として、健診の通知の中に入れていただくということですけれども、この屈折検査、なぜこの検査が必要なのかというところは大事なところだと思いますので、その点、よろしくお願いしたいというふうに思います。この検査は、もう１回確認ですが、家庭でやる検査を持って検査場に来て、それで全員この屈折検査を行うという理解でいいのか、もう一度そこの点を確認させてください。","respondent":"柏木品川保健センター所長","answer":"今、委員ご指摘のとおりです。視力検査、それと全員に対して屈折検査を実施いたします。","voiceIndex":127,"id":"exchange-053"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問に参ります。次は、精神保健事業についてお聞きしたいと思います。その場合、入院制度としては、現在、大きく分けて３つあると聞いております。参考までに、区における入院制度の利用の現状について、各入院の件数などが分かりましたら教えていただきたいと思います。各入院の際の移送費用について、負担先はどのようになっているのか、負担額なども分かりましたら、お知らせいただきたいと思います。","respondent":"榎本荏原保健センター所長","answer":"措置入院ということで入院になっている患者は、全体には、警察官から通報される状況では７０件ほどあるのですが、年間約３０件ぐらいが措置入院になっております。その場合は、警察官の方が一緒に病院に行くということが多い状況になっております。","voiceIndex":129,"id":"exchange-054"},{"speaker":"こんの委員","kind":"確認","question":"それぞれの入院体制の状況を確認させていただきました。なぜそのように高額なのかと伺いますと、ご相談者曰く、症状によっては大きな男性五、六人で対応しないと患者を移送することができないということで、入院が必要になるのは突発的なことなので、この高額な移送費用を工面するが大変に厳しい、困っているというご相談でありました。","respondent":"榎本荏原保健センター所長","answer":"保健センターといたしましては、例えばですが、在宅の往診の先生に行っていただいて少しずつ病状を改善していく中で、ご本人との関係づくりなどを行って、その上でご本人も了解して。","voiceIndex":131,"id":"exchange-055"},{"speaker":"こんの委員","kind":"質問・要望","question":"訪問医あるいは看護師の方がご本人と人間関係をつくってということですが、なかなかそこに時間もかかるし、やっぱりいざとなったときの移送費用が必要ということですので、今後そうしたことも考えていただければ、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、予算書の２８７ページ、感染症対策事業から新型コロナウイルス感染症対策、２８３ページ、定期予防接種から子宮頸がんワクチン、２８１ページ、乳児健康診査から新生児聴覚検査について、順次お尋ねしてまいりますので、よろしくお願いいたします。新型コロナウイルス感染症対策についてお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"ただ、感染者数が非常に多いため、単純に数だけで見ると、入院数はそんなに減っていないという辺りも今回のオミクロン株の特徴かと思います。","voiceIndex":135,"id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"意見","question":"新型コロナウイルス感染症対策アドバイザリーボードは、オミクロン株の特徴を踏まえた効果的な対策の中で、オミクロン株はデルタ株を含めたこれまでの新型コロナウイルスとは異なる感染症として捉えるべきであると述べています。病気の傾向を見ますと、従来の新型コロナウイルス感染症は、約５日の潜伏期の後に、発熱、咳、倦怠感、味覚・嗅覚障害などの症状が１週間ぐらい続き、その後、軽快します。","respondent":"鷹箸保健予防課長","answer":"もともと、特に高齢者ですが、コロナ感染を理由に入院されたのですが、高齢者ということで、もともと持病があったりということで、入院を契機に持病が悪化したり、コロナ感染拡大の可能性はなくなっても、感染力はなくなっても。","voiceIndex":137,"id":"exchange-058"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ワクチンの発症予防効果では、オミクロン株に対しては、２回接種後、約７０％の発病予防効果が、６か月後には１０％ぐらいまで低下してしまいます。そのため、昨年暮れから既にワクチンの効果がなくなった高齢者が品川区でも増えている状況の下で、１月に爆発的に第６波の感染爆発が始まりました。ワクチン追加接種と並んで第６波を収束させるためには、治療薬による治療が必須です。","respondent":"鷹箸保健予防課長","answer":"投与方法としては、点滴ですとか服薬、経口などがありますが、それぞれ症状や重症度に応じて使い分けることになります。区内の治療実績、投与実績につきましては、報告するシステムになっていないことからも、区として把握はしてございません。","voiceIndex":139,"id":"exchange-059"},{"speaker":"鈴木（博）委員","kind":"確認","question":"投与する医師も登録が必要です。品川区の実績を伺いましたが、残念ながら把握されていないようですので、現在の薬物療法は誰でも行える治療ではないため、今ご紹介したような治療は一部の患者に限られている点だけ確認したいと思います。次に、子どものコロナ患者についてお伺いします。子どものコロナウイルス患者の症状の特徴、入院した事例があったのでしょうか。お答えをお願いいたします。","respondent":"鷹箸保健予防課長","answer":"子どもの陽性の場合の症状ですけれども、発熱、咳、鼻水などの症状がありますが、いわゆる風邪と区別がつかない軽症なものというふうに把握しています。入院したという報告は、オミクロン株になってから、私どもとしては受けておりません。","voiceIndex":141,"id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"しかし、子どものコロナ対策については、現状でよいのでしょうか。次に、定期予防接種から子宮頸がん予防のＨＰＶワクチンについて、時間がないので１つだけお伺いします。このような点をはっきり説明すること、それゆえにこそ、これらの人々には、２次予防として子宮頸がん検診をしっかり受けていただくこと、この点を区はしっかりと説明するべきだと思いますが、区のご見解をお伺いします。","respondent":"高山健康課長","answer":"子宮がん検診につきましては、２０歳以上の偶数年齢でお受けいただくということで、区はこれまでも二十歳の成人式の折に検診受診を勧奨するほか、お誕生日の前日に個別の受診券の送付、それから、その後、勧奨通知という形で。","voiceIndex":143,"id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"確認","question":"私からは、２８７ページの猫の不妊・去勢手術費助成に関わって、地域猫について伺いたいと思います。今言った猫の不妊・去勢手術費助成、ここから地域猫の質問に入るわけですけれども、地域猫、そして地域猫活動への事業の予算は、特化して組まれてはいないということでいいのでしょうか。確認をさせてください。","respondent":"鈴木生活衛生課長","answer":"ご質問の地域猫に関する対策につきましては、予算書の中で、猫の不妊・去勢手術費助成という項目で出ておりますが、その他の啓発や活動団体の支援経費も全てここに含まれているものです。","voiceIndex":146,"id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。本当に多くの方が、不妊治療も全額助成ではないですし、そして、そうしたケージとか医療費、そうしたことに身銭を切っている状況があるので、ぜひその仕組みをつくるべきだと思いますし、国や都もガイドラインを出して進めようと言っているわけですので、国や都にも予算の確保を求めるべきではないか、していただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木生活衛生課長","answer":"今ご質問にありました経費面での支援とか、それからガイドラインの作成、また、いろいろな啓発ですけれども、実際には、予算書の項目では、猫の不妊・去勢手術費助成というタイトルになっておりますが。","voiceIndex":148,"id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、病院にかかる治療費、またケージの購入費、そしてえさ代、こうしたものにも使えるということでいいのでしょうか。","respondent":"鈴木生活衛生課長","answer":"現在、実際に経費の補助として対象にしているのは、このタイトルにある去勢手術、それから、モデル地区に関しては、その保護等に係る必要な医療の経費、それから、えさ代に限定はしていないのですが、いろいろな資機材が必要な場合の経費なども想定をしています。","voiceIndex":150,"id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ予算の支援をしていただきたいと思いますが、いかがでしょうか。だけれども、そこまでいかないという地区もあると思うのですけれども、その１０頭を超えてしまう地区に、そこまで使わない地区の不妊・去勢助成費用を充てていくということはできないのかということを相談されたのですけれども、その流用の仕方というのですか、柔軟性、そこはどうお考えでしょうか。","respondent":"鈴木生活衛生課長","answer":"その使い勝手の部分ですが、基本的には、おおむね地域猫活動に必要な経費は対象として想定しておりますので、それ以外の部分については、一律にお渡ししたり、基準を定めるのではなくて、活動の中で意見を聞いたりしながらご相談をしていますので、現在では。","voiceIndex":152,"id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、区のほうにも、もう少し力をかしてほしいというのが、結構複数の方から声が寄せられました。やっぱり地域だけでは対応し切れない。やっぱりそこに区も関わってほしいという声が結構出されたのです。やはり地域住民の同意を得るということがガイドライン等にも載っていますので、そこにはやっぱり今、区が入っていかないと駄目なのではないかと思うのですけれども、ここはどのようにお考えでしょうか。","respondent":"鈴木生活衛生課長","answer":"委員へのご相談者の方がご存じなかったのかもしれませんが、区では、地域でのそういう問題と取組みについてのご相談があったときには、町会の会議の場をかりたり、また、当事者の方とお会いして、そういう情報を伝えたり、調整をするということに取り組んでいるところです。","voiceIndex":154,"id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"意見","question":"ちょっと地域の方と実感が違うのだと思うのです。なので、ぜひ国も都も区も掲げている事業ですので、もうちょっと地域の状況を聞いて、積極的に協力をしていただけたらなというふうに思います。本当に多岐にわたる作業が、地域に地域活動としてやることというふうに課せられているというか、地域でやられているのです。そこにもうちょっと区が力をかしてほしいということですので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問","question":"猫のお話で、多くの委員がいろいろご質疑されていました。これらの自治体のこういった成功している、あるいは、参考になる点があると思うのですが、こういった方策を品川区はなかなかすぐに導入できないいろいろな事情と、それから、それに伴う品川区としての今後のこの問題に対する方向性をお伺いします。","respondent":"鈴木生活衛生課長","answer":"そのような中で、今、品川区では、先ほども説明しましたように、町会を中心とした地域全体での取組みということで、モデル地区を進めているところです。","voiceIndex":158,"id":"exchange-068"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"次は、公衆浴場です。地域の関わりが少ないというのが残念ながら実情です。なぜここの款でお話ししたかというと、区立公園での掃除をふれあい作業などが実施していますが、担当課の障害者福祉課が、公衆浴場に働きかけて、清掃業務の委託先として開拓していくのは、なかなか難しいと思います。その委託料の一部を区が助成をすれば、公衆浴場、銭湯経営の継続支援にもつながると考えますが、いかがでしょうか。","respondent":"高山健康課長","answer":"仮にそうしたお話があるとすれば、健康課といたしましては、これまでも委託事業などを公衆浴場の団体と結んで事業等を展開してきておりますので、そうしたお声を伝えていくことは十分できるかと思いますので、その上で双方が思いを同じくしてくだされば。","voiceIndex":160,"id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"提案","question":"声があればではなくて、公衆浴場で、こういうふうな手が、作戦がありますと、そういうものを浴場のオーナーなどに提案していただいて、そういうものはいかがですかと言っていただかないと、障害者福祉課が銭湯にアプローチになかなか行けない部分もありますし、オーナーもそういうものがあるということが分からないと思うのです。","respondent":"高山健康課長","answer":"積極的にという意味でのご提案だと思いますので、様々、銭湯も経営上の思いなどもありますでしょうから、その中で、こうしたことを話題にした上で、そうした経営者側のご理解が得られるかどうか、今後探ってまいりたいと考えております。","voiceIndex":162,"id":"exchange-070"},{"speaker":"高橋（し）委員","kind":"意見","question":"非常に貴重なコンテンツをお持ちなので、活用をお願いいたしたいと思います。モンゴル高専の件です。それからもう１つは、ＴＯＣの建て替えによって、一時的にかなり事業者が西五反田周辺、五反田から少し去ってしまうことによるその地域の活性化、にぎわいという観点での懸念とＴＯＣが完成した後の、その後のにぎわいへの期待、その辺りをお願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"一時的には、当然いなくなってしまうので、にぎわいという部分では厳しいところはあろうかなと考えていますけれども、５年後にはまた新しい建物、立派なものができるというふうに聞いておりますので、地域のにぎわいにどのようにつなげられるか。","voiceIndex":164,"id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"意見","question":"モンゴルとの交流は、あまり目立たない話ですけれども、他の自治体にはない非常に有効な、本当に独自のすばらしい施策だと思います。コロナの中でも何とか続けていける見通しがあるので、ぜひ継続してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":166,"id":"exchange-072"},{"speaker":"西村委員","kind":"質問","question":"２７９ページ、母子健康診査費、３０１ページ、創業支援センター等運営費、３０７ページ、商店街店舗支援事業を順不同で伺ってまいります。母子健康診査費より、項目はありませんが、産婦健康診査事業について伺います。改めてこの産婦健康診査事業がどのようなものか。今、区内に産後２週間、１か月後健診を受けていらっしゃる方がどれぐらい受けておられるか把握をしておられたら、教えてください。","respondent":"高山健康課長","answer":"本事業は、産後２週間、それから産後１か月など、出産後間もない時期の産婦に対する健康診査の費用を助成することによりまして、産後の初期段階における母子に対する支援を強化し、妊娠期から子育て期にわたる切れ目ない支援体制を構築するといった趣旨の事業と認識しています。","voiceIndex":168,"id":"exchange-073"},{"speaker":"西村委員","kind":"質問","question":"この平成２９年度に創設された産婦健康診査事業は、自殺防止はもとより、児童虐待の防止のため、マタニティブルー、産後鬱の早期発見などの産後のメンタルケア、産後ケア事業につなげる入り口として、産後鬱対策の導入としても重要な事業だと考えます。今、区内で産後１か月以内の母親にアプローチできる事業はあるか、どのようなものがあるのか伺います。","respondent":"柏木品川保健センター所長","answer":"産後１か月以内に母親にアプローチしている事業ですけれども、品川区では、産後２週間から約１か月の間に、助産師のほうで、産後全戸電話相談を実施しております。これが委員ご指摘の１か月以内に母親にアプローチできるものと考えています。","voiceIndex":170,"id":"exchange-074"},{"speaker":"西村委員","kind":"質問","question":"改めまして、助産師からのお電話があるということで伺いました。今年１月２１日、総務省から厚生労働省宛てに、子育て支援に関する行政評価・監視─産前・産後の支援を中心として─という勧告が出されているのを拝見しました。どのような勧告か、また、広域連携についても勧告が出されていますが、導入にあたってどのような課題があるのか伺います。","respondent":"高山健康課長","answer":"導入にあたっての課題という点のご指摘ですけれども、やはり妊娠して出産するのは、必ずしも１つの区域内で完結しないということから、やはり区内で妊娠出産などを行った場合ですと、その状況の把握などは比較的容易になってくるのですが、やはり里帰り出産も含めて、区外など。","voiceIndex":174,"id":"exchange-075"},{"speaker":"西村委員","kind":"質問・要望","question":"このことに関しましては、引き続き私も研究をしまして、区としても動向を注視していただけますようお願いしたいと思います。これは要望ですが、産後ケア事業に関しても勧告が出されておりまして、区の産後ケア事業に関しましては、他区の状況もお調べいただきながら、宿泊事業、宿泊型の利用期間の延長の要望をさせていただきたいと思います。次に、商店街店舗支援事業を伺わせていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの事業ですが、いわゆる中小小売商業者等のグループが、例えば、商店街とか、今みたいないわゆるグループのブランド力向上を意図して、新たに共同開発する制作物、その周知等に係る経費を補助するということで、個店および商店街の活性を図るというものでございまして。","voiceIndex":176,"id":"exchange-076"},{"speaker":"西村委員","kind":"提案","question":"どうぞ引き続きご支援のほどをよろしくお願いいたします。次に、創業支援センター運営費について伺いたいのですが、この２月に改修したばかりの西大井創業支援センター、利用者のキャンセル待ちもある大崎の「ＳＨＩＰ」、女性に特化した「ＭＵＳＡＫＯ ＨＯＵＳＥ」と、区では創業支援センターを立ち上げていただいており、区民委員会でも視察に行かせていただきました。ご意見を伺います。","respondent":"遠藤商業・ものづくり課長","answer":"西大井創業支援センターのいわゆる地域課題への貢献という部分です。","voiceIndex":178,"id":"exchange-077"},{"speaker":"西村委員","kind":"質問","question":"他区の方に伺うと、こういった自治体がつくるこういったセンターというのは、古めかしかったり、古い会議室だったりするというところもたくさんあるそうで、本当にきれいなセンターを立ち上げていただいておりますので、大変期待をしております。この特色のある３つの創業支援センターを取り巻く今後の展開ですとか、この３つの連携の取組みがあればお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"先ほど言った今年の２月で３つの創業支援センター、全て工事が終わりまして、実際に運営を開始したところです。","voiceIndex":182,"id":"exchange-078"},{"speaker":"西村委員","kind":"質問","question":"２４０人もいらっしゃるということで驚きました。実際にＭＵＳＡＫＯ ＨＯＵＳＥで起業をスタートさせまして、ＳＨＩＰにオフィスを移動して事業を拡大しているという女性起業家の方もいらっしゃいます。武蔵小山創業支援センターですけれども、こちらは女性の起業に特化しているということで、女性の起業支援の効果と課題をどのように区は捉えておられるか伺います。","respondent":"遠藤商業・ものづくり課長","answer":"女性の起業支援の難しさですが、やはり子育てをしながらというところで、十分に時間がとれないという方、その隙間を見てやられている方が多いため、そこでうまくいかないというところで、こういうやり方はどうだとかと。","voiceIndex":184,"id":"exchange-079"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほど課長もおっしゃられていましたが、女性の起業は小規模スタートの方も多く、事業拡大志向がなかなか低いと特徴などもあると言われておりますので、ぜひともそのような就職支援、起業から転換していくというふうなところの支援にも今後力を入れていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-080"},{"speaker":"若林委員","kind":"質問・要望","question":"情報発信側の送り手の思いと、受け手の側の理解の仕方、捉え方があるという中で、区民へのお知らせ、最終的には、広報物、ホームページとか、広報しながわとか、その他もろもろというものに、そういう具体的な媒体、ツールになると思うのですけれども、こういったものの工程というのは、どういう工程をたどって最終的に区民の目に触れていくのかということを教えていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"おおむね締切りは一月前、どんなに近くても２０日ぐらい前にと決められているのが現状でございまして、大変急ぐものについては、それまであったところにちょっと隙間をいただいて、１０日ぐらい前に入れられる場合もありますけれども。","voiceIndex":188,"id":"exchange-081"},{"speaker":"若林委員","kind":"質問・要望","question":"これは見直しとかということではなくて、庁内全体で、対策本部もあると思いますので、そういうところでしっかりと一日も早く、いい方法があれば着手をしていただきたいなというふうに要望をします。それからもう１つ、うがいのほうは、そういうことなのですね。そうすると、保健所としては、この通知は正しいのでしょうか。マルなのかバツなのか三角なのか、１回ご見解をお聞かせください。","respondent":"鷹箸保健予防課長","answer":"元品川保健センター所長で母子保健を担当していた立場から言いますと、歯科保健の観点からいえば、食後の歯磨きは非常に重要だと考えています。","voiceIndex":190,"id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、２７４ページの健康推進費から、性と生殖に関する健康と権利、リプロダクティブ・ヘルス・アンド・ライツの視点に立った取組みについて、それから、中小企業支援から事業復活支援金の手続きのサポートについて伺いたいと思います。女性の健康と権利を守るためのリプロダクティブ・ヘルス・アンド・ライツを位置づけて具体化することが求められていると思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"品川区の健康増進計画でありますしながわ健康プラン２１の中に、リプロダクティブ・ヘルス・アンド・ライツの考え方を位置づけてはとのご提案かと思います。","voiceIndex":193,"id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"単なる知識不足ではなくて、体の仕組み自体を正しく理解していないために、ネットで調べてさらに不安になる。伺いたいと思いますが、望まぬ妊娠の相談を、品川区では、どこでどのように受けられているでしょうか。そうした相談は何件ぐらいあるのか。その望まぬ妊娠という状況が、どのような状況になっているのか、件数とかも含めて把握をされているのか、その推移はどうなっているのか、伺いたいと思います。","respondent":"柏木品川保健センター所長","answer":"専門機関を紹介した場合も、紹介しておしまいではなく、その後も保健センターのほうで、相談者に寄り添った形で引き続き対応しています。","voiceIndex":195,"id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういう相談をＮＰＯ法人に頼るだけではなくて、私は、区としても相談窓口を設けて、望まない妊娠、困った、どうしよう、こういう方に寄り添った相談体制をつくることが必要なのではないか、専門機関先の相談だけではなくて、ＳＯＳを出せる相談体制が必要なのではないかと思うのですが、いかがでしょうか。","respondent":"柏木品川保健センター所長","answer":"その体制ですが、窓口を全部保健センターに整備というよりは、やはり全庁的に連携をとりながら対応していくことがいいだろうと考えています。","voiceIndex":197,"id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２０２０年６月、公衆トイレで出産した学生が、保護責任者遺棄致死罪と死体遺棄罪で起訴されて有罪になった。こういうところにしっかりと目を向けて、そういう方を相談に応じますよという体制、そういう保健所としての姿勢を示すということが求められていると思うのですけれども、いかがでしょうか。こういう状況をなくすために、区としては、どのような対策が必要と考えるかお聞きしたいと思います。","respondent":"柏木品川保健センター所長","answer":"ただ、どうしても周りの方からも気づかれず、自分も声を上げにくいという部分はありますが、改めて保健センター等で相談いただける体制もありますので、そういう部分は、いろいろな場所を通じて周知をしていきたいと考えています。","voiceIndex":199,"id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう教育を受けないで育っているという大人もたくさんいるわけですから、それに対しての健康教育も必要だと思います。私が相談を受けたのが、この確認機関のところにお願いをしたら、３万円かかるよ、１万円かかると。この仕組みを区としても、こういう方はほかにもいらっしゃるのではないかと思いますので、仕組みとしてつくっていただきたいと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"どうしても駄目だというところ、あるいはなかなか難しいという場合につきましては、ビジネス・カタリストという制度を使いまして、専門家の派遣という形で対応させていただいているところです。","voiceIndex":201,"id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それを相談して初めて分かるのではなくて、区としてそういうことをやっているということで周知していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-088"},{"speaker":"渡部委員","kind":"質問","question":"３０３ページの中小企業事業資金融資あっせんのところと、３０５ページは販路拡大支援事業のところで商業の件で伺うのと、２９１ページは環境学習交流施設のところで少しお伺いをしていきますが、品川区に事業所があって、例えば品川区ではないところにまた事業所があってという会社の方々のお話とかだと、本当に品川区はよくやっていただいている。","respondent":"遠藤商業・ものづくり課長","answer":"新しく借りるという形になるので、いわゆる信用が変わらない、かつ、１年間の支払猶予といいますか、据置期間などもできるような形の仕組みをとっておりますので、こういう部分をいろいろと組合せて使っていただいて。","voiceIndex":205,"id":"exchange-089"},{"speaker":"渡部委員","kind":"質問・要望","question":"そこでつまずくと、その会社は飛んでしまいますから、そういうことであれば、その借換えという制度をしっかりご説明をしていただいて乗り切っていただきたいなと思います。そこでまた地元の仲間たちに会ったりとか、いろいろな方が大勢来ていて、そこでマッチングされれば、区の産業も振興していくのだろうななどと思ったのだけれども、その在り方も、これからどうなのですか、状況を教えていただきたい。","respondent":"遠藤商業・ものづくり課長","answer":"先ほどの、品川パピリオンのほうですけれども、ちょうど来週の水曜日から、ビッグサイトでやる予定になってありますが、こちらにつきましても、やはり品川区のブランドというところで、一緒にやることでのメリットはかなり大きいというふうに感じているところですので。","voiceIndex":207,"id":"exchange-090"},{"speaker":"渡部委員","kind":"質問・要望","question":"６年前だったか８年前だったか忘れたのですけれども、目黒区がすごい図鑑みたいなものを作って、それは課長に見てもらったのですけれども、品川区もこれから何か、そういう環境学習交流施設というものをつくって発信していくのであれば、いわゆるこの品川区内の自然とか、調査してみたりとか、民間の人、地域の人とかの助けもいただいて、どんどん盛り上げていってほしいと思うのですが、どうでしょうか。","respondent":"河内環境課長","answer":"エコルとごしは５月に開設予定ですが、その際にオープニングイベントに際しましても、戸越公園の自然を生かしましたネイチャーゲームなどを行うとともに、大型映像展示なども含めまして、区内に生息する鳥類や植物、昆虫類を含めました常設展示なども取り入れているところです。","voiceIndex":209,"id":"exchange-091"},{"speaker":"渡部委員","kind":"質問・要望","question":"そういう冊子といいましょうか、リーフレットとかを作るときに、実は、紙１枚もらうと、その場は確認をするのですけれども、それは大体ごみになってしまうのです。できれば、簡単なものでいいから、ちょっと冊子でポケットに入るようなもので、できれば筆記ができたりみたいなもの、環境学習交流施設というところであれば、そういうもののご用意もしてほしいなという要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-092"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、２９７ページ、収集運搬作業全般についてお伺いします。そして今回の分担金なのですけれども、２３区全体だと、令和４年度が３９０億円で、令和４年度が４２０億円と、３０億円の増額。品川区においても、令和３年度が１５億９,４３０万円だったのが、令和４年では１７億７,８９２万円と２億円弱の増額となっております。この分担金の増額につきまして、その理由をお伺いしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"この背景につきましては、一部事務組合で清掃事務所を持っているのですが、やはり随分前につくった清掃事務所は大分老朽化をしているというところがあります。こういった施設の建て替えの部分、それからメンテナンス費用の部分、それからメンテナンスについても、最近はやっぱり建築資材とか、そういうものも高騰している部分、こういったところが背景になって。","voiceIndex":213,"id":"exchange-093"},{"speaker":"湯澤委員","kind":"質問","question":"清掃一部事務組合管理者の山崎江東区長からも、対策を考えるというふうに伺っております。その対策とは何とか、お尋ねしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"この辺につきまして、各関連する企業、それから清掃工場のほうもそうですけれども、こういった部分のところを総合的に見て、手数料改定を進めていく予定です。","voiceIndex":216,"id":"exchange-094"},{"speaker":"湯澤委員","kind":"意見","question":"一時的には、今おっしゃった一般廃棄物の手数料の値上げ、そういったところでまかなえるとも思うのですけれども、根本にあるのは、先ほどもご答弁にありましたように、工場の老朽化かと思います。現在のごみの量であれば、工場を減らすという議論も出てくるのかなというふうに考えますけれども、それに対する本区のお考えをお知らせください。","respondent":"品川品川区清掃事務所長","answer":"これは一部事務組合のほうでの基本的な清掃工場の計画というものがあります。これに則って進めているという面がありますので、やはり一部事務組合の状況を見ながら、動きを見て、声を出すべきところについては、やはりいろいろ意見をしていこうと、このように考えております。","voiceIndex":218,"id":"exchange-095"},{"speaker":"湯澤委員","kind":"質問・要望","question":"一部事務組合ですけれども、２３区の考え方がそれぞれありますし、また、対応も１つにはならないと思いますが、担当課長会でも、し尿処理場や税外収入など、そういった様々な意見を出していただき、議論していただくことを要望させていただきたいと思います。来年度より、粗大ごみからのリユース事業が新規計上されております。この事業は、どのように運営をされていくのか。","respondent":"品川品川区清掃事務所長","answer":"そういった中で、どのようにやっていくかというところも、今後、業者選定をしまして進めていきたいと、このように考えております。","voiceIndex":220,"id":"exchange-096"},{"speaker":"湯澤委員","kind":"質問","question":"こちらのリユースの事業に関しましては、持込みというふうにお聞きしていますけれども、取りに来ていただく、そういったものに関しても、リユースの需要があるのではないかと思うのですけれども、そちらも今後は検討されるのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"粗大ごみとして出された中でリユースできないかというところで進めていきたいと思います。","voiceIndex":222,"id":"exchange-097"},{"speaker":"湯澤委員","kind":"確認","question":"こういった事故は、本当になるべく少なくあってほしいと思うのですけれども、区内ではどのぐらい年間に起きてしまっているのか、また、分かれば２３区ではどうなのかということと、あとは、このような事故を防止するために、どのような取組みが行われているのか、そして町会とか商店街でこういう分別活動をされている方への支援も必要になってくるのではないかと思いますが、お考えをお知らせください。","respondent":"品川品川区清掃事務所長","answer":"そこの中で、ガス缶とかライターとか、そういう部分については、袋を分けて、中にもしガスが入っている場合については「ガスが入っています」というような表記をしていただいて出していただくというふうにごみの出し方には書いてあるのですけれども。","voiceIndex":224,"id":"exchange-098"},{"speaker":"湯澤委員","kind":"質問・要望","question":"町会、商店街、そしてマンション組合とか、そういったところにご協力いただいているところもあると思うのですけれども、さらにそういったところの掲示板とか店舗とか、そういったところに、今課長がおっしゃられたようなポスター、そういったものを掲示していただくなどして、ぜひ区民のごみ出しへの意識向上に取り組んでいただきたいと思うのですけれども、最後、ご答弁いただければと思います。","respondent":"品川品川区清掃事務所長","answer":"こういった方たちも、うまく協力して、それから町会とも協力しまして、随時こういった啓発活動を進めて、ごみの分別がしっかりできるように、それから、こういった火災等、事件がないように周知もしていきたいというふうに考えております。","voiceIndex":226,"id":"exchange-099"},{"speaker":"松本委員","kind":"質問","question":"私からは、３０１ページ、品川ビジネスクラブ助成金、それと武蔵小山創業支援センターについて伺います。産業振興はすごい大事なのですけれども、その中で限られた区民のための区の予算をどこに使うのかというのは極めて重要かと思いますが、まず、改めて、品川区がこの品川ビジネスクラブに助成をする理由、意義について、お伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"区で産業振興させていただいているところですが、やはり１点、民間の力なども一緒にやらせていただきたいというところで、連携協定を平成２５年に結びまして、その中で品川ビジネスクラブに対して、毎年人的部分等を中心に。","voiceIndex":229,"id":"exchange-100"},{"speaker":"松本委員","kind":"意見","question":"品川ビジネスクラブ補助金交付要綱を拝見すると、区内のものづくり産業等の振興発展に寄与することを目的というふうに補助金が交付されているということだと思いますが、一方で、このビジネスクラブ自体は、別に会員とかを区内に限っているわけではないということかと思うので、では、区内のものづくり産業等の振興発展にどう実際に寄与しているのかというところをお願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"区内の事業所に対して何ができるかということで、いろいろ考えていただいて事業などを行っていただいている。私どもも当然一緒に相談しながらという形になりますけれども、そこの部分が一番大きいのかなと考えているところです。","voiceIndex":231,"id":"exchange-101"},{"speaker":"松本委員","kind":"質問","question":"もともとは、ＳＨＩＰができた時期と、補助金を出し始めた時期はずれているので、本来的には、ＳＨＩＰとは別に考えて、どういうふうに区のビジネスの創出に寄与しているのかということを考えていくべきかなと思います。こういったところで考えていくと、品川ビジネスクラブ発で、区内で新しい新規のビジネスがスタートしたというふうな事例は実際にはあるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"なかなか企業、品川区内だけでビジネスというのはなかなか難しいところがありまして、法人として品川区に登記をされるということはあろうかと考えています。","voiceIndex":233,"id":"exchange-102"},{"speaker":"松本委員","kind":"質問・要望","question":"こういったものを使って、ぜひ区内で、このコンテスト自体も全国から応募可能というところなのですけれども、ぜひ区内の産業の発展に寄与していただきたいというふうに思っているので、この副賞の実証実験の機会提供が、実際に副賞であげても、特に使われないということになるとちょっと悲しいので、毎年コンテストを行われていると思うのですけれども、毎年どういった実証実験が行われているのか。","respondent":"遠藤商業・ものづくり課長","answer":"実証実験は副賞の１つになっているところですけれども、実際に受賞した方に対する支援はいろいろありますので、その中の１つというふうに考えているところです。","voiceIndex":235,"id":"exchange-103"},{"speaker":"松本委員","kind":"質問","question":"この品川ビジネスクラブの補助対象経費、補助金の要綱を見ますと、事業費から会費等の事業収入を控除した額を対象に補助経費を算出しているということになると、会員数がどんどん減っていけば、区の持ち出しというか、補助金の額も増えざるを得ないというふうに思うのですけれども、この辺りの会員の増強、ここについて区として何かしら対策はとられているのか伺います。","respondent":"遠藤商業・ものづくり課長","answer":"委員おっしゃるとおり、会員数としては、実は平成２６年の段階で１０６人だったのですが、現在１９４人と会員自体は増えているような形になっています。なぜ会費が減っているかというと、いわゆる有料会員が減ってしまっている。","voiceIndex":237,"id":"exchange-104"},{"speaker":"松本委員","kind":"質問","question":"会員数自体が増えているのはいいことかなと思います。区からの支出、これは私、補助金と指定管理料かなと思っていたのですけれども、令和２年度の品川ビジネスクラブの決算書を見ると、１,０００万円以上の受託料が区から払われているというふうに出てくるのです。これは何のお金なのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"そちらにつきましては、区のほうで委託をした事業がございまして、ですので、指定管理料や補助金とも別という形で受託していただいたというものです。","voiceIndex":239,"id":"exchange-105"},{"speaker":"松本委員","kind":"質問・要望","question":"その辺りも、結構これは私もびっくりしたのですけれども、決算書を見ると、ＳＨＩＰ関連を除くと、この品川ビジネスクラブの収入は９０％以上が区からの支出ということになっているのです。この補助金が出て結構もう長くなると思いますので、一度こういった事業の見直しということも要望して、私からの質問は終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-106"},{"speaker":"おくの委員","kind":"質問","question":"私からは、２９２ページ、リサイクル推進費あるいは２９４ページ、清掃費に関わって、サーマルリサイクルについて質問いたします。そこで、サーマルリサイクルについて伺いますけれども、これは焼却するということですから、多くのＣＯ２を出す処理方法です。温暖化対策としては、もちろん可能な限り避けるものだと思いますが、この点はいかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"このサーマルリサイクルについてというところになりますと、確かに委員のお話のように、ＣＯ２の面では、少しそういう面はありますが、ただ、平成２０年度当時、それまでは全てを埋立てていたというところで、埋立て処分場の寿命の年数とか、そういったところを考えれば。","voiceIndex":245,"id":"exchange-107"},{"speaker":"おくの委員","kind":"質問","question":"それからもう１点、このサーマルリサイクルについて伺います。素朴に言って、これをプラスチック廃棄物を再生して利用している、リサイクルだと言うのには、やはり無理があると思います。なぜこういうプラスチック廃棄物の焼却のことを、世界でも使われていない「リサイクル」という言葉でわざわざ呼んでいるのでしょうか、この点もお伺いいたします。","respondent":"品川品川区清掃事務所長","answer":"サーマルというのは、当然、燃やすことによって熱に変換されている。そして、それが電気になったり、温水になったりというようなことで、燃やすことによって何かを生むことができるという意味から、「リサイクル」というような言葉を使っているかというふうに考えております。","voiceIndex":247,"id":"exchange-108"},{"speaker":"おくの委員","kind":"質問","question":"品川区は、サーマルリサイクルで焼却の範囲を広げたというふうに申し上げましたけれども、港区のように、資源の範囲を広げて、本来のリサイクルの範囲を広げていくという考え方もあると思うのですけれども、この点は、品川区としては、どのように考えていらっしゃるのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"区としましても、この流れに沿って、製品プラスチックの回収方法と、それから処分の仕方、それから再生の仕方等を、どうするかというところも現在検討しながら、製品プラスチックの回収に向けて考えていっているところです。","voiceIndex":249,"id":"exchange-109"},{"speaker":"おくの委員","kind":"質問","question":"結局は、拡大生産者責任の考え方に立って、生産者が生産した製品が使用され、廃棄された後になっても、その製品の適正なリサイクルや処分について、物理的または財政的に生産者自身が一定の責任を負うべきだと。そういう考え方について、品川区自身はどういうふうにお考えでしょうか。","respondent":"品川品川区清掃事務所長","answer":"先ほど委員からお話あったように、生産者のほうの工夫も必要ですし、現在使っているプラスチック製品についても、改善できるところは改善していく、それから、リサイクルについても、今度どんどんやっていくというような形で。","voiceIndex":251,"id":"exchange-110"},{"speaker":"おくの委員","kind":"質問・要望","question":"私としても、結局は拡大生産者責任の考え方をしっかり取り入れて、そして生産量自体を減らしていくという立場に立つ以外、この問題の解決はできないと思うのです。区のほうからも国に対しても、こういう考え方を主張していっていただきたいと思います。最後に、これを申し上げまして質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-111"},{"speaker":"大沢委員","kind":"質問・要望","question":"３０１ページ、創業支援施設等経費、それと各種融資あっせん、時間があれば、商店街、順不同で聞かせていただきたいと思いますけれども、質問に入ります前に、歳入の使用料及び手数料のところで、ものづくり創造センターについて伺いましたけれども、今年の予算書に書いていないということは、廃止をしたということなのでしょうけれども、これは、委員会のほうに報告はされたのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ものづくり創造センターの歳入がなくなったというところでございまして、使用料収入が入らないということで、こちらのほうから落としているだけでございまして、物自体はまだあるという状況です。","voiceIndex":256,"id":"exchange-112"},{"speaker":"大沢委員","kind":"確認","question":"分かりました。確認だけさせていただきましたので。日本では、欧米並みに１０％の開業率を目指そうということで国で言っていますけれども、ちょっとこの中で文がありますので読ませてもらいます。２０１４年１月に施行された産業競争力強化法においては、地域における創業を促進するため、創業支援事業計画を策定した自治体を国が認定し支援するとされていますが、品川区の認定状況についてお尋ねします。","respondent":"遠藤商業・ものづくり課長","answer":"当区は認定されているというふうに認識しております。","voiceIndex":260,"id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"創業支援事業計画を策定しているということですけれども、現状、品川区の開業率はどれぐらいになっているのか。そして、目標値をどのくらい定めていらっしゃるのか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"すみません、資料として、今、手元にないのですけれども、まだ開業率というところでは、特に目標値は定めていなかったような認識をしています。","voiceIndex":262,"id":"exchange-114"},{"speaker":"大沢委員","kind":"質問","question":"で教えてください。目標値を定めていない、なぜ定めていないのでしょうか。やはり創業支援、正にこの数字に関わる事業であるので、やはり目標値は定めるべきであって、先ほども冒頭でお話をしたように、欧米諸国ではということで、開業率１０％を目指すということをうたっているわけです。国もそれに対しての支援策を出しているわけなのですけれども、目標値を出すご予定はあるのですか。","respondent":"遠藤商業・ものづくり課長","answer":"来年度、様々な形で調査費用などもいただいているところですので、委員ご指摘の部分も踏まえて検討していきたいと考えております。","voiceIndex":264,"id":"exchange-115"},{"speaker":"大沢委員","kind":"質問","question":"ぜひとも検討をお願いします。プチ創業、あるいは、大きなものを、大きな器をつくって創業したい方、いろいろな種類があるわけですけれども、区内５か所ある創業支援センターを、そこら辺の創業に対する意識の違いがある方たちにどのように紹介されているのか。取組みを教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"西大井創業支援センターはまだ動いたところですが、やはりＳＨＩＰが一番の出口というふうに考えているところがありまして、西大井創業支援センターがそのもっと手前といいますか。","voiceIndex":266,"id":"exchange-116"},{"speaker":"大沢委員","kind":"質問","question":"そこで、決して後ろ向きな話ではないのですけれども、創業、起業に相対するもので廃業というものがあります。かつて早稲田の先生だったかと思いますけれども、『会社の寿命』なる書物があったような気がします。そして、廃業にならないために、どのようなフォローアップ、取組みを行っているのか、それをまず教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"やはり黒字のうちにだとか、いろいろと、周りに迷惑をかけないでというところで、廃業という形の選択をとられる方もいらっしゃるですので、残念ながらというところで、いろいろな形で企業の支援と、廃業の支援というのもちょっと変なところですけれども、事業者にとって。","voiceIndex":268,"id":"exchange-117"},{"speaker":"大沢委員","kind":"質問","question":"廃業の支援ということでありますけれども、起業に関する様々なデータがある。先ほど冒頭にお話をしましたその本には、２３年から３０年が会社の寿命だとなるものが書いてありますけれども、品川区では起業された企業、創業された企業、これは男女問わず、平均でどれくらいになっているのか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"すみません。実際に立ち上げてから廃業までの平均年数は把握していないところです。先ほど２３年から３０年というお言葉がありましたけれども、何となく今の世の中の流れということで、少しずつ早まっているというような話は全般的に聞いているところです。","voiceIndex":270,"id":"exchange-118"},{"speaker":"大沢委員","kind":"質問・要望","question":"商いは数字でありまして、何となくという表現は、ちょっと私、カツンと来たのですけれども、何となくで創業支援をされたりとか、何となくで、創業するということは、みんな人生をかけているわけです。廃業するということも、やはり人生をかけるわけですから、そこのところをしっかり認識していただいて、この事業をやっていただきたいと思うのですけれども、ご意見をください。","respondent":"遠藤商業・ものづくり課長","answer":"「何となく」という表現、大変失礼いたしました。マスコミ等の報道あるいは雑誌などを読んでいる中で、傾向としてということで認識しています。","voiceIndex":272,"id":"exchange-119"},{"speaker":"大沢委員","kind":"質問","question":"各種融資あっ旋ですけれども、規模の小さいところ、特に物販であればいいのですけれども、飲食になると、設備資金はさほどのものではないのですけれども、運転資金がなかなか出づらいような状況があるということを聞いているのですけれども、そこらのところの実態は把握されていますでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"運転資金、通常ですと、３か月をめどにという形で借りていただくお話が多いのかなというふうに認識しています。","voiceIndex":274,"id":"exchange-120"},{"speaker":"大沢委員","kind":"質問・要望","question":"様々、区の事業にも協力をしていただいているわけですけれども、このコロナ禍の中、そしてこれからチェーン店が多くなる世の中で、個店は非常に苦戦を強いられているところがあるので、しっかりとした事業計画が成り立つような資金計画もフォローアップしていただきたいと思うのですけれども、いかがお考えになりますでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"私ども経営にかかわる窓口は、現行でも拡大して実施しています。困っている事業者の方がいらっしゃれば、その部分も含めて、細部にわたり、こちらのほうでご支援させていただければと考えているところです。","voiceIndex":276,"id":"exchange-121"},{"speaker":"つる委員","kind":"提案","question":"名刺についても、バナナペーパーを採用したらどうですかということをあわせて提案させていただいていて、これについては、今年度、令和３年度から採用していただいていて、バナナ繊維２０％配合の名刺というふうに認識をしております。この間、制服についての話等もさせていただきましたので、これに限らずですけれど、その辺の活用の拡大について伺いたいと思います。","respondent":"河内環境課長","answer":"バナナに限らず、こういったものにつきまして積極的に取り入れることが、環境負荷の低減に非常に有効だという点で、環境省のサステナブルファッションというところに出ておりますが、再生原料など、素材を選択することが非常に重要だというふうな認識です。","voiceIndex":279,"id":"exchange-122"},{"speaker":"つる委員","kind":"提案","question":"今おっしゃっていただいたように、やはり単価の課題というのはどうしてもついて回る。それから一般質問での提案の拡大についても、ぜひあわせてご見解をいただきたい。それから、これも本会議で伺ったことで仮称ではありますけれども、品川青年環境未来会議についてです。あわせて、サステナブルファッションショー等についても、本会議で求めていますので、今日は具体的にご答弁いただければと思います。","respondent":"河内環境課長","answer":"私どももこれを検討しているところではありますが、海外からのご参加などを含めまして、リアルがいいのか、あるいはネット配信がいいのか、また、受け取る側にとりまして、どちらのほうが訴求力、インパクトがあるのか、そういう意味では、多面的な面で見まして。","voiceIndex":281,"id":"exchange-123"},{"speaker":"つる委員","kind":"確認","question":"すみません、多岐にわたって質問させていただきました。この辺りは、都にも既に確認しているので答えは難しいと思うのですけれども、２０１５年も当時の環境課長が、東京都２３区が一緒になってやっておりますと、対応を考えてまいりますというご答弁をいただいているので、あえて伺いますが、ここについての支援策が何か検討されていれば、ご答弁いただければと思います。","respondent":"河内環境課長","answer":"そういったところで、最低限の費用の掘削で済むように、都とも連携いたしまして、土壌のエキスパートを紹介しながら、こういう配置のときにはこのぐらいで済むだろうというところで、１件１件丁寧に対応しながら。","voiceIndex":283,"id":"exchange-124"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に、もったいないレシピの動画配信について、これは一般質問で求めさせていただきました。環境省のいろいろな動画とかがありますけれども、そういうものをぜひ参考にしていただきたいというふうに申し上げましたが、区として、今後どのようにして考えていただけるのか、最後にご答弁いただければと思います。","respondent":"河内環境課長","answer":"中身ですが、やはり動画配信ですので、クックパッドなど、実際に使っていただきますようにという点を大事にしておりまして、１本当たりの時間、編集内容につきまして検討を進めているとともに。","voiceIndex":285,"id":"exchange-125"},{"speaker":"小芝委員","kind":"質問","question":"私からは、２９１ページの環境学習交流施設管理運営費と、商店街地域力向上事業について質問します。先ほど、つる委員、また渡部委員からも質問がありましたので、なるべく重複しないように質問をします。！イベント参加者の方々にはメリットもあったのではないかと思いますし、また、ほかでも広報活動をされてきたと思いますが、これまでの広報活動の取組みを教えていただけますでしょうか。","respondent":"河内環境課長","answer":"そういった中で、今後も開設される講座などのご案内もしつつ、先ほど、委員からもお話がありましたとおり、大型イベントに出展させていただきまして、そこの方にいろいろなチラシ、あるいは中身についてご説明申し上げながら、こういったものを進める予定です。","voiceIndex":288,"id":"exchange-126"},{"speaker":"小芝委員","kind":"質問","question":"今こういう様々な広報活動を行っていくですけれども、エコルとごしに入場する初年度の目標数値といいますか、年間で大体どのくらいの人数を予測されておりますでしょうか。今後、５年後、１０年後に向けて、その数、どのように推移していくことを目標にしているのか教えていただければと思います。","respondent":"河内環境課長","answer":"これは近隣区で、例えば港区、江東区などに同様の環境施設がございまして、講座数など、中身の濃さ、数は違うのですが、そういったところを逆算いたしますと、年間３万人を見込むのが妥当かなというところで、これに向かいまして、今、開設を進めているところです。","voiceIndex":290,"id":"exchange-127"},{"speaker":"小芝委員","kind":"質問","question":"ご丁寧な説明ありがとうあります。年間３万人としているそうですが、字幕だとか、そういった誰もが利用しやすいエコルとごしというところで、今後、ふだんから入館される方もいれば、そういったイベントだとか講座、若干イレギュラーな部分での入場も見込まれると思うのですけれども、その辺りのイレギュラーな部分での考え方を教えてもらいたいのですが。","respondent":"河内環境課長","answer":"公園の利用者の方の憩いの場、交流の場といたしましても利用を促進していきたいと考えております。多様な関わり方があるかと思いますが、学習だけということではなく、地域の方に愛されますように、こういったことを進めていきたいという考えです。","voiceIndex":292,"id":"exchange-128"},{"speaker":"小芝委員","kind":"質問","question":"ちょっと遡りますけれども、広報による宣伝、先ほどご答弁のとおり、承知いたしました。先ほど少し若年者向けのという話もありましたけれども、やはり若年者だとか主婦層だとか、そういったところにも本当にアプローチ、宣伝が行き届くよう、ＳＮＳを総動員した広報活動の促進をお願いしたいと思いますけれども、そこを改めてお答え願えますでしょうか。","respondent":"河内環境課長","answer":"先ほど、年間、月間利用者数が８万８,０００人というＬＩＮＥのこともお伝えしたところではありますが、同時に、ツイッター、インスタグラムなども、通常の若い世代の方が使われているものに関しましては。","voiceIndex":294,"id":"exchange-129"},{"speaker":"小芝委員","kind":"質問・要望","question":"ぜひ若年者、主婦層向けの宣伝に取り組んでいただきたいと思います。例えば、ツイッターで、オープン直前に、品川区の公式アカウントにフォローしている方に、例えばリツイートをお願いすることで、１時間とかで２時間とか、そういった短い時間帯での枠で拡散させていくということも１つの手ではないかなと思います。その辺り、どのようにお考えでしょうか。","respondent":"河内環境課長","answer":"そういったところの連携や、また、有名な解説者など、様々な連携の中で、やはり今まで手の届きにくかった世代に対して、情報発信を隅々までというような思いの中で進めてまいりたいというふうに考えているところです。","voiceIndex":296,"id":"exchange-130"},{"speaker":"小芝委員","kind":"提案","question":"積極果敢な宣伝をお願いしますとともに、エコルとごしをはじめとしまして、今後の区の環境施策の展開を、またさらに広めていく上で、区内に本社を置きます企業との連携が、またさらに施策の相乗効果を生み出すものと考えております。私もこれまで、昨年の決算特別委員会などで提案をさせていただきましたけれども、連携についての取組みについて教えていただければと思います。","respondent":"河内環境課長","answer":"国内企業との連携によりまして、双方がメリットが生じますように、双方高め合いながら、エコルとごしの機能も生かして進めてまいりたいというように考えているところです。","voiceIndex":298,"id":"exchange-131"},{"speaker":"小芝委員","kind":"質問・要望","question":"取組みが行われているものと承知いたしました。続きまして、商店街地域力向上事業についてお伺いいたします。今年の当初予算では１７件を見込んでいるそうですが、まず、今年度の令和３年度の実績について教えていただきたいということと、この予算での１７件という見込みを出しましたその理由を教えていただけますでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"来年度の予算につきましては、今年度の実績見込みなどを勘案いたしまして、少しコロナなども落ち着いてきたことから住民生活サポート事業が少し動いてくるのかなというところもあって、住民生活サポート事業につきましては、若干、２件ほど計上したと。","voiceIndex":300,"id":"exchange-132"},{"speaker":"小芝委員","kind":"提案","question":"地域の中には、町会長をはじめとしまして、社会福祉協議会だとか、民生委員、また所轄の警察の方も一緒になって、月に１回、地域を２時間ほど時間をかけて回っているところもあります。ですので、町会、自治会、また、ときには警察などと連携して取り組んでもらうような事業展開を提案させていただきたいと思いますが、その辺りのお考えを教えていただけますでしょう。","respondent":"遠藤商業・ものづくり課長","answer":"様々な方法があろうかと思いますので、今後も研究していきたいというふうに考えています。","voiceIndex":302,"id":"exchange-133"},{"speaker":"小芝委員","kind":"質問・要望","question":"先ほど、エリアサポーターの活用ということもありましたけれども、先ほども話しましたとおり、商店の方々、町会とのつながりも当然あるわけです。ぜひとも、時には行政も入りまして、三位一体となって地域を回っていただく、それが、よく言うところの長期基本計画の目的です「住み続けたいまちしながわ」の１つのきっかけにもなると思いますので、ぜひ前に進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-134"},{"speaker":"大倉委員","kind":"質問・要望","question":"私は、２９５ページ、粗大ごみからのリユース事業から質問をさせていただいて、少し関連して聞いていきたいと思います。その中で、この事業が進んでリユースが品川区内で進めばいいなという思いで伺わせていただきたいと思います。リユースとして、年間２,４００点程度の粗大ごみをということで、ごみの削減効果としては、どのぐらいを試算されているのでしょうか。お願いします。","respondent":"品川品川区清掃事務所長","answer":"持ち込みなのですけれども、また解釈がいろいろ違うのかもしれませんが、１つは、今考えているところは、あくまでも、例えば日曜日に品川区資源化センターに粗大ごみを持っていくというような流れがあるのですけれども。","voiceIndex":306,"id":"exchange-135"},{"speaker":"大倉委員","kind":"確認","question":"現金とかクレジットカード、電子マネーとかが可能なのかというところを教えてください。は販売の方法なのですが、これは先着なのか抽選なのか、どういったことになるのか。この辺も決まっているのかどうかも含めて、分かれば教えてください。購入者については、ここは希望する区民に提供するということで、「区民」と書いてあるのですが、区在住の方ということでいいのか確認をさせていただければと思います。","respondent":"品川品川区清掃事務所長","answer":"購入者につきましては、基本的には区民を考えているのですけれども、これも例えば、こういうリユースの状況などを見て、あまり進みがよくないのであれば広げていくというような考え方もありますし、この辺についても、どういうふうにしていくかというところは。","voiceIndex":308,"id":"exchange-136"},{"speaker":"大倉委員","kind":"質問","question":"すみません、細かくお伺いしました。１つ懸念点があるのが、いろいろな方に購入の機会を均等に確保していくというところが重要かなと思っていて、区民以外も、今後の状況によっては検討もされていかれるということだと思うのですが、１点、制限について伺えればと思うのですけれども、何点買っていいのか、また、年間にどのくらい、例えば、１人なのか、世帯なのかということが決まっていれば教えてください。","respondent":"品川品川区清掃事務所長","answer":"ちょっと繰り返しになってしまいますけれども、こういうところも先進自治体とかを参考にしながら、また考えていきたいと、このように思っております。","voiceIndex":310,"id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"その際に、本人確認とかも必要になってくるのかなと思うので、みんなが購入機会をしっかり得られるような取組みにしていっていただきたいのですが、最初は区民のみというところで、これ、ふと思ったのは、例えば、在勤の方と考えたときに、五反田でもベンチャーでこれから頑張っていくというような人たちが、割と安価なものを買いたいといったときに、様々な民間企業もありますが、例えばそういったところを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":312,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"私は、３０３ページ、中小企業活性化事業費についてお聞きしたいと思います。区内の中小事業所の経営状況の実態を、今、どのように把握されていますか、教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"一方で、何度もお話ししています、いわゆる倒産件数ということでは、一番少ない状況だと、ここ最近では少ないというところがありますので、一定、区内も含めましてですけれども、効果が出ているのかと感じているところです。","voiceIndex":314,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"融資がありますよね。融資を受けてから２年たちました。そして、経営困難企業は日本中で３０万社以上と言われ、今後、追加融資や借入融資ができなければ、破綻事業者が続出すると思いますが、何か区として対策はありますか、教えてください。そして、品川区内に経営困難企業はどれぐらいあるというふうにお思いでしょうか。これも把握されているでしょうか、教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"これから資金を返すところが出てくるけれども、なかなか返せないだろうというところでの区の支援策ですけれども、来年度、今回予算要求させていただいている中で、借換専用資金を用意させていただいて、こちらは私どもで融資あっ旋させていただいているもので。","voiceIndex":316,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"今の借換融資についてもちょっとお聞きしたいのですが、これは今の経営状況、経営内容や、既に融資されている額に関係なく、必ず借換融資を受けられるのでしょうか。それを教えてください。そして、品川区の借換融資で一体何社まで助けられる、そういう予算措置というのはしてあるのでしょうか。その辺についてお答えください。","respondent":"遠藤商業・ものづくり課長","answer":"その結果、借換専用資金が使えないという部分は、全くゼロではないかというふうに感じているところですが、基本的に銀行からは、こちらの制度については、今のところ好評をいただいているような雰囲気でございまして、費用につきましては、既に利息。","voiceIndex":318,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"今、何社ぐらい助けられるのですかとお聞きしたのです。今、お話をお聞きしたとおり、結局、金融機関によっては、この経営内容では駄目ですよということがほとんどではないですか。結局、何百社もあって、「いや、何社かは大丈夫ですけれども、あとは金融機関でどういう返事をするか分からないから、私どもでは責任は持てません」ということなのですか。その辺についてお答えください。","respondent":"遠藤商業・ものづくり課長","answer":"ですので、全てを救うというのは現実的には難しいかなという部分は正直ありますので、今後、もう事業が成り立たないという部分まで税金を使って支援するのかというのは、考え方としてあろうかと思っているところです。","voiceIndex":320,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"全てを救うというのは、恐らく無理だと思います。それは、やることはやっぱり国と都の事業だと思っています。融資額の減額、毎月の額を例えば３０万円ずつ返済するならば、それを２０万以下にしてもらうとか、そういうことは区でお願いできるのではないでしょうか。教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"なおかつ、１年間据置きという形になり、一旦支払いが終わる形になりまして、返済期限が１０年という形になりますので、恐らく今の返済しているものよりも長くなりますため、一月当たりの金額も少なくなって、返済期間も延びるというふうな形になっているところです。","voiceIndex":322,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"もちろん、相談とか何かも受けて、しっかりお聞きして、そしてこういう支援を国や都にしてほしいという希望が多々あると思いますので、その辺、私はもっと身近な区として、一社一社に対して、アンケートでも何でもいいですから、声を聞いていただきたいと思います。２９２ページ、リサイクル推進費についてお聞きしたいと思います。そして、リサイクル、リユースは大事だよということをやったではないですか。","respondent":"品川品川区清掃事務所長","answer":"今年度、まず始めてみるというところが１つ大きなところかというふうに思っておりますので、まずは、資源化センターで引渡しをして、どれぐらいのニーズがあるかとか、そういうところを見ながら。","voiceIndex":324,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区が今日まで取り組んできたということは、私はすばらしいことだと思っています。それで多くの子どもたちにも、多くの大人の皆さんにも、この気持ちを、リユースする気持ちを植えつけています。私は、物の大切さという教育も兼ねて、もっと近場で皆さんが利用しやすい、そういう立地も考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":326,"id":"exchange-145"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、２８９ページの温暖化対策事業、２９１ページの品川区環境基本計画改訂に関わって伺っていきたいと思います。こうした下で、２０５０年、ＣＯ２ゼロに向けて、地方自治体の役割発揮が求められています。できることをやるという姿勢でなく、２０５０年、ＣＯ２ゼロに向けて、どのような取組みが必要かという姿勢が必要だと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"は手のつけられるところから取り組むとともに、将来到来いたします新技術などが円滑に社会に行き渡り、またそれをご活用いただけますよう、意識の向上なども含め進めてまいりたいというふうに考えているところです。","voiceIndex":328,"id":"exchange-146"},{"speaker":"のだて委員","kind":"質問・要望","question":"２０３０年までが勝負と言われておりますので、そこに向けて、区としても意識を持っていただいて、２０３０年までに目標を達成していく、まず半減にしていくというところでやっていっていただきたいと思うのですけれども、来年度、区の環境基本計画の改訂検討が始まりますけれども、これまで行ってきた取組みの分析はどうなっているでしょうか。うまくいっているという分析かどうか伺いたいと思います。","respondent":"河内環境課長","answer":"そういった面倒くさいところがありますけれども、丹念に対応しながら、省エネに関わらず、そういった排出係数につきまして、全く関係なくゼロになるというようなところをまずは普及させていき、区民の模範となりますように、先ずは隗から始めろでございまして。","voiceIndex":330,"id":"exchange-147"},{"speaker":"のだて委員","kind":"質問・要望","question":"政府は、ＣＯ２排出の多い石炭火力発電に固執しており、２０５０年、ＣＯ２ゼロに向けて、こうした姿勢を改めることを自治体としても求めるべきだと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"２０３０年におきましては、水素による発電も始まるという点があります。社会情勢に伴いまして排出係数が変わってまいりますが、適宜、脱炭素電力を導入することによりまして、その影響を低減することができるというふうに認識しております。","voiceIndex":332,"id":"exchange-148"},{"speaker":"のだて委員","kind":"質問","question":"脱炭素電力にしていくことで削減していくということですので、そういう意味では、やはりこの石炭火力を廃止していく、そうしたことが、区の取組みをさらに進めていくためにも重要だと思うのですけれども、改めて伺います。","respondent":"河内環境課長","answer":"そうした風潮を受けまして、区としても進行方向についてしっかりと考えてまいりたいというふうに考えているところです。","voiceIndex":334,"id":"exchange-149"},{"speaker":"のだて委員","kind":"質問・要望","question":"国に対して意見を言うということはおっしゃいませんでしたけれども、ぜひそうしたエネルギーの転換、自治体としても国に要望もしていただきたいと思いますし、自治体としても進めていっていただきたいというふうに思うのですけれども、やはり区内のＣＯ２排出量、現在、この業務や家庭、運輸部門など、それぞれの排出割合を伺いたいと思います。","respondent":"河内環境課長","answer":"先ほど言い忘れましたが、再エネルギーの導入なども非常に有効な手だてです。家庭におきましても、そういったものを進めることによりまして、こういった提言に向かって進めてまいりたいというふうに考えているところです。割合はまだこれから検討してまいります。","voiceIndex":336,"id":"exchange-150"},{"speaker":"のだて委員","kind":"質問","question":"区の排出量の割合を聞いたのですけれども、ご答弁がなかったので、それは今度でいいです。部門別、具体的に計画を進めていくというところで、これから検討していくということですけれども、そうした考えがあるのかどうか伺います。","respondent":"河内環境課長","answer":"部門別に進めるかどうかは今後の検討事項ではありますが、分科会におきまして、相関関係も見ながら、そういったものの削減に向かって取り組んでまいりたいというところです。","voiceIndex":338,"id":"exchange-151"},{"speaker":"のだて委員","kind":"質問・要望","question":"これから検討するということですけれども、やはりそうした具体的に部門別ですとか、年度ごとに目標を持って計画を立てて進めていくということが、２０５０年、ＣＯ２ゼロに向けて重要だと思いますので、やっていただきたいと思いますし、それぞれ見える化をしていくということも重要だと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":340,"id":"exchange-152"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２９１ページ、環境学習交流施設、ＺＥＢ普及支援業務委託、２８９ページ、太陽光発電・蓄電池システム設置助成、２９１ページ、低公害車買換え支援事業、２９３ページ、節電啓発、国産間伐材有効活用事業助成、２９１ページ、アスベスト対策事業、２９５ページ、普及啓発事業についてお伺いいたします。初めに、２９１ページ、環境学習交流施設とＺＥＢ普及支援業務委託についてお伺いいたします。","respondent":"小林施設整備課長","answer":"セールスポイントですが、まず１つは、施設の約３０％の電力をまかないます太陽光発電、それから、空調等につきましては、地中の安定した熱を活用したシステムを用いる、いわゆる機械を用いた環境配慮、それから、地域につきましては。","voiceIndex":342,"id":"exchange-153"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"省エネ、創エネの工夫点が本当によく分かりました。普及に向けて、それを今後にどのように生かしていくのか、この区有施設の面、また、民間の普及促進についての取組みもあわせてお聞かせいただきたいと思います。","respondent":"小林施設整備課長、河内環境課長","answer":"私のほうからは、前段、区有施設の関係についてお答えいたします。やはりこのＺＥＢというのは、今後の脱炭素社会へ向けて、実現のためには非常に大きな役割を果たすというふうに認識しております。民間の普及ですが、こういったセミナー、講座などを中心とした啓発について取り組んでまいりたいと考えています。対象ですが、ＺＥＢ化も検討いたしております民間事業者、デベロッパー、設計事務所など、実施を想定しています。","voiceIndex":344,"id":"exchange-154"},{"speaker":"高橋（伸）委員","kind":"質問","question":"宣伝も含めて、今後の取組み、ぜひともよろしくお願いいたします。続きまして、２８９ページ、太陽光発電・蓄電池システム設置助成についてお伺いいたします。再生エネルギーの普及においては、太陽光パネルは有効な手段だと考えています。昨年度の助成件数と、これから得られた課題は何かをお伺いしたいと思います。よろしくお願いします。","respondent":"河内環境課長","answer":"そうしたことから、当該パネル設置は、あらかじめこういったものを想定した建物ということで、補強可能の場合か、あるいは新築かに限られているところがあります。多くの申請の方が新築となっているところが課題として捉えるべき問題というふうに考えております。","voiceIndex":347,"id":"exchange-155"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。次に、２９１ページ、低公害車買換え支援事業についてお伺いいたします。個人事業主を含む区内中小企業に対しては、東京都と連携した低公害車の買換え助成を行っている事業ということですけれども、脱炭素に向けた取組みが進む中、この低公害車はどのようなものが対象になるのか、まずお伺いしたいと思います。","respondent":"河内環境課長","answer":"こちらの対象車種ですが、窒素酸化物や硫黄酸化物などの大気汚染物質排出量の少ない車、今まで取り扱っているディーゼル車ですが、そのほか環境負荷の少ない自動車といたしまして、燃料電池車、電気自動車、ハイブリッド車などがこの対象となっているものです。","voiceIndex":351,"id":"exchange-156"},{"speaker":"高橋（伸）委員","kind":"質問","question":"最近では、脱炭素に向けて、特に電気自動車が注目されていると思います。戸建てにお住まいの方ならば、Vehicle to Homeという電気自動車の蓄えた電気を家庭で使う。防災面でも注目される点もあわせ持つような方式があります。現状、区内には、利用可能ないわゆる充電スタンドはどの程度あるのでしょうか。把握しているのであればお答えをお願いしたいと思います。","respondent":"河内環境課長","answer":"こちらにつきましては、カーディーラー、また大型小売店、ホテルなどを中心といたしまして、令和４年２月末現在ですが、１９か所２５基の状況です。令和４年５月に開設いたしますエコルとごしにつきましても、これを備えており、充電が可能な状況となっておるものです。","voiceIndex":353,"id":"exchange-157"},{"speaker":"高橋（伸）委員","kind":"質問","question":"電気自動車なのですけれども、化石燃料を使わない点は、脱炭素の面で優位な点は分かりますけれども、ガソリン車の燃費にあたるようなエネルギー効果は本当に優れているのかどうなのか、どのようにお考えなのでしょうか。","respondent":"河内環境課長","answer":"いわゆる次世代自動車にあたるものの燃費的な比較ですが、こちらにつきましては、環境省にエコカーを選んでみませんかというようなページも載ってございまして、ガソリン車の燃費効率を１とした場合に、電気自動車は２.１前後、また。","voiceIndex":355,"id":"exchange-158"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。続きまして、２９３ページ、節電啓発、国産間伐材有効活用事業助成についてお伺いします。ＣＯ２対策としては、発生抑制も大切だと思います。カーボンニュートラルにおいて、今後も森林がＣＯ２吸収力を持続していくためには、具体的な取組みも含めた啓発が欠かせないと考えますけれども、この鍵となる子どもたちへの啓発について、どのように対応するのか教えてください。","respondent":"河内環境課長","answer":"やはり民間のほうでいろいろ使いながら、こういった森林の整備も含め、ＣＯ２削減に向かって役立てていくことが重要というふうに考えているところです。子どもたちには、そういったところも含めまして、しっかり啓発を進めてまいりたいと考えているところです。","voiceIndex":357,"id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今後もしっかりと進めていただきたいと思います。次に、２９１ページ、アスベスト対策事業についてお伺いいたします。区の業務量が増えている状況と思いますけれども、こういった規制については、必要な力量を持った者が現場を回ったり、確認などをすることが重要と考えておりますけれども、区の対応は、どのように行われているのかお伺いしたいと思います。","respondent":"河内環境課長","answer":"これまで国や都から、通知に基づきまして、年３回程度、解体現場のパトロールなどを実施していますが、令和３年度から、通年パトロールといたしまして、全ての解体改修現場を対象といたしまして実施しています。現時点で３００件超実施済みです。","voiceIndex":359,"id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"意見","question":"最後に、２９５ページ、普及啓発事業で、エコルとごしで、これからワークショップをやったりという中で、清掃の普及啓発にはすごい重要だと思うのですけれども、今後の展開をどのようにお考えになっているかお知らせください。","respondent":"品川品川区清掃事務所長","answer":"今後、エコルとごしのほうで、映像のシステムとか、そういったところが大変長けている施設ですので、こういったところを利用しながら、清掃のごみ出しの分別だとか、リサイクルだとか、そういったところも啓発のために使っていきたいと、このように考えております。","voiceIndex":361,"id":"exchange-161"},{"speaker":"塚本委員","kind":"確認","question":"これまでの経営変化対策資金などと比べれば、大分予算規模が小さいのですけれども、いわゆるニーズに対してというか、この借換えを望まれる方々に対して、十分に対応できる予算規模なのかというところで、いわゆる信用保証料等が経営変化対策資金２０２０等のときは、全額補助の対象だったわけですけれども、この借換えについては、その部分が入っていないというところはありますが、そこについて。","respondent":"遠藤商業・ものづくり課長","answer":"借換専用資金の予算規模です。大きくは、金額がかかっていないという部分ですけれども、１点目に今お話しいただきました信用保証は、今回こちらのほうでは区として予算化していないです。","voiceIndex":364,"id":"exchange-162"},{"speaker":"塚本委員","kind":"意見","question":"必要な方に十分に行き渡るようにということで、よろしくお願いしたいと思います。次に、３０５ページのＤＸ・デジタル技術活用推進事業ということで、これはプレス発表にも載っておりましたけれども、プレス発表のほうでは、区内中小企業のデジタル化は後れている状況にあると、こういう認識が書かれておりました。例えば、近隣区と比べて後れているとか、そういったことなのですけれども、お聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"中小企業は、どうしても人材がなかなかいないというところがありますのと、あと、そもそもどういうふうに取りかかってやればいいかというところで、中小企業全般にわたってなかなか、分かっているのだけれども取り組めないというような状況が現状です。","voiceIndex":366,"id":"exchange-163"},{"speaker":"塚本委員","kind":"質問","question":"これは新規の事業ということで伺っております。一般に、ＩＴ化ということと、ＤＸ化ということは、意味が違うというふうに言われているのですけれども、そういった点も含めて、この新事業の狙い、また、今までの事業との違い、こういったことについてお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"新たに何が変わったかですけれども、セミナーと助成金につきましては、引き続きやらせていただくのですけれども、先ほど申しましたとおり、ＤＸ化を進めるにあたって、なかなか中小企業は、どうやってやったらいいかというところが分からないという部分がございまして、１つは。","voiceIndex":368,"id":"exchange-164"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうした中で、今、区が新しい事業を始めるにあたって、その企業のＤＸ化による業績の最大効果みたいなものを求める上で、どういったところのＤＸ化を推進しようとしているのか、ここが非常に関心というか大事なところだと思うので、そこについてお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"ほかのところにつきましては、先ほどから、まずコーディネーターがおりますので、そちらにご相談いただいて、まだそれはアナログの段階だねということであれば、こちらではなくて、例えば新型コロナウイルス感染症対応中小企業支援特別助成だとか。","voiceIndex":370,"id":"exchange-165"},{"speaker":"塚本委員","kind":"提案","question":"今、答弁いただいた狙いというか、ターゲットというか、大変に適切なのではないかなというふうに私も思います。このＤＸ化によって、日本の賃金は、欧米諸国に比べ、先進国に比べてずっと上がっていないということを最近よく言われていると思います。どういうスペース、どの部屋を使うのですかみたいな具体的な話でもあるのですけれども、教えていただきたいと思います。","respondent":"河内環境課長","answer":"エコルとごしにおけます特別展示などのお話です。委員のおっしゃるとおりです。交流自治体、歴史館、水族館との連携の特別展示企画を予定しておりまして、場所ですが、１階にありますコミュニティラウンジ、広い部屋を用いまして、こういった特別展を持ちたいと考えています。","voiceIndex":372,"id":"exchange-166"},{"speaker":"塚本委員","kind":"確認","question":"講座というのは、多目的スペースを使うのでしょうか。講座もコミュニティラウンジなのでしょうか。ちょっと細かいですけれども確認させてください。","respondent":"河内環境課長","answer":"講座系あるいは集会系ですが、同じく３階にあります多目的スペース、こちらを用いましてやらせていただきたいのですが、特別展示となりますと、１階で、身体障害者の方も含めてアクセスのいいところを選びたいという狙いもありまして、そういったところを踏まえながら。","voiceIndex":374,"id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば、ＳＨＩＰでも区内割引みたいなものがあるけれども、１０％とか、あとは、特別日は５０％割引とかやっているけれども、そういう区分けというか、そういうことを考えながら検討されるのだろうと思うのだけれども、そこら辺の感覚を教えていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"私どもでやらせていただくのは、その多目的ホールというところで、先ほどいただきましたＳＨＩＰ、ブライトコアホールが隣の大崎で運営していますので、そういう部分も含めて、恐らく月曜日から金曜日、平日の部分については、どうしても商業利用が多くなるのかなというところで。","voiceIndex":377,"id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこを使うときは、ＳＨＩＰみたいな、ある程度の金額設定にするのかとか、今、土日にイベントという話があったけれども、そうすると、例えば、きゅりあんとか、スクエア荏原でもいいのだけれども、そこは地域の人が使えるぐらいの金額になっていると思うのだけれども、それはそういうふうにしようと考えていらっしゃる、平日と土日で、逆に土日のほうがぐっと安いのか。","respondent":"遠藤商業・ものづくり課長","answer":"そこの部分の検討経費という形になってきまして、近隣の状況だとか、あとはいわゆる周りの方、区民の方の利用だとか、そういう部分も含めて、今回、検討委託という形で計上させていただいたです。","voiceIndex":379,"id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけど、ここにも１５億円ぐらいの予算はあるけれども、多分区でやるのはこれぐらいが限度ですね。これは非常に大切なのだけれども、先ほど言ったように、第１回目の３年が来るわけです。そういう中になってくると、今回は借換えだから一気に返してしまうけれども、それで返していけるかというと、すごくそこはいいのだけれども、そうではなくて、もっと前向きに取り組むときの費用があるではないですか。","respondent":"遠藤商業・ものづくり課長","answer":"今後いろいろ設備資金など、いろいろな融資の形があります。そういう部分で、区としてどういうことができるか、いろいろな案が出てくるかと思いますので、研究をさせていただければというふうに考えてあります。","voiceIndex":381,"id":"exchange-170"},{"speaker":"石田（秀）委員","kind":"質問","question":"多分、省エネは勉強するのはそんなに難しいことではないと思うのです。創エネだと思うのです。そういう映像とかはいっぱいあるし、漆喰なども、ぜひそういうものは、鳥インフルエンザに見たてて白い粉をまくとか、姫路城を見ても分からないけれども、そういう感じのものをぜひ子どもたちに、そういうものでやってほしいなと思うのだけれども、最後にそれだけ伺います。","respondent":"河内環境課長","answer":"そのときの反応ですが、やはり直に生の木に触れるという点で、非常に驚きと喜びということがあり、戻ってきてからの講座でそういったことが活発に議論されました。そういったところの特徴を活かしながら進めてまいりたいと考えているところです。","voiceIndex":383,"id":"exchange-171"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":130724,"voices":385}},{"id":"r04-20220311-3","meetingId":"r04-c-budget","date":"2022年3月11日","dateIso":"2022-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を159件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村委員","kind":"質問","question":"おはようあります。３１１ページ、しなみちレポートの拡充、３４７ページ、避難行動要支援者経費について伺ってまいります。長くなってしまいましたが、このような訓練を受けて、地元の方たちからいただいた課題を３点伺います。１つ目です。要支援者情報と町会の把握しているリストとの整合性をどのようにしていくのか、町会と福祉事業者が持っている要支援者情報をどのように統一していくのか伺います。","respondent":"山本防災課長","answer":"一方で、福祉関係者につきましては、また、それ独自のデータ等を保有していることも承知をしていますので、今後、その情報だったり、データの共有方法につきましては、関係部署とも連携しながら、管理しやすい方法というところを検討していきたいというふうに考えてあります。","voiceIndex":4,"id":"exchange-001"},{"speaker":"西村委員","kind":"確認","question":"懸念しておられましたのが、有事に限られた役員数での要支援者の安否確認が大変だということ、また、その他消火活動と同時になってしまうということを懸念しておられました。災害の程度にもよりますけれども、町会の担当者が優先して一次支援から三次支援までの安否確認をするため、福祉事業者から安否確認の連絡をもらっても対応できるのかとおっしゃっておりました。ご答弁をお願いいたします。","respondent":"山本防災課長","answer":"来年度の避難行動要支援者事業の中で、災害発生時の支援における防災区民組織、それから福祉関係者の役割分担であったり、具体的な連携方法については、検討していきたいと思っているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"西村委員","kind":"提案","question":"これはご提案ですけれども、今後有事の際に、産後のお母さん、赤ちゃん、多胎児家庭も確認して、地域と連携する仕組みがつくれないだろうかと、これは私自身も研究しながら考えているところです。最後に、要支援者、家族に対しまして、事前の備蓄の啓発をお願いしたいと考えています。区のご見解をお聞かせください。","respondent":"山本防災課長","answer":"今福祉部のほうで避難行動要支援者の個別避難計画の作成というものを進めておりますが、この計画をご本人様に説明する際に、そういった自助の促進、備蓄の促進というところをご説明できるよう、今後進めていきたいというふうに考えてあります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"１点好事例、またご報告させていただきたいのですが、町会のほうで全役員の方に用意した、要支援者安否確認訪問用バッグというものがとてもよかったです。次の質問に移ります。道路のみならず、公園の損傷も通報できるようになっているということで、遊具やトイレ、カーブミラーなど様々通報できると思いますが、河川の通報はできるのでしょうか、伺います。","respondent":"溝口道路課長","answer":"今回、４月から本格導入する、しなみちレポートの住民通報システムの件ですが、河川といいますか、河川に即した、沿った形で道路があると思います。そういったところも一応区のほうで、私どもが管理しておりますので、併せて今回通報していただけるかと考えているところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"西村委員","kind":"確認","question":"通報対応のフローの確認をします。これまでは通報があった場合、電話でやり取りをされていて、一つひとつ地図を開いて確認されていたと思います。手間が大幅に省ける取組みになるのではないかと思いますが、３点伺わせていただきます。１つ目が区の管理物でなかった場合どのようにされるのか。２点目が、必ずしも補修などを行うものではない場合があると思うのですが、どのようにされるのか。","respondent":"溝口道路課長","answer":"今回のシステムで一番いいところは、区民の方から受け付けたもの、それをすぐ区のほうで、どのような対応をしていくのかという対応経緯が、その方に分かるような形で流せるということが１つの大きなシステムの利点です。","voiceIndex":12,"id":"exchange-005"},{"speaker":"西村委員","kind":"質問","question":"他区ですと、１か月レポートのような形でホームページにアップをされているような地域もあるのですけれども、この仕組みの場合は、例えばＬＩＮＥのように一人ひとりとやり取りができるという認識だと思いますので、どのように区民の皆さんに、通報があって対応されたかということが報告されるのか、お伺いさせてください。","respondent":"溝口道路課長","answer":"その後対応状況等、進捗に応じて、補修したとか、そういったものを出すということと、あと補修状況についての写真というものも併せて載せるような形にしておりますので、区民の方が通報したものが、どのように区のほうで処理されたのか。","voiceIndex":14,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"３０９ページ、道路・公園等占用費、３１７ページ、（仮称）勝島人道橋詳細設計、３２３ページ、立会川・勝島地区まちづくり検討経費、３４９ページ、備蓄物資購入、時間がありましたら、３４９ページ、防災情報配信経費についてお伺いしてまいります。本日、３・１１東日本大震災より１１年目を迎えました。１点目に、道路・公園等占用費について、八潮地区の停電についてお伺いします。","respondent":"稲田土木管理課長","answer":"２月１５日午前１時２０分に発生して、その日の６時４分に全域送電が完了したという状況ですが、これは私ども道路管理者が、占用許可で東京電力の埋設管等を許可していますので、私どものほうから東京電力に対しまして、原因と、それから今後の対応、その辺を東京電力の方を呼び。","voiceIndex":18,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"勝島人道橋、また、立会川・勝島地区まちづくり検討についてお伺いしてまいります。具体的な詳細設計ということで、予算が計上されてまいりました。地域の皆様の思いが形になっていく第一歩であります。人道橋の設置のスケジュール、また、大変大規模な事業になると思うのですが、予算規模をどれぐらいと見込んでいるのか、また、財源はどうなっているのか、お伺いいたします。","respondent":"鈴木都市計画課長","answer":"事業規模的なところは、これから来年度、人道橋の詳細設計を進めていくことになりますので、その中で総工事費等の予算的なところが明らかになっていくというところと、それから、予算の枠組み、この事業の枠組みですが、今ご説明した都市再生整備計画の中で。","voiceIndex":20,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"かねてより、公衆便所については要望をいただいておりまして、このしながわ花海道、併せて新浜川公園の改修とともに、新浜川公園の中にある公衆便所の位置をご検討いただきたいということも、かねてから要望していますが、この件も併せて、時間がかかることと思うのですけれども、ご検討いただけるのか、ちょっと今の検討状況をお知らせいただきたいと思います。","respondent":"高梨公園課長","answer":"公園の中のトイレについての、付近の住民からの声というものも、しっかり公園課としては受け止めておりますので、全体改修の中で、そういった声も配慮しながら、また、そのほかの住民の声も聴きながら、皆さんの声を聴いて改修計画に活かしていきたい。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"当初、この令和４年１月に素案に対する意見を募集し、また３月、ガイドライン取りまとめというふうに伺っておりました。このガイドライン策定に当たっては、町会、自治会はもとより、とにかく若い方々、これからの八潮地域を担っていく若い方のお声を聴いてほしいということの要望を続けてまいりましたが、この点に関しましてどのように反映していただいたのか、また、今後のスケジュールをお知らせください。","respondent":"鈴木都市計画課長","answer":"ワークショップ自体は、自治会、管理組合の方を対象に、１１月１９日に一度行っておりまして、先ほどご紹介いただいた、やはり地域の方、いろいろな世代の方のお声をお聴きするということで、１２月１１日には。","voiceIndex":24,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"若い方のお声を聴いていただいているということで、大変安心いたしました。多分若い方は、自治会や、また管理組合の方とは違ったご意見があったかと思いますので、ぜひそのご意見を反映していただきたいと思います。続きまして、備蓄物資購入について伺います。この低たんぱく米等ということで、そのほかに何が新しく備蓄物資の中に含まれているのか、お知らせください。","respondent":"平原防災体制整備担当課長","answer":"次年度新たに導入する備蓄物資の予定ですけれども、今、委員ご指摘のとおり、低たんぱく米を新たに導入することとしたところです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこが大きな課題だったというように、これまでのご答弁でいただいておりましたが、どのような仕組みで活用されるのかということを確認させていただきたいということと、これまで品川区の区内企業であるＫ－ＰＯＲＴと、この液体ミルクに関しては協定を結んでいたかと思います。そのことと、また、東京都から物資がもらえる、その液体ミルクのこの関連についてお知らせください。","respondent":"平原防災体制整備担当課長","answer":"通常の備蓄品と違いまして、温度管理が非常に難しいということで、こちら私どものシステムがありますサーバーを管理している部屋、年中空調が効いておりますので、そういったところに入れるというものです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"横山委員","kind":"質問","question":"私からは３１１ページ、しなみちレポート、３４１ページ、空き家等対策事業、３４３ページ、居住支援事業について、また、時間がありましたら、３３５ページのＰａｒｋ－ＰＦＩ導入に向けた調査・検討についてお伺いいたします。１点目に空き家等対策事業、居住支援事業についてお伺いいたします。","respondent":"竹田住宅課長","answer":"居住支援として区で実施している制度、および居住支援協議会による主な活動ですが、居住支援として、ひとり親世帯など、自分で住まいを探すことが困難で、住居の確保に配慮が必要な方の民間住宅探しを支援する制度を今年度からスタートしております。","voiceIndex":31,"id":"exchange-013"},{"speaker":"横山委員","kind":"提案","question":"プレスリリースには、民間事業者を活用した空き家の有効活用提案による適正管理の促進とあります。そこで、個別の物件の状態などにもよるかと思いますが、空き家活用の提案書の中に、母子世帯向けのユニークで先駆的な事例なども入れていただきますよう要望いたします。しなみちレポートについてお伺いいたします。公園投稿の試行運用につきましては、どのようなイメージなのか教えてください。","respondent":"竹田住宅課長、溝口道路課長","answer":"委員ご指摘のとおり、居住支援協議会、区の福祉部門、民生委員を含めた地域の方々にも、ぜひご協力をいただいて、住みやすいまち品川の実現に向けて力を尽くしてまいりたいと考えております。併せて公園のほうになりますが、公園課とも連携しまして、今年の４月から、公園のほうは試行になりますけれども、公園の中の遊具、または樹木の管理とか、そういったところについて投稿いただけるように。","voiceIndex":33,"id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"しなみちレポートのほうも、有効性が確認されているということと、使っていただいている方にも、今後も使っていきたいというような結果が出ているということで、ぜひ試行、公園の試行のほうも引き続き続けていただきたいと考えています。３点目に、Ｐａｒｋ－ＰＦＩ導入に向けた調査・検討についてお伺いいたします。区として今後公園をどうしていくのかというビジョンについてお聞かせください。","respondent":"高梨公園課長","answer":"なかなか小さな公園ですと、中に建設できる建物の規模が限られてまいりますので、例えば東品川海上公園であったり、区民公園であったりというような面積を有する公園、または水辺等の特色のある公園から調査を開始してまいりたい、このように考えているところです。","voiceIndex":36,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"様々、今ご説明いただきましたけれども、公園ですが、コロナ禍でいろいろな使い方がされていたり、地域の方のお声もいろいろあるところです。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"３２５ページ、（仮称）西大井三丁目防災広場整備、３２７ページ、市街地整備事業費より西大井一丁目南地区まちづくり協議会について、それぞれ伺いたいと思います。解体工事を進めるに当たって、このネズミとアスベストの対策を十分に取っていただきたいという点と、解体工事を行うに当たっての説明会では、どのような対策が講じられるのか丁寧に説明をしていただきたいと思いますが、いかがでしょうか。","respondent":"小林施設整備課長","answer":"これらの内容につきましては、説明会、現在のところ１２月頃を予定しておりますが、しっかりと対応してご説明のほう図っていきたいと考えています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"ご近所の方心配されておりますので、丁寧な対応を要望したいと思います。次に、西大井南について伺います。西大井南について、まちづくりニュースは何号まで出ているのか、伺いたいと思います。そして、この事務局を支援する東京建物株式会社ですが、この事務局とどのような内容の協定書を交わしているのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"それで、令和２年の、今ご紹介のあった８月に、まちづくり協議会ということで新しく設立されて、現在このまちの地区について、どのようなまちに進めていくかということで検討されているところです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"端的に伺ったことを答えてほしかったのですけれども、まちづくりニュースは５号まで出ているとのことでした。先ほど伺ったのは、事務局を支援する東京建物株式会社は、事務局とどのような内容で協定書を結んでいるのかと伺いましたので、東京建物と交わした協定書の内容について、改めてご説明いただきたいと思います。","respondent":"多並都市開発課長","answer":"その協議会として、やはり行政との関わりということで、このまちづくりで進めている勉強、進めている方向が、区の方向性についても、いろいろ話し合って情報を聞きたいということで、そのような観点で事務局がいらっしゃいますので。","voiceIndex":46,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、協議会の総会や会議に品川区は何回出席したのかと伺いました。先ほどから聞いてもいないことをのうのうと述べて、時間を稼ぐのはやめていただきたい。これは率直に指摘したいと思います。改めて出席回数を伺います。なぜならば、この課は再開発を進める組織だからです。現状、この協議会に何人の地権者が参加しているのか、そして参加企業はどこか伺います。質問だけお願いします。","respondent":"多並都市開発課長","answer":"加入者としましては、約３８％の方が出席されているということで、約２９軒の方が加入されているということをお聞きしています。関連する企業としましては、東京建物株式会社、また、コンサルとしては、久米設計というところが関わっているということでお聞きしているところです。","voiceIndex":48,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"西大井の活性化についてお伺いします。効果が出てくると思うのですけれども、なので、原踏切の件ですが、どうにかもう今のうちから考えていただきたいと思うのですけれども、お伺いします。その中で、これも何回も言っておりますが、西大井駅の西口に相互通行できる改札口をぜひつくっていただきたいという要望をさせていただいていますけれども、その辺についてはいかがでしょうか。これは通れないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"すみません。その中で、首都直下および南海トラフと同時に富士山が噴火したらどのようになるのでしょうかという質問をしました。そうしたら答弁が、そのようなことはまだ予想していないというような答弁だったのですけれども、もうこれはきちんと分析をして、対策等、区でできる対策等はしていっていただきたいと思うのですが、いかがでしょうか。","respondent":"栗原河川下水道課長、稲田土木管理課長、溝口道路課長、鈴木都市計画課長、森木密整備推進課長、長尾建築課長、竹田住宅課長、山本防災課長","answer":"この工事は平成２４年に着手いたしまして、今年の２月に延長約３００ｍ、直径１ｍの下水道管、維持管理のためのマンホール。現在２００ｍから３００ｍの範囲で３か所ほどあるのですけれども、やはりちょっと直近ではないというところで。そういった中、そこにつながる２０５号線、区が整備する都市計画道路になりますので、やはり一体的に整備することによって。そうしたところをしっかりマスタープランのほうでも記載していきたいというところで今考えているところと、ご提案いただいている。","voiceIndex":53,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"でも、やはり実績を、数字を見て、ここはなどといろいろ調整していくと思うのですけれども、２年連続でゼロというものに予算をつけていくということは、昔は事務事業評価があって、Ａ、Ｂ、Ｃなどとついていたではないですか。だけれども、これ、それがあったらもうＣや廃止というように、私はなると思うのですけれども、その辺についてはいかがでしょうか。","respondent":"佐藤企画調整課長","answer":"３点目、委員ご指摘のとおり、必要性、ニーズに関しましては、２年連続で実績がないというところで、なかなか厳しい判断になるのかなとは思いますが、来年度全戸訪問もするというところで、将来的な事業の必要性というところもある程度見込んで。","voiceIndex":62,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、今答弁いただいて、将来のと出ましたので、これは来年、令和４年度の実績を見てから、また質問をさせていただきたいと思いますので、よろしくお願いします。ですから、この件においては、地震においてはいろいろな方も質問しておりますが、噴火に関しては質問があまり出てこないので、私は噴火一本でこれからも伺っていきたいと思いますので、今後ともよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-024"},{"speaker":"吉田委員","kind":"提案","question":"それから３２９ページ、都市開発費、広町地区整備検討、３３５ページ、緑化活動支援事業で、屋上緑化等について伺います。しながわ防災訓練ガイドの活用について伺います。最初に広町地区整備検討について伺います。広町地区の土地区画整理事業について、昨年１１月３０日の建設委員会の資料を確認いたしました。そのほかに、事業者が東京都に提出した地区計画の企画提案書を、情報開示請求して得ました。","respondent":"多並都市開発課長","answer":"私からは広町地区についてお答えします。土地区画整理事業につきましては、建設委員会の中でも、事業計画の案ということでご説明させていただきました。","voiceIndex":66,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"開発区域外のほうは何となく分かりました。まだこれから値段を決めるということですけれども、先ほど質問した中で、そのような値段を決めるのもＵＲに全部任せてしまうのでしょうか。これ、例えばその中に品川区の土地もあるかと思うのですけれども、そのようなことで品川区は価格の設定などには関わらないのでしょうか。ぜひその辺について教えていただきたいと思います。","respondent":"多並都市開発課長","answer":"その値段の決め方につきましても、公平性の観点からＵＲ都市機構がやって、国の基準等に沿いながら、適正に評価をして、それをまた第三者で見るということで、そのような形で公平性があるということで、区としてもそのような認識です。","voiceIndex":68,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"客観性というと、とても聞こえがいいのですが、品川区の土地について、品川区が何も関われないということは少し納得がいかないので、簡単にもう一度伺いたいと思います。これをやっていると、これだけで２０分使ってしまうので、ずっと飛ばして、公園管理費について伺います。屋上緑化です。助成をするなら、その先の仕組みも一緒に構築すべきだったのではないでしょうか。それについて伺います。","respondent":"多並都市開発課長、高梨公園課長","answer":"先ほどの土地の、いわゆる価格についてのお話ですけれども、これは、要するに区が関わるというよりは、区も土地所有者でして、国も土地所有者、都も土地所有者、行政が関わっていますが、そうではなくて。屋上緑化助成についてのご質問です。公園課といたしましても、屋上緑化をしていただいた後の、その継続といったところは、非常に大きな課題であるというふうに感じております。","voiceIndex":70,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"屋上緑化で、この方は多分お金を求めているのではないです。その仕組み、引き取るところまで持っていくとか、そのようなことは負担するとしても、その引取り先がないということについて、大変、何か考えるべきではないかというご意見でした。ＣＯ２削減と言っているときに、区内であっても緑が果たす役割は大きいと思うのですけれども、その辺についてはいかがお考えでしょうか。","respondent":"高梨公園課長","answer":"前段の屋上緑化に関する土の処分について、土の終わった後というか、この入れ替えの際の処分について、土をどのようにしたらいいかといったところは、公園課には園芸に詳しい職員もおりますので、その土を、例えば、多分捨てるだけではなくて。","voiceIndex":73,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"屋上緑化については、確かにぜひ仕組みを一緒につくって、それで助成金を出していただきたいと思います。その更新のやり方も。だから、その辺についてのリスク、それはどうしても発生しますということはきちんと説明するべきではないかと思います。これは要望にとどめます。しながわ区民公園の木です。そのようなことについて、どこにどのように注意を呼びかけていらっしゃるのか、現状を伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"ただ、今コロナ禍におきまして、なかなか出前型など、そのようなものが開催できないという状況ですけれども、警察とも引き続き連携しまして、そのような事故の発生状況等をそういう方々に周知できるように努めてまいりたいと考えております。","voiceIndex":75,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。何ですか、電動キックボードでしたか、何かそのようなものもいろいろ、便利な分危ないことも出てきています。高齢者への呼びかけというのは、高齢者の交流会なども今減っている状況なので、なかなか難しいと思いますけれども、広くご家族への呼びかけとか、そのようなことも含めてやっていただきたいと思いますが、改めてちょっと見解を伺います。","respondent":"川口交通安全担当課長","answer":"警察におきましても、高齢者を対象とした、いろいろな交通安全の普及啓発に関するチラシ等を作成したりなどしていますので、これをまた区でも、どのような形で区民の方々に周知できるかというところも併せて検討していきたいというふうに考えております。","voiceIndex":77,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひよろしくお願いします。最後ちょっと時間がないので、要望だけしておきます。しながわ防災訓練ガイド、とてもいい冊子で、中に細かく、いろいろな訓練の仕方なども書いてあって、ぜひそれをやってみたいという区民の方がいらっしゃいます。区に聞いたら、町会などでないと対応できないと。人数など。ぜひ今後、そのような仕組みも考えていただきたいと思います。これは要望だけにとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"},{"speaker":"木村委員","kind":"質問","question":"私からは３０９ページ、下から７行目、駅周辺等放置自転車対策事業から質問いたします。この事業には、令和３年度は約４億４,１００万円の予算、そして令和４年度は約４億９,４４４万円の予算が組まれています。もし、それ以外何か方法が、減額する方法があるとすれば、どのようなことがありますか。お聞かせください。","respondent":"川口交通安全担当課長","answer":"ただ、長いスパンで見ますと、この放置台数も減りつつありますので、引き続き広報啓発に努めて、正しい安全な利用をしていただくということ、また、自転車を駐車される場合は、自転車駐車場をご利用いただくという啓発活動を引き続きしていきたいというふうに考えております。","voiceIndex":81,"id":"exchange-032"},{"speaker":"木村委員","kind":"質問","question":"やはり撤去台数ですか、それが減っているということはないと思いますし、本当に毎日毎日撤去をするわけですから、大変な台数が出ると思いますけれども、よろしくお願いします。これは撤去することによって、自分たちがそれを処分しなければならない、そのようなことを免れるためにわざと路上に止めておく、このようなことがあるのかどうか、前例があるかどうかをお聞かせください。","respondent":"川口交通安全担当課長","answer":"確かに、自転車が放置されている場合、区のほうでは必要に応じて撤去を行っているわけですけれども、当然撤去が行われた場合に関しましては、その引取り手がないという場合もありますので。","voiceIndex":83,"id":"exchange-033"},{"speaker":"木村委員","kind":"質問","question":"海外では、ロンドンやパリにおいては既に１００％の無電柱化を達成しておりますが、現在の日本におきましても、まだまだこれからといったところ、近年では災害で倒壊した電柱により、救助の妨げになるケースなどもあるとお聞きいたしました。本区においても、この区道約３２７kmのうち、約２３km、約７％しか、まだこの無電柱化が進んでいないということをお聞きいたしました。","respondent":"溝口道路課長","answer":"無電柱化につきましては、令和２年度に無電柱化推進計画というものを品川区はつくって、今、無電柱化の整備を進めているところです。","voiceIndex":85,"id":"exchange-034"},{"speaker":"木村委員","kind":"質問","question":"本当に気の遠くなるような話でありますけれども、ぜひともお願いしたいと思います。お聞きいたします。本区の無電柱化事業は現在どのように進んでいるのか、一説には、地中化のスピードより逆に電柱が増えているともお聞きしたことがあるのですが、現在とこれからの本区の工事の進行状況はどのようになっていくのでしょうか。お聞かせください。","respondent":"溝口道路課長","answer":"委員ご指摘の令和元年度に基本方針というものをつくりまして、令和２年度に推進化計画をつくっています。その中で防災の重要性や景観、そういったものも踏まえた中で、重点的に優先的に整備する路線というものを定めております。","voiceIndex":87,"id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"先ほど横山委員からの質問に対する答弁で、まずは検討ということで、規模の大きいところというような話があったかと思うのですけれども、大体基準としてはどのくらい、何平米ぐらいを想定して、何平米以上のところというふうに想定されているのか伺います。","respondent":"高梨公園課長","answer":"規模についてですけれども、平米数で絞って、１万平米以上などというような基準では考えてございません。","voiceIndex":92,"id":"exchange-036"},{"speaker":"松本委員","kind":"質問","question":"というのも、都内でいったら渋谷区で、北谷公園ですか、あそこがこのＰａｒｋ－ＰＦＩを活用して、あそこの規模は１,０００平米を下回っているということで、かなり小さい規模になっていました。いろいろなやり方があると思っています。そういった、まだこれから調査・検討の段階だと思うのですけれども、そういったテーマの方針というものが、もし今の段階で何かありましたらお願いいたします。","respondent":"高梨公園課長","answer":"ご案内のとおり、来年度そういった事業者の声も聴きながら、可能性を見いだしていきたいというふうに考えてありますので、その中で区としてもしっかり方針を探していければなというふうに考えてあります。","voiceIndex":94,"id":"exchange-037"},{"speaker":"松本委員","kind":"質問","question":"続きまして、ブロック塀についてですけれども、これは何が聞きたいかといったら、ブロック塀だけではなくて、総務課の款でもお伺いした自動販売機との関係で聞きたいなと思っているのですが、まずブロック塀については、平成３０年の大阪府北部地震で、倒壊したブロック塀による人的被害が発生したことなどをきっかけに、改めて注目を集めていると。お願いします。","respondent":"長尾建築課長","answer":"安全性が確認できないものの数量といったところは、具体的には、統計的に整備はしていないですけれども、やはり塀の傾きであるとか、あと足元部分が破損しているとか、ひびが入っているとか、そういった部分は道路側からも確認できておりますので、そういったところをもって。","voiceIndex":96,"id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"ただ一方で、この自動販売機、高さの標準が１８３cmと言われていて、重さでいったら数百kgぐらいになるというような話だと思います。ということで、区としても、ブロック塀と同様にこの自動販売機、どこに自動販売機が設置されているかということも、現状届出制もないので把握できていないと思うのですが、１回自動販売機についても調査をされたほうがいいと思うのですけれども、いかがでしょうか。","respondent":"山本防災課長","answer":"区のほうの自動販売機の対策というところでは、地域防災計画の中で転倒防止対策の強化というところは記載をしていますが、具体的な対応というところは今後考えていきたいと思っているところです。","voiceIndex":98,"id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"このような、例えば対策が取られていないとか、あるいは老朽化でちょっとねじが緩んでいるというようなものを見たら報告してくださいというような、そのようなやり方もあると思いますが、区民の皆さんからのお力を使うというようなやり方については、いかがお考えでしょうか。","respondent":"山本防災課長","answer":"区民からの通報です。確かに地域の方々からご意見をいただいて、それを集約するというところは、１つ効率的な方法かと思いますので、どういった仕組みでできるのかというところも含めまして、いろいろ研究等を進めていきたいと思ってあります。","voiceIndex":100,"id":"exchange-040"},{"speaker":"小芝委員","kind":"質問","question":"私からは３２３ページ、地域交通検討経費、コミュニティバスについてお伺いいたします。いよいよ３月２８日から、西大井駅と大森駅を循環しますコミュニティバス、通称しなバスが試行運行を開始します。昨年３月に開かれました地域公共交通会議の後、本区が警視庁との協議をする中で、西大井を循環するルートは、道路幅の狭さという問題により、通行するのが難しいとの課題が出てきたと私は認識しております。","respondent":"鈴木都市計画課長","answer":"ご提案いただいた考え方というのは１つあろうかと思うのですが、やはり区としては、まず、この循環ルートについては、一定程度の輸送量が確保できる、今想定しているタイプの車両を、警察との協議の中で何とか進めていきたいというところで、その１つの打開策として。","voiceIndex":104,"id":"exchange-041"},{"speaker":"小芝委員","kind":"確認","question":"ぜひ前向きに検討していただければと思います。確認のほうさせていただきました。よくバス停の前には、路面にバス停と表記されている道もあるわけですが、そうすることで、一般の車両が駐停車することを防いだりとか、あと自転車の方にも注意を促す効果があると思うのですけれども、こういったバス停の前での白線の表示というものはされるのかどうか、お答え願えますでしょうか。","respondent":"鈴木都市計画課長","answer":"新規にバス停を整備するところについては、今お話しいただいた、荷さばきですとか、あるいはタクシーですとか、そうした一時的な駐停車を注意していただくという注意喚起を込めて、そうした白線を整備していくと。運行開始までに整備していくです。","voiceIndex":106,"id":"exchange-042"},{"speaker":"小芝委員","kind":"質問","question":"バスの収支率について伺います。収支率をその年度ごとに見て、３年目の収支率が５０％以上かどうかで、その後の本格運行を判断するということを聞いておりますが、収入は恐らくこの運賃を軸にして、そのほかの収入も含まれてくるのではないかと思われますけれども、この収入の考えについて教えてください。","respondent":"鈴木都市計画課長","answer":"収支率を考える場合の収入の部分につきましては、やはり大きくは運賃収入というところでございまして、それ以外のところとしましては、やはり広告料ですとか、そうした費用も見込んでいくというところになろうかと思います。","voiceIndex":108,"id":"exchange-043"},{"speaker":"小芝委員","kind":"質問・要望","question":"私はシルバーパスもぜひ金額換算した上で、この収入に組み込んでもらいたいと考えますが、どうでしょうか。コロナ禍により外出そのものが減っている現状と、また、今後の経過によっては、５０％の数値目標をもっと柔軟に評価していただきたいと考えますが、その辺り、２点についてお答え願えればと思います。","respondent":"鈴木都市計画課長","answer":"この辺の状況も踏まえながら、その収支率の線引きをどのようにしていくかということは、まずは、やはり５０％というところでスタートしたいというふうには考えてありますが、これも、一方ではその運行状況等を見ながら柔軟にといいますか、しっかり検討していきたいです。","voiceIndex":110,"id":"exchange-044"},{"speaker":"小芝委員","kind":"質問・要望","question":"最後に、この２８日から試行運行が始まる予定ですけれども、始まりましたら、ぜひ乗客のおおよその住まいだとか、例えば何丁目に住んでいるのかとか、あと何歳代の方なのか、そういったものを含めましてアンケートをして、ぜひニーズを把握していただくことで今後の検討に生かせると思うのですが、そういったアンケートをしてフィードバックしていくという、そういった考えというのがあるのかどうか。","respondent":"鈴木都市計画課長","answer":"今ご質問いただきました、利用者あるいは周辺の方へのアンケートというものはしっかり実施して、その結果を踏まえて、中身も検証しながら、改善を加えるところは加えながら、利便性の向上、利用者。","voiceIndex":112,"id":"exchange-045"},{"speaker":"小芝委員","kind":"意見","question":"３年目の収支判断に向けまして、試行錯誤を繰り返していくことが必要と考えます。ぜひこのアンケートを取ってもらいたいと考えます。その上でフィードバックを行い、適宜改良を重ねていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"午前中にも質疑がありまして、古くは２０１２年ですが、当時武雄市がフェイスブックを活用して、市民との様々な情報交換、交流、そしてこうした不具合の箇所等も、フェイスブックの双方向性というものを活用して施策に活かしていたというような事例を通して、フェイスブックを採用したらどうでしょうかというような、地域課題の解決の手段として私も提案させていただいていて、また、２０１９年にも。","respondent":"溝口道路課長","answer":"来年度につきましては、予算書のとおり、公園の試行も含めて、道路課のほうで取っている５００万円弱の予算で、今回のしなみちレポート、そういったものが行えるということになっているものです。","voiceIndex":117,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"そうすると、しなみちレポートとなると道路に非常にフォーカスしたような愛称というか、事業名なので、公園のほうについても同様の愛称といいましょうか、そういうようなことで展開していくのが分かりやすいのかなというところと、それに併せて、公園への拡大というところをやっていただくのですが、これは今、既にしながわパパママ応援アプリにも載せていただいているなどあるのですけれども。","respondent":"溝口道路課長、高梨公園課長","answer":"今後公園にも拡大して、本格運用する際には、しっかりと区民の方に親しまれるような名称、そういったものも併せて検討していきたいというふうに考えているところです。ただ、やはり公園の利用者の方の目につくところに、こういったシステムがあるということを知っていただくことは非常に重要で、有効なことだというふうに考えておりますので、公園現地での広報の仕方については。","voiceIndex":119,"id":"exchange-048"},{"speaker":"つる委員","kind":"確認","question":"ぜひ公園での、現場での掲示、よろしくお願いしたいと思います。次はＰＦＩについて伺います。本会議でも確認させていただきましたけれども、これは建設委員会で示された水とみどりの基本計画・行動計画素案、今月末にはそれが策定される予定であると思うのですが、その中の事業スケジュールで、Ｐａｒｋ－ＰＦＩの推進の中の運用が、目標年度が令和１３年度となっている。","respondent":"高梨公園課長","answer":"もう１点、エリアについてですが、なかなか荏原地域の中に大きな公園がないですけれども、来年度、事業者との対話の中で、荏原地域の公園の中での事業性等についてもヒアリングするなど、取組みを進めてまいりたいというふうに考えてあります。","voiceIndex":122,"id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"ぜひスケジュール、少しでも早くというところと、また荏原地域についても、そのような適地、ぜひ推進をお願いしたいと思います。次に移ります。過去、２０１６年の予算特別委員会のときに、この大空襲については、５月２４日、この日が品川区においても非常に被害が大きかった日ということで、この日をしながわ平和の日として、いろいろな施策に展開したらどうでしょうかという提案もさせていただきました。","respondent":"高梨公園課長","answer":"ただそのマークだけがあれば、もしくはその模したものだけすればといったものではないとも考えておりまして、しっかりその公園においては説明も必要なのかなと考えています。平和を担当する部署とも連携しながら、取組みをさせていただければと考えております。","voiceIndex":124,"id":"exchange-050"},{"speaker":"つる委員","kind":"提案","question":"毎回聞いています。２０１９年の１定では、桜などについての記念植樹についても提案をさせていただきました。これは植樹祭という形で、学校でやられるわけでありますけれども、ぜひ今後も、この桜、１本でも多く品川区内に植えていただきたい、また、駅に植えていただきたいという思いがありますので、最後の残りの時間で、この桜についての品川区の取組みを教えてください。","respondent":"高梨公園課長","answer":"自らの人生のイベントごとに、その桜の思い出がともにあるようなものだと考えています。今回の事業を通じて、その思い出、その木がたとえ枯れてしまっても、その思いが未来永劫生き続けられるようにという思いを込めて、しっかりこの事業を進めてまいりたいと考えております。","voiceIndex":126,"id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３１３ページ、立会川緑道整備（２工区）、３２５ページ、不燃化特区支援事業、３３３ページ、みんなに愛される公園づくり、３３５ページ、Ｐａｒｋ－ＰＦＩ導入に向けた調査・検討についてお伺いいたします。初めに３１３ページ、立会川緑道整備（２工区）についての質問をします。いよいよこの最後となる第２工区の工事が、来年度予算に計上されております。危なくないという声もいただいております。","respondent":"溝口道路課長","answer":"地域でイベントが盛んに行われてきたという経緯も踏まえていますので、整備に当たっては、もともと皆さんに説明会などで説明したとおり、広場型の整備をしていって、地域の方たちに今後イベント等、そういったもので使っていただける。","voiceIndex":129,"id":"exchange-052"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続いて３２５ページ、不燃化特区支援事業についてお伺いいたします。１０地区の中の旗の台四丁目、中延五丁目地区についてお尋ねいたします。令和７年度までに、士業の派遣検討、密集住宅市街地整備促進事業の計画検討、権利者の調整、住宅の建築物耐震化支援事業と、いろいろあると思うのですけれども、なかなか進んでいないかと思うのですが、現在の現状、進捗状況をお知らせいただきたいと思います。","respondent":"森木密整備推進課長","answer":"そういった声を丁寧に聴きながら、こういった機会を逃さずに事業を進めてまいりたいというふうに考えているところです。","voiceIndex":133,"id":"exchange-053"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今交渉の段階で、すぐというわけにはいかないと思うのですけれども、なるべく早めに、早急にいろいろ整備というのは、恐らくこれ大変な作業になるかと思いますが、今現在そこの一軒長屋、いわゆるハーモニカ通りのところの、大体どのぐらい、今何割ぐらいの方に対して交渉しているのかということもお知らせいただきたいと思います。","respondent":"森木密整備推進課長","answer":"全地区で全て一遍にやるということはなかなか難しい部分もあろうかと思いますので、そういった方々のまとまりで、まずはちょっと考えていきたいと思っているところです。","voiceIndex":135,"id":"exchange-054"},{"speaker":"高橋（伸）委員","kind":"提案","question":"分かりました。コミュケーションサインというものが書いてありますけれども、この来年度予算に関して、予算の中で、みんなに愛される公園づくりというものは、今後お子さんを含めて、私たちの会派からはインクルーシブ公園というものも提案していますが、これからの展開、いろいろ公園に関してはあると思いますけれども、どのようにお考えになっているのか教えていただきたいと思います。","respondent":"高梨公園課長","answer":"来年度につきましては、源氏前公園および特定児童遊園で全体改修、今年度設計作業を行っておりますけれども、そちらのほうでインクルーシブ遊具を設置ということで、現時点では考えているところです。","voiceIndex":137,"id":"exchange-055"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ぜひとも、これからも要望しますので、インクルーシブ公園への展開よろしくお願いいたします。これは２０１７年の都市公園法改正によって新設された制度だと思うのですけれども、この説明、開始された制度、Ｐａｒｋ－ＰＦＩに関しての説明を、まず最初にお伺いいたします。","respondent":"高梨公園課長","answer":"本制度を利用しますと、今まであった公園施設の設置管理許可の許可期間は１０年間ですが、最長２０年間まで許可をすることができるという特例や、建蔽率の特例、公園施設によって定められておりますけれども、原則２％とされている建蔽率、こちらについて。","voiceIndex":139,"id":"exchange-056"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今ご答弁ありましたように、設置管理許可が、通常だと１０年が上限でそれが２０年になるということ、あと建蔽率も２％から１２％となっています。でも都市公園法で規定する、何というのですか、公募の対象の公園施設というのは、ちょっと同じような質問になるかと思いますけれども、やはり幅が、大きさというものは当然あると思いますが、そこをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"ただ目新しさであったり、今のはやり廃りだけではなくて、しっかりその地域の方と一緒に連携が取れる、利用していただくといったような施設を、内部の検討だけではなくて、地域の声も聴きながら検討を進めてまいりたいなというふうに考えているところです。","voiceIndex":141,"id":"exchange-057"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。今年の１２月にはオープンするという話も伺っている中で、これは民間事業者のイオンからも、何というのですか、この無電柱化というか、バリアフリー工事がもう済んだところに新しく今これから建つわけですけれども、イオンが何か区に対して、何か道路に関しての取組みとか、何かそのような声はいただいているのですか。それだけお分かりになれば、ひとつ確認させていただきたいと思います。","respondent":"溝口道路課長","answer":"個別の商業ビルの建設の件で、特段道路についてということはありませんが、開発環境指導要綱にのっとった形での歩道状空地とか、そういったところのお話はいただいているところです。","voiceIndex":143,"id":"exchange-058"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"すみません、突然に。もしそのような声があったら、ぜひいろいろと検討していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-059"},{"speaker":"おくの委員","kind":"質問","question":"私からは、３２９ページ、武蔵小山駅周辺地区再開発事業に関わって、小山三丁目第１地区、第２地区の再開発について質問いたします。この地区の再開発については、昨年の３定や、今回の１定の一般質問でも取り上げてきました。私はその声を２回の一般質問で紹介してきましたし、４定や１定に出された請願は、その反対の声そのものです。この点をお伺いいたします。","respondent":"多並都市開発課長","answer":"武蔵小山の小山三丁目第１地区、第２地区についてですけれども、今委員からご紹介いただきましたように、これまで都市計画の手続きに際しましては、まずは地域の方が準備組合の中で地域主体でまちづくりを検討していただき、区のほうにご提案いただき。","voiceIndex":147,"id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"反対の声、十分に考慮いただきたいと思います。それで負担し切れなくなってしまうと。区は、このような方が不安を感じることなく、安心して生活を再建できるよう、準備組合に対して指導助言しているというふうに説明するのですけれども、具体的にはどのような指導助言をしているのか伺いたいと思います。このような思いを尊重するために、具体的にどのような指導助言をしているのか伺いたいと思います。","respondent":"多並都市開発課長","answer":"は再開発事業の中で、地区の方々にご説明させていただいて、これまで進めてきたところです。今のご意見としましては、まずは不安ということで、管理費等のお話が今ございました。","voiceIndex":149,"id":"exchange-061"},{"speaker":"おくの委員","kind":"質問・要望","question":"もう一つの一般質問で、私はお店の例を出して言わせていただきましたけれども、そのとき区の説明としては、新しい建物に床の権利を受け取るか、補償金を受け取って出ていくかの２つ、そのような選択が自由にできるのだと。このように住民の権利が保護されていない以上、このような都市計画手続は一旦中止すべきではないかと私は思うのですけれども、この点いかがでしょうか。伺います。","respondent":"多並都市開発課長","answer":"この再開発事業というものは、この地区でやはり地域の方のご意見が多い、老朽化した建物であったり、または防災性の課題がある地域で、または商店街のにぎわいの創出について非常に解決しなければいけない問題ということで。","voiceIndex":151,"id":"exchange-062"},{"speaker":"おくの委員","kind":"質問","question":"しかし、住み続けるという選択肢はないわけです。これでもって権利が保護されているというのは、言えないのではないですか。この点伺います。中止すべきだと思いますけれども、いかがでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-063"},{"speaker":"田中委員","kind":"確認","question":"小山三丁目の再開発に関して関連質問を行います。先日の建設委員会の請願・陳情審査の会議録を確認しました。その中で区は、準備組合はまちづくりに賛同する方々が集まる組織と答弁されていますが、この認識は正しいでしょうか。伺います。","respondent":"多並都市開発課長","answer":"準備組合という任意の民間組織になりますけれども、この組織の考え方といたしましては、その地域の方が、このまちを、今後住むまちをどうしていこうかということを検討するために集まった方々の集まりですので。","voiceIndex":155,"id":"exchange-064"},{"speaker":"田中委員","kind":"質問","question":"次の質問をします。都市計画の事業計画が出てから、様々な資金計画が出るとの説明がありました。区としての補助金はどのくらいと見込んでいるのかということはちょっと伺いたいのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"そして資金計画の中に区の補助金など、要するに財源構成などもそこに入ってきますので、そのようなことが中に入っているということですので、今後そのような形で整理されて、区もしくは都のほうに提出されてくると、そのような説明をさせていただいたものです。","voiceIndex":157,"id":"exchange-065"},{"speaker":"田中委員","kind":"質問","question":"今は区としての補助金がどのくらい出るかも分からない状態の中で認可をしているということで間違いないですか。","respondent":"多並都市開発課長","answer":"認可につきましては、都市計画決定以後です。組合設立および事業計画の申請があって認可するものですので、まだ現時点では認可しているものではございません。今後、認可するものというふうにご理解いただければと思います。","voiceIndex":159,"id":"exchange-066"},{"speaker":"田中委員","kind":"確認","question":"補助金がどのくらいかという金額も見込んで、これから認可するのですよね。確認させてください。","respondent":"多並都市開発課長","answer":"事業計画の中に資金計画があって、その補助金がその中に入って、それを基に事業計画として認可しますので、今後それが含まれて示されると。入ってくるという理解をいただければと思います。","voiceIndex":161,"id":"exchange-067"},{"speaker":"田中委員","kind":"質問","question":"認可するときには補助金を大体どの程度出すかということは示されるという認識でいいでしょうかということと、先ほどの準備組合の考え方ですが、準備組合はそもそも本当に賛成している人、まちづくりに関して賛同しているのはそのとおりです。ただ、再開発するしないに関しては、そこに賛同している人たちが集まる団体ではありません。次の質問です。そのことについてどのようにお考えですか。","respondent":"鈴木都市計画課長、多並都市開発課長","answer":"正月も挟んだというところで、当日机上配付になってしまったと。ただ、当日の委員会の中では、その賛成・反対意見も含めて、細かく丁寧にご説明をして、会のほうを進行させていただいたです。補助金については、事業計画の中に補助金が入ってくるです。","voiceIndex":163,"id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問","question":"初めに、ドローンの活用についてお聞きいたします。平成３０年に導入されたドローンですけれども、どういった性能のドローンを所有しているのか、また、現在は何台所有しているのか、操縦できる方は何人いらっしゃるのか、また、搭載されているカメラには夜間でも見えるような暗視スコープや、あとはサーモグラフィー、そういった機能があるのかをお尋ねいたします。","respondent":"山本防災課長","answer":"こちらにつきましてはライセンス、職員のほうが今５名取得しておりまして、こちらのほう、月１回程度の訓練を実施しています。夜間のほう、赤外線カメラがありますので、夜間の撮影もできる仕様になってあります。","voiceIndex":167,"id":"exchange-069"},{"speaker":"湯澤委員","kind":"質問","question":"高性能のドローンの金額についてもお伺いいたします。カメラについてですけれども、災害から７２時間は、自治体が自力で切り抜けなければならない期間だと思いますので、人命救助のためにも、ぜひサーモグラフィー、そういったものがついたものがあれば、瓦礫の下にいらっしゃる生存者などの発見にもつながるのではないかなと思うのですけれども、こちらについてご意見を伺います。","respondent":"山本防災課長","answer":"地区ごとという要望でございましたが、今その１台で、各地区を順番に運用していくというところを想定はしていますが、今後、運用方法等も検討していきたいというふうに考えてあります。","voiceIndex":169,"id":"exchange-070"},{"speaker":"湯澤委員","kind":"質問・要望","question":"今のお話にもありましたが、区ではドローンを開発している３社と防災協定を結んでいるとお聞きしております。これらの企業とはどのような協定を結ばれているのか。平時において、防災課との合同練習を可能ならば行っていくべきではないかなと思いますが、いかがでしょうか。練習場所や時間についても、あらゆる状況を想定して様々に行っていくべきと考えますが、ご見解をお聞かせください。","respondent":"山本防災課長","answer":"それから様々な状況での訓練ですが、区のほうも先ほど申したとおり月１回の訓練をやっておりますけれども、この前夜間の訓練というものも初めて行ったところですので、今後様々な状況で実際に対応ができるよう、訓練のほうも充実させていきたいと思ってあります。","voiceIndex":171,"id":"exchange-071"},{"speaker":"湯澤委員","kind":"提案","question":"これは提案になるのですけれども、防災協定を結んでいる企業に協力していただけるのであれば、避難所訓練の際にドローンを飛ばしていただくなどすると、波及効果があるのかなというふうに考えます。今後の訓練メニューに入れていただくことなども検討していただけないかと思いますが、ご見解を伺います。","respondent":"山本防災課長","answer":"例えば区のほうもドローンを保有していますので、そういった機会に、区が保有しているドローンを区民の方に知っていただくいい機会だと考えていますし、また協定事業者も、そちらのほうの連携強化という意味も含めまして。","voiceIndex":173,"id":"exchange-072"},{"speaker":"湯澤委員","kind":"質問","question":"大変物珍しさもあると思いますので、ぜひそういった新しいメニューを取り入れていただきながら、家族や友人などと参加したくなるような避難訓練、そういった工夫をしていただければと思います。コロナ禍でも楽しく行える、そういった企画も増やしていくべきと考えますが、ご見解をお伺いします。","respondent":"山本防災課長","answer":"区の啓発活動も含めまして、訓練も含めまして、区民の方に楽しんでもらいながら防災を学んでもらうためには、そういった区民のアイデアを活用することも１つの方法かと思いますので、今後どういった機会が提供できるかというところは考えていきたいと思っているところです。","voiceIndex":175,"id":"exchange-073"},{"speaker":"湯澤委員","kind":"意見","question":"自転車走行環境整備工事についてです。この２６号線は都道ですけれども、利用しているのは区民でもあり、また、困っているのも区民でありますので、ドライバーが乗っている、そのようになっていると違法駐車には当たらないかもしれないですが、区民の思いを区でできることはないのかと考えていますけれども、区のご見解をお知らせください。","respondent":"川口交通安全担当課長","answer":"その活動は、本来であれば管内いろいろなところを回るところですけれども、１つの組についてはあそこを専従で回しているというところの回答をいただいているところです。","voiceIndex":177,"id":"exchange-074"},{"speaker":"湯澤委員","kind":"質問・要望","question":"対策をある程度打っていただいているということではあるのですけれども、やはりなかなか結果が出ていないと私は思っております。そこに対して注意を促せば、少しは解決していくかもしれません。そういったことに対して、警察に対しても、区民のためにぜひとも強く要望していただきたいと思うのですけれども、その辺に関してもう一度ご答弁いただけますでしょうか。","respondent":"川口交通安全担当課長","answer":"警察からも話はいただいているところですけれども、例えばその駐車車両に迷惑性とか、あと移動の緊急性があれば、当然遠慮なく１１０番していただきたいというふうにもお話しいただいていますので。","voiceIndex":179,"id":"exchange-075"},{"speaker":"湯澤委員","kind":"質問・要望","question":"時間がありますので、駅周辺等放置自転車対策事業についてお伺いします。この件は、武蔵小山駅に限定して、ちょっとお伺いしたいと思うのですけれども、自転車対策の成果についてお伺いいたします。","respondent":"川口交通安全担当課長","answer":"これと併せまして、駅前には一時的な利用ができる大きな自転車のスペースもありますが、そちらのほうにつきましても、以前は本当に１０％台の利用率だったのですけれども、今４０％台にまで上がっておりますので、また引き続き。","voiceIndex":181,"id":"exchange-076"},{"speaker":"湯澤委員","kind":"質問・要望","question":"やはりそういったところというのは、どうしてもこれをなくしていくには、もう利用者のマナー、それしかないのかなと考えています。このマナー向上に向けて、やはり何らかの策を練っていかなければいけないと思いますし、それがもう駄目な場合には、さらに撤去を強化していく、そういったことをしていかなければいけないのかもしれないので、そういったところもしっかりと注視していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問・要望","question":"本日３月１１日で東日本大震災から１１年が過ぎます。これ自転車のほうの、主に取締りだと思うのですが、自転車だけではなくて、歩行者のマナーであったり、特に高齢者の方々、結局それに巻き込まれるということが多くて、そちらのほうの指導もぜひしていただきたいなと考えていますが、いかがでしょうか。これはやはり多くの方にＰＲするべきではないかなと考えていますので、そのお考えをお聞きします。","respondent":"川口交通安全担当課長、鈴木都市計画課長、平原防災体制整備担当課長、五十嵐災害対策担当課長","answer":"委員もご存じのように、非常に管内の自転車事故が多いということで、今回事業を開始するわけですけれども、実際の事業の開始に当たりましては。全体的には、この自転車を区としてどう区民の方に使っていただくかということをしっかり検討して、打ち出していきたいです。同じく近隣自治体の輸送というところ、こちらのほうも東京都が主に担うものですので。区内一斉防災訓練についてですけれども、今回の訓練を通して、さらにアンケートを通して分かったことですが、区内一斉防災訓練とは。","voiceIndex":185,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"今ご答弁いただいた、区民の皆さんへのＰＲをぜひしっかりやっていただきたいと思います。このようなことをやっているよということを広く広く、そして興味を持っていただいて、自ら身を守るということ、そして近隣との自助、共助ということがあると思いますので、進めていただくようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-079"},{"speaker":"こんの委員","kind":"質問","question":"私からは３０９ページ、駅周辺等放置自転車対策事業、３４３ページ、公営住宅等長寿命化計画策定経費、３４５ページ、居住支援協議会支援委託、この３点を順不同でお聞きしたいと思います。初めに、居住支援協議会支援委託をお聞きしたいと思います。居住支援協議会において、住宅支援要配慮者に対する具体的な施策展開のための協議などは、今後どのように行われていくのでしょうか。","respondent":"竹田住宅課長","answer":"今後の見通しですが、住宅確保要配慮者が入居可能な専用住宅を区内に増やすことによって、国や都の補助金を受けられるように制度のほうをＰＲ、および進めていきたいと考えております。","voiceIndex":192,"id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"経費の内容、分かりました。今後、住宅確保要配慮者への必要な施策となる、この家賃低廉化補助の活用について、居住支援協議会においてご検討いただいて、区としては、協議会での検討を踏まえて、実施要綱などの策定などを進めるなど、実効性ある家賃低廉化助成を進めていただきたいと再度要望いたしますが、区のご見解をお聞かせください。","respondent":"竹田住宅課長","answer":"こちらを使いながら、居住支援協議会のほうでもご議論いただきまして、品川区でどのように実施していくことが一番理想的で効果的なのかということをご議論いただいて、実際の事業にしていきたいと考えております。","voiceIndex":194,"id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ、そのように調査をしていただきながら進めていただきたい、このように思います。その軽減策も併せて考えていく必要があると考えますけれども、その点について、区のお考えはどのようにお考えでしょうか。","respondent":"竹田住宅課長","answer":"東京都は指定居住支援法人として、そういったソフト面を支援する会社を３５社ほど指定していますので、こういった支援法人の活用も考えながら、オーナー様のご心配をできるだけ少なくするような制度設計を考えていきたいと考えています。","voiceIndex":196,"id":"exchange-082"},{"speaker":"こんの委員","kind":"質問","question":"次の質問に参ります。既存の区営住宅の中で、昭和４５年以前に建設された住宅は何棟あって、どこの住宅なのか、お聞かせください。これまで長寿命化計画にのっとり、建物の維持管理をして、大事に使ってきたことと思いますけれども、さすがに半世紀以上たつ住宅となりますと、計画的なメンテナンスだけではもたないのではないかと考えますが、その点、区のお考えをお聞かせください。","respondent":"竹田住宅課長","answer":"委員ご指摘のとおり、長寿命化計画を立てまして、それに基づきまして、予防保全的な維持管理や、耐久性の向上に資する改善等を計画的に実施しております。何よりも大事なのは、居住者の方に安全・安心にお住まいいただくことが一番大切なことと考えております。","voiceIndex":198,"id":"exchange-083"},{"speaker":"こんの委員","kind":"質問・要望","question":"５０年たった、半世紀以上たつ建物について、今のお考えだということです。そうしたことについて、二葉一丁目のこの住宅は、建物の老朽化とともに、バリアフリー対策も必須の課題であると考えています。これまで私も、決算特別委員会、予算特別委員会等でエレベーターの設置を要望してきましたけれども、日影の問題などでなかなか話が進まないのが現状です。","respondent":"竹田住宅課長","answer":"来年度で公営住宅の長寿命化計画を策定してから１０年がたちまして、見直しの年となっております。区営住宅全体を考えながら、各個別の住宅についても適切な時期に建て替えをすべく、検討していきたいと考えております。","voiceIndex":200,"id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"来年の計画策定、しっかり調査をしていただきながら、進めていただきたいと思います。次の質問に参ります。そこで、現在この利用状況について、増設する前の既存駐輪施設の利用割合は８５.１％となっていましたけれども、２０１７年度増設後の利用割合はどのような状況でしょうか。この駐輪施設、３階建てになっておりますけれども、築年数と当日利用、定期利用の利用割合も併せてお聞かせください。","respondent":"川口交通安全担当課長","answer":"さらに西大井の建屋の部分の駐車場だと思いますけれども、こちらにつきましては、昭和６１年６月に当時の自転車駐車場整備センターが設置いたしまして、これは築３５年という形になっております。","voiceIndex":202,"id":"exchange-085"},{"speaker":"こんの委員","kind":"質問・要望","question":"当日と定期利用も、もし分かりましたら、併せて後でお聞かせください。分かりました。建屋のほうの駐輪場についてですけれども、こちら３階建ての建屋の駐輪場です。今後、この西大井駅は、ニコンの跡地が自社開発をされるなど、駅周辺の環境が大きく変化するという予測から、駅周辺の放置自転車対策の強化が、今後さらに求められると考えております。","respondent":"川口交通安全担当課長","answer":"将来的な整備検討につきましては、今後の周辺地域のまちづくりも絡めた状況で考えていきたいというふうに考えています。","voiceIndex":204,"id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"３２３ページ、航空機騒音測定委託に関わって羽田新ルート、３２６ページ、都市開発費、超高層再開発について伺います。巨額な税金を入れるのですから、最低限の説明責任だけは少なくとも果たすべきだと思っていますが、先日の建設委員会でも、先ほどもありましたけれども、小山三丁目第１・第２地区再開発の補助金額について聞きますと、建設委員会では、現時点でお答えするものはないとのことでした。","respondent":"多並都市開発課長","answer":"ということですので、先ほど、最初のほうのご説明をしますと、この資金計画として補助金が幾らになるかということはこれから示されるけれども、その見込みのというものは、準備組合の中で検討している内容ですというご説明になります。","voiceIndex":207,"id":"exchange-087"},{"speaker":"安藤委員","kind":"質問","question":"理解できません。見込額で、試算でいいのです。その額でいいので教えてください。都市計画審議会では言って議会で言わないというのは、完全な議会軽視です。しかも、都市計画決定されているわけですから、先ほど紹介したのは都市計画審議会、都市計画決定の前の段階で、見込みで教えているのに、今日教えないというのは、これはちょっと大問題だと思いますけれども。","respondent":"多並都市開発課長","answer":"今の見込みというお話ですけれども、要するに準備組合と民間組織の中で検討されている資金計画の試算というところだと思います。これについては、区からお答えしなかったということです。","voiceIndex":209,"id":"exchange-088"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは本当に、私は検討している資金計画の見込みで構いませんので教えてくださいと言っていますので、教えてください。これはもう後戻りできないのです。もう一度見込額を、都市計画審議会で言っているわけですから。ご答弁お願いします。２点伺いたいと思います。いかがでしょうか。ちょっと伺いたいのですけれども、区として減便中の一時中止すら国に求めないということでよろしいのでしょうか。伺います。","respondent":"多並都市開発課長、鈴木都市計画課長","answer":"したがって、その検討している段階では変動するものですので、そのようなものが、これから事業計画として固まっていくということですので、そのような変動する内容でのお答えではなくて。羽田新ルートの件ですが、まず１点目の、コロナ禍における一時中止について、これは区のほうでも区民の声を伝える形で、そのやり取りの中で国のほうから確認しているところでは、やはり復便に、いつか必ず航空需要というものは。","voiceIndex":211,"id":"exchange-089"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点伺います。区は常々、固定化回避検討会で早急に具体的な方策が示されるよう求めると言っておりますが、これニュースレターを見るに、区の言う早急とは、早くとも５年、１０年のスケジュール感だと理解してよろしいでしょうか、伺います。もう一つは、区は、国の固定化回避の方策が導入されるまで、区民には騒音被害や落下物墜落事故への不安は我慢していただくという考えなのでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"現在国のほうで検討いただいております固定化回避につきましては、これはもう本当に、明日にでも実行できるものがあれば、もう当初から行っていただいているべきものです。","voiceIndex":214,"id":"exchange-090"},{"speaker":"安藤委員","kind":"質問・要望","question":"検討はこれだけ時間がかかるわけですから、実際その前に、導入前にもう、落下物事故は起こりかねないと思います。私は、区は固定化回避検討にしがみつくのではなくて、即刻中止を国に求めるべきだと思います。それであるならば、もうシミュレーターを使っているのですから、ならば、区として今すぐこのルートについて明らかにするよう国に求めていただきたい、少なくとも。いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"具体的なルートを決めての検証はまだ行われてないという回答でございました。引き続き、早急な検討結果を求めてまいりたいです。","voiceIndex":216,"id":"exchange-091"},{"speaker":"渡部委員","kind":"質問・要望","question":"１１年前も予算特別委員会をやっていまして、民生費だったと思います。質問に入ります。３４５ページ、先ほど西本委員のところでもありましたけれども、東京都・品川区合同総合防災訓練について、３１５ページの都市計画道路に入るのでしょうか、２６号線、一般質問でもさせていただきました、戸越三丁目界隈渋滞等について、昨日中途半端になってしまいました。大学病院のほう。そこに町会の人が入ったり。","respondent":"五十嵐災害対策担当課長","answer":"しながわ中央公園ですけれども、医療救護訓練を実施したいと考えておりまして、ちょっとヘリコプターをあそこで使えないかなというところなのですが、ではどこでヘリコプターを使うのかということは、今東京都と検討しています。","voiceIndex":220,"id":"exchange-092"},{"speaker":"渡部委員","kind":"質問","question":"失礼しました。ジージョくんですね。本当に、せっかくそれだけ大きなものがあるわけですから、何かそこで様々なことをして、人に出てきてもらう。どうぞよろしくお願いいたします。よろしくお願いします。だけれども、なぜこのようなときにこれほど混んでいるのだろうというときは混んでいる、どのような対策を取られてきたのかということを、もし分かれば教えてください。","respondent":"稲田土木管理課長","answer":"今後、また調査は実施したいということを言っておりますので、その辺で、委員ご提案の車線の形などもございましたけれども、その辺も情報を共有しておりまして、その辺をまたこれからやる滞留長の調査と併せながら、警察、都、区、いろいろと考えていきたいなと考えています。","voiceIndex":222,"id":"exchange-093"},{"speaker":"渡部委員","kind":"質問・要望","question":"１つだけ、結局あそこの交差点のことを云々言って、渋滞にはまってしまうのでというような一般質問の内容だったのですけれども、会派のほうにもいろいろなお声はいただいていて、その中で、あそこの交差点というのは、やはりちょっと事情があって歩車分離になった交差点で、それはやはりあの地域の方々にとって、区にとっても当然そうですが、それを壊してまでという話では全くなくて、優先事項はそこなので。","respondent":"高梨公園課長","answer":"今、委員からもご案内がありましたとおり、やはり見てわくわくする、まずは、どんなに立派な計画も、見てもらわなければしようがないと思っていますので、しっかり子どもも含めて、見て魅力のある、概要版を含めた冊子作り、計画づくりということに努めてまいります。","voiceIndex":224,"id":"exchange-094"},{"speaker":"渡部委員","kind":"意見","question":"本当にペラ１枚でも、もう実際にいいです。ただ、冊子になればなるほど、持ち歩いてほしいと思うのです。ちょっとポケットに入るような大きさのものを作ってもらって、そこには裏返せばスケールが入っている。できることなら、しおり型のルーペの一枚でもつけてあげて、何かあったらこうやって観察できるのだよというようなところまでやっていただけたら、品川区すごいなと思います。よろしく願います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":226,"id":"exchange-095"},{"speaker":"松澤委員","kind":"質問・要望","question":"私からは、３４５ページ、防災関係組織経費、そして３４９ページの応急活動対策費、これ全般について質問します。そういったお声が行政のほうにも届いているのか、教えてください。避難所開設訓練の際にアンケートが配られましたが、地区防災などの訓練中止の際に、この自主防災組織、これに向けたアンケート、要は組織の課題、そういった要望、そういったものの配布があったのか教えてください。","respondent":"五十嵐災害対策担当課長","answer":"訓練アンケートについてなどのお尋ねですが、予定していた訓練を中止された自主防災組織には、アンケートは行っておりません。しかし、地区防災協議会会長連絡会を通して、各地区から防災訓練に関するご意見はいただいております。","voiceIndex":228,"id":"exchange-096"},{"speaker":"松澤委員","kind":"質問","question":"しっかりした訓練をしてほしい、これは多分区民の声、本当の声だと考えています。だからこそ、このソフト面の強化、これを考えていかなくては、課題の解消につながらないのではないでしょうか。そこで大事なのは啓発の部分になりますが、自主防災について区が取り組んでいる部分で、昨年しながわ防災学校、これにつなぐとご答弁がありましたけれども、ほかにも行っているものがあるのか教えてください。","respondent":"山本防災課長","answer":"自主防災に対する区の取組みについてです。区では区民消火隊など、１０年以上活動された方への感謝状の贈呈を防災フェアの中で実施したり、また、東京防災隣組に認定された町会の取組内容をしながわ防災体験館に掲示をしています。","voiceIndex":230,"id":"exchange-097"},{"speaker":"松澤委員","kind":"質問","question":"これはどんなに参加してくださいと言いましても、要は自主防災の中身というのですか、自分たちでやるという意識が伝わらないと、自主防災自体の組織というものは成り立たないと思っているのです。私が消防団、２３年前です。タイトルがすごいなと。やはりいつも決まった素材で勉強するのではなくて、みんなでつくり出す防災動画というのですか、要はケーブルテレビ品川を巻き込んでもいいと思っています。","respondent":"山本防災課長","answer":"引き続き新しい技術などを活用しながら、オンライン、それからオフライン、それぞれ組み合わせながら、より効果的な啓発方法というものを進めていきたいというふうに考えてあります。","voiceIndex":232,"id":"exchange-098"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひＹｏｕＴｕｂｅの活用、委託するのではなく、ちょっと負担になってしまうかもしれないですけれども、課長がこのように実際に出ると、あれ、何かちょっとクールだけれども実は面白いなとか、何かそのようになって面白さが本当に増すと思っていますので、やってほしいというわけではなくて、ぜひ活用していただきたいと思います。このおうち防災運動会というものが、明日開催されます。","respondent":"五十嵐災害対策担当課長","answer":"令和４年度は、先ほど来お話しさせていただきました、４５年ぶりに実施する東京都・品川区合同総合防災訓練に、各地区総合防災訓練の参考となるような新しい訓練コンテンツを取り入れる予定です。ですので、区内全地区に対して、その点の周知を図ってまいりたいと思います。","voiceIndex":234,"id":"exchange-099"},{"speaker":"松澤委員","kind":"確認","question":"避難所のＷｉ－Ｆｉについてちょっとお聞きいたします。災害時に学校の体育館、これが避難所になりますが、たしか体育館、避難所のＷｉ－Ｆｉ環境、これは区ではなくて、多分都か国だと思うのですが、そういったところを整備すると認識しておりますが、ここを確認させてください。この避難所への、要はＷｉ－Ｆｉの整備、これは進んでいるのか、避難所に導入する計画なども教えてください。","respondent":"平原防災体制整備担当課長","answer":"区では、事業者から広帯域移動無線アクセスシステム、これは、いわゆる地域ＢＷＡと言われるものですが、こちらのサービスの実施について提案を受けまして、災害時における活用という観点からも整備を進めてまいりました。","voiceIndex":236,"id":"exchange-100"},{"speaker":"松澤委員","kind":"質問","question":"避難所全部に整った、これは大変うれしいことであります。要は訓練だとすると、１年に１回です。ただ、それをやってしまうと、防災とは全く関係しないので、例えばそのようなものを使うのであれば、要は防災学習を取り入れるとか、何か防災に関することを１つ入れるとか、そういったことをやりつつ、そのＷｉ－Ｆｉの機能を確かめる、こういった取組みはどうでしょうか。ご見解をお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"一方で、先ほど説明させていただきました地域ＢＷＡによるＷｉ－Ｆｉにつきましては、用途の制限があるということもございまして、防災に役立つものであれば、例えば平素から活用できるのか、こういった点につきまして、事業者のほうにも確認を進めてまいりたいと思います。","voiceIndex":238,"id":"exchange-101"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひその活用の確認をしていただいて、どうすればそういったうまい利用というのですか、活用ができるか、ぜひ前向きに検討していただきたいと思っています。訓練の形骸化を変えていくためにも、デジタル防災をはじめとしたいろいろな検討を進めていただきたいと思っています。火災に関連しまして、一般質問でお話ししました同時多発火災、そういった危険性も伴うと思います。","respondent":"平原防災体制整備担当課長","answer":"品川区における水利、貯水槽ですけれども、４０トン以上のものでいきますと、現在区内に１３３か所、こちら区の管理のものですが、整備させていただいておりまして、消防庁からお話を聞くところによりますと、水利は充実しているというようなご回答をいただいているところです。","voiceIndex":240,"id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"都市計画課は、これまでの様々、先ほどありましたアンケートの成果や、そういった成果はどのように関係して、それでどのような役割を果たす、関わっていく状況なのでしょうか。","respondent":"鈴木都市計画課長","answer":"ある意味、新たに来年度組織立てるところというのは、地域コミュニティの継続した検討ですとか、ある意味将来にわたっての八潮の在り方等々についても幅広く検討されるですので、それは全く分離するものではなくて、連携をして、今後も取組みを進めていきたいです。","voiceIndex":243,"id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"自転車のほうです。この時期から考えると、隔世の感があります。そして先ほども少しありましたが、この計画策定の後、自転車関連の区の事業はどの方向に向かっていくのでしょうか。そしてさらに、この自転車に関することがかなり広がってきましたので、様々、ハード、ソフトの両面から進める、自転車担当の、何というのですか、幅広くつかむ担当の設置を求めますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"計画期間のほうは、基本的には２か年をかけて、学識経験者を入れた検討委員会を設置して、２か年をかけて策定を進めていきたいです。","voiceIndex":245,"id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この計画がきちんと制定されて、自転車事業政策がさらに進んでいくことを要望したいと思います。３つの柱があるというふうにありましたが、回遊性というものもキーワードになっていると思います。この東京都の整備計画や方針との関連性というか、長い話になると思います、先の話ですが、どのようにつないでいくのか、その辺を想定しながら、都市再生整備計画は策定へ進められているのでしょうか。","respondent":"鈴木都市計画課長","answer":"ひいては歩行空間のネットワーク、安心して歩ける、安心して暮らせるまちづくりにつながっているというところでは、当地区のビジョンにも関係してくるところですが、整備計画のほうは、令和６年から５か年をかけて人道橋、新浜川公園。","voiceIndex":249,"id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"意見","question":"この都市再生整備計画、その中の人道橋の新設等は、本当に地域の方々の非常に大きな期待があります。ぜひ、きちんとした形で進めて、計画の実現、できるだけ早く実現していただけるようにお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":251,"id":"exchange-106"},{"speaker":"若林委員","kind":"質問・要望","question":"３４９ページの医療救護体制整備費について、まずお尋ねいたします。特に大地震発災直後の、この医療体制の整備というところで、特に早急に救護所、また、避難所に向かわなければいけないという観点で、特に医師会等、また薬剤師会、その２つの動きについて確認をさせていただきたいと思います。","respondent":"山本防災課長","answer":"課題といたしましては、もちろん情報通信機器が正常に使えるかどうかというところで、その辺りの対応というものは今後考えていかなければならないと思っているところです。","voiceIndex":254,"id":"exchange-107"},{"speaker":"若林委員","kind":"確認","question":"今の情報通信機器が動くかどうかというところで、医師会と薬剤師会の会の中では、その情報通信機器というものがどのようになっているのか確認させてください。","respondent":"山本防災課長","answer":"医師会、薬剤師会の内部の情報通信機器というところは、これ専用のものを準備しているということは区では把握してございませんので、一般の電話等で対応するものというふうに理解をしているところです。","voiceIndex":256,"id":"exchange-108"},{"speaker":"若林委員","kind":"質問・要望","question":"その確認はされていないというところで、やはり医師会、薬剤師等からご相談、課題のお話がございまして、これは長年品川区のほうにも、ご要望や要請をされているという中で、やはり薬事のコーディネーターが区役所に参集して、そこから、例えば医師の会員や、また薬剤師の会員に、あなたは救護所、あなたは避難所、あなたはとどまる、また、全国から救援物資、薬剤、また医療資機材の物資があったときには。","respondent":"山本防災課長","answer":"区では、災害対策本部でも、それぞれ専用の、例えばデジタル移動通信等を関係機関にお配り等しているところで、医師会と、あとは主要の災害拠点病院等にお渡しはしていますが、各診療所等にはちょっとお渡しはしていないところで。","voiceIndex":258,"id":"exchange-109"},{"speaker":"若林委員","kind":"質問・要望","question":"通常は、区役所でいうと、いわゆる保健所とか、健康推進部とか、そのようなところが直接の窓口になっていると思いますので、しっかりその辺は、また横の連携を取っていただいて、各団体のお声をしっかりと聴いて、来年度中にはしっかりとこのシステムを、様々な意味での区の支援をいただきながら構築していただきたいなと、このような強い要望をしますので、どうぞよろしくお願いいたします。","respondent":"山本防災課長、長尾建築課長","answer":"平時においても、防災課、それから健康課、保健所等と災害利用の協議等は今進めているところです。今後内部の連携だけではなくて、外部の機関との連携強化というところもしっかり進めてまいります。相談件数としましても、現時点で１００件超えのご相談をいただいておりまして、その中には助成に関わるご相談も１０件以上いただいておりますので、来年度もしっかりと対応していきたいと考えております。","voiceIndex":260,"id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"災害時の医療救護体制の整備、これはしっかり万全に、前に進めていただくように重ねてお願いを申し上げ、また、人命を守るためのがけ・擁壁、またコンクリートブロック塀の安全化についても、力強く進めていただければと要望します。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、３２０ページの都市計画費に関わって、リニア新幹線について伺いたいと思います。リニア新幹線は、昨年１０月から、ＪＲ東海の調査掘進という名の初期掘進が始まり、約５か月がたっています。区として、東京地裁による調布市の外環道シールドトンネル掘削工事差止めの決定をどう捉えているか、伺います。この工事差止め決定が、リニア新幹線工事にどう影響するのかについても伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"区としましては、外環道、陥没事故が起こってあります。そうしたこと、様々今検証されてありますが、そうしたことを踏まえまして、ＪＲ東海に引き続き安全に工事していただき、また、住民の不安払拭に向けて努力していただきたいというふうに考えてあります。","voiceIndex":265,"id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"結局陥没や空洞が起こったところ、その場所の９kmにわたっての工事差止めです。リニア新幹線の工事も、気泡を添加剤にする点で同様の工法ではないかと思うのですが、伺います。調査掘進の説明会の資料でも、削った土砂の粒の隙間を添加剤、気泡で埋めるということで書かれておりますけれども、その点では同じ工法となるのではないか、お聞かせください。","respondent":"中道まちづくり立体化担当課長","answer":"そこにつきましては、有識者委員会に各５本、おのおの具体的な再発防止対策というものが報告されてあります。それを検討いたしまして、また、地域の方に説明会を開いて、安全性の周知をしているというところで、今回の決定では中止にならなかったというふうに認識しております。","voiceIndex":267,"id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はぜひ調布市にも、区として実態を見に行っていただいて、話も聞いていただいて、つかんでいただきたいなと思うのですけれども、その点についても伺いたいと思います。それから、調布市の陥没事故、巨大空洞の事故、そして今回の工事差止めについては、リニア新幹線、品川区としては関係ないこととするのではなく、ここをしっかりと教訓として学ぶことが必要ではないかと思いますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"そうした安全対策というものも、今現地で実地試験をしています。ですので、区としましては、こうした外環道の安全対策、再発防止対策ということを踏まえまして、ＪＲ東海に対して、安全に工事を計画・施工するよう、努めてまいりたいと考えています。","voiceIndex":269,"id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区として、土木の専門家として、私はこの気泡添加剤についても、ボーリング、地盤についても、安全性についてしっかりと、土木の専門家として検証していただきたいと思うのですけれども、その検証はされているのか、検証していただきたいと思いますが、いかがでしょうか。ＪＲ東海が安全と言っているので信じますということでは、区民の安全は守れないと思いますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"４.６kmで直径１４ｍのシールドマシンが通るというところで、その真上のボーリング調査が１か所もないですが、通常シールド工事をやる際には、事前に土質の状況を調べるというところで、ボーリング調査というものを実施します。","voiceIndex":271,"id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで建設委員会での請願審査時、課長がオープンハウス型で地域ごとにやるような説明をしていますけれども、ＪＲからはどのように言われているのか伺いたいと思います。これは区も参加されているのか、どのようにされたのか、それから、町会長たちも地域ごとに、みんながやってくれと求めたということでしたけれども、それにもどう応えていくのか伺います。","respondent":"中道まちづくり立体化担当課長","answer":"調査が終わった後の説明会ですけれども、時期につきましては、まだＪＲ東海からの報告はございません。","voiceIndex":273,"id":"exchange-116","title":"町会・自治会支援"},{"speaker":"大倉委員","kind":"提案","question":"３１１ページ、しなみちレポート、３４５ページ、防災訓練、３０９ページの自転車安全利用指導員業務委託について伺います。自転車安全利用指導員業務委託ですが、簡単に内容を教えてください。ジージョくんの活用とか、キャラクターを利用して参加者に興味を持ってもらうとか、様々、やはり多くの方に参加してもらう訓練というところで、課題を解消していこうというご提案なのかなと思います。","respondent":"川口交通安全担当課長、五十嵐災害対策担当課長、溝口道路課長","answer":"そこで区では、この交通事故が多発している、特に自転車の交通事故が多発しているような交差点におきまして、指導員を配置して。それと、集客についてですけれども、会場が荏原地区など、なかなか行きにくいところにありますので、バスルートを、臨時バスを３本ほど。委員ご指摘のように、様々な形でまずは知ってもらう、使ってもらう、登録してもらう、そういったことが大事だと考えていますので。","voiceIndex":276,"id":"exchange-117"},{"speaker":"大倉委員","kind":"質問・要望","question":"しなみちレポート、ぜひ調整していただいて、多分経年で、お話を伺うと経年で劣化していく中で揺れてくるということもあるかなと思いますが、工事終了後すぐに揺れるということであれば即座に対応もできるのかなと思いますので、ぜひ調整をお願いしたいと思います。これは要望して終わりたいと思います。","respondent":"川口交通安全担当課長","answer":"そのほかにも、例えばブレーキもなかなか利きが悪くなるなど、そのような問題もありますので、そういうところ全てを含めて、安全な利用の指導を行っていきたいというふうに考えているところです。","voiceIndex":280,"id":"exchange-118"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、３４５ページの感震ブレーカー普及経費、３４１ページ、空き家等対策事業、３１７ページ、水辺利活用事業、時間があれば３４９ページの防災体制整備費、伺っていきます。感震ブレーカーから、まずお伺いしていきたいと思います。今把握されている範囲ですか、どれぐらいの割合が実際に感震ブレーカーを設置されているとお考えなのか、まずお聞かせください。","respondent":"山本防災課長","answer":"対象エリアが木造住宅、大体１万３,０００以上あるというところで、それから割り返すと大体３.５％の普及率というところではありますが、こちら区の助成制度を活用してもらった件数しか、ちょっと区のほうは把握してございませんで、一体その現状というところ。","voiceIndex":284,"id":"exchange-119"},{"speaker":"芹澤委員","kind":"質問・要望","question":"先ほど課長からも、延焼を防ぐというようなお話がありましたが、ただホームページを見ると、この不燃化特区の一部を除くというようにエリアが書いてあって、徐々にこれは、今年度からですか、またちょっとエリアが拡充されたかのように思うのですけれども、いまだに一部除かれているエリアがあるということ、まずそこの考え方をお聞かせいただきたいということと、あと先ほどお伝えしたとおり。","respondent":"山本防災課長","answer":"こちらにつきましては、延焼遮断帯の形成を一番の目的としているというところで、除外していますが、当然その地域におきましても、ソフト面での延焼防止というところの必要性はありますので、今後その対応等は考えていきたいと思っているところです。","voiceIndex":286,"id":"exchange-120"},{"speaker":"芹澤委員","kind":"質問・要望","question":"これは事前に伺ったところによると、このポスティングの時期が、７月とたしか１１月だったかと思うのですが、そこで合っているのかお聞かせいただきたいということと、もしその７月、１１月であれば、やはりこの感震ブレーカーというものは、先ほどお話ししたように、暖房器具が倒れたときに火につながっていく、火災につながっていくというもので、なかなか一般人の心理からすると。","respondent":"山本防災課長","answer":"リーフレットの配付時期ですが、今年度につきましては７月、それから１１月の２回実施したところです。７月が申請の開始時期というところで、７月としています。","voiceIndex":288,"id":"exchange-121"},{"speaker":"芹澤委員","kind":"質問・要望","question":"空き家対策についてお伺いいたします。ここの空き家、このように活用したらどうですかというようなマッチングを始められるというふうに伺っていますが、そのマッチング業者というものがどういった会社になるのか、コンサル会社なのか、不動産会社なのか、お聞かせいただきたいということと、あと契約形態、実際に解決したらお金が支払われるのか、年度でもらうのかをまずお聞かせください。","respondent":"竹田住宅課長","answer":"空き家の有効活用提案の事業のお問合せだと思います。業者の契約形態ですが、単価契約を考えておりまして、１件提案していただいたら幾らというような形で契約していこうと考えております。","voiceIndex":290,"id":"exchange-122"},{"speaker":"芹澤委員","kind":"提案","question":"歩合制というのですか、そのような契約にしていくということで、少し気になったのが、聞き間違いだったらあれですが、提案ごとにお支払いというようなお話になるというご答弁があったように思うのですけれども、解決するというようなお金ではなくて、提案ごとにとなると、ある意味同じものの使い回しというような危惧もあるのですが、そこに対してどういったお考えがあるのかお聞かせください。","respondent":"竹田住宅課長","answer":"空き家の有効活用提案の事業のほうです。こちらは改善した場合の実績で報酬ということになりますと、なかなか難しいと思いますので、まずは１つの空き家に対して１つの提案をしていただいたという段階でお支払いをしたいと考えております。それから、封筒です。","voiceIndex":292,"id":"exchange-123"},{"speaker":"芹澤委員","kind":"質問・要望","question":"契約に関してもありがとうございました。繰り返しになりますが、同じ空き家改善案を使い回しで出されてしまうのだけは、ぜひ止めていただいて、同じようなというか、大体空き家というものは同じレベルの大きさだったりするものが多いですから、それがやはり使い回しになって、どんどんお金をお支払いするということだけはないようにご注意いただければと思います。お答えをお願いします。","respondent":"竹田住宅課長","answer":"それから報酬ですね。報酬のほうも、それから建て替えについてのご提案ですけれども、こちらについては検討していきたいと考えております。","voiceIndex":294,"id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"私は３３７ページ、住宅・建築物耐震化支援事業についてお聞きします。後でお聞きしたいのですが、１９８１年以前に着工した旧耐震基準ビル、これ、どれぐらいこの品川区にあるか後でお聞きしますので、よろしくお願いします。早朝ということもあって、死亡原因の８割は、建物の倒壊や崩壊等による圧死でした。４１年前に建てられたビルですが、品川区には、今何棟ありますか、教えてください。","respondent":"長尾建築課長","answer":"耐震化支援事業に関わるお問合せです。","voiceIndex":297,"id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"それこそ死傷者がたくさん出てしまう、そのようなことに関して、どのようにお考えでしょうか。私はもう大変心配だと思うのですが、なぜそちらのほうに関しては、耐震診断も含めて対応しないのか、これは２７年前にこのような事故があったら、少しでも進めておかなければいけなかったのではないですか。それを、いや危険かどうか分からないで、みんな日常生活を送っているのです。教えてください。","respondent":"長尾建築課長","answer":"は優先的に耐震化を図るべく、建物というところのカテゴリーをきちんと決めて、これまで支援してきておりますので、まずはそこの部分の耐震化支援というところに注力してきたのが、これまでの取組みとなっております。","voiceIndex":299,"id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"やっています。でも、民間の建物のほうが圧倒的に、ビルは多いではないですか。商業ビルが。いつか何か起きたら、このような大地震が起きたら、ああ、ぺしゃんこになりましたでは済まないではないですか。少なくとも耐震診断だけはして、ここはちょっと危険な建物がありますよとか、そのぐらい、私は区で責任を持って調査すべきではありませんかと思うのですが、いかがですか。","respondent":"長尾建築課長","answer":"区としましては、そういった財源の確保も、国や都のほうに求めながら、今後の課題としては検討していきたいと考えておりますが、まずは優先度の高いものの耐震化というところが、まだ道半ばですので、そこの部分に注力しつつ。","voiceIndex":301,"id":"exchange-127"},{"speaker":"須貝委員","kind":"確認","question":"予算がつかないから、別に危ないものでもそのまま放置しておきます、地元の自治体がそのようなことではまずいのではないですか。そして専門家もおっしゃっています。診断の方法だって、４１年前に建てられたビル、それは区で確認できるはずです。そのようなものを私は学者に聞いて、実際にどうなのですかと。それほどお金をかけなくてもできるのですか。何年に建ったとか。もう一度お聞かせください。","respondent":"長尾建築課長","answer":"旧耐震基準で建てられた建物であっても、当時求められていた基準以上の水準で建てている建物も当然ありますので、そういったところの確認となると、なかなかその外観だけ見てとか、区で保有している情報だけでもって、安全であるとか、危ないとか。","voiceIndex":303,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問・要望","question":"少なくとも、そこで生活している区民、国民の方には、ちょっとこの辺に危険なものがありますよというぐらいは、その町会、自治会もそうですが、その住民の方にある程度教えてあげるべきではないですか。２７年間、多くの自治体が、このようにオフィスビルや商業ビルに関して、全く手をつけて、ほとんど手をつけていない状態というのは、私はいくら何でもちょっとひどいのではないですかと。もう１点。","respondent":"山本防災課長","answer":"区といたしましては、地域というところが共助の要というふうに考えてありますので、それぞれ特色のある災害対策というものを行っているところですので、区といたしましては、引き続き各町会等の支援等をさせていただきたいというふうに考えてあります。","voiceIndex":305,"id":"exchange-129"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３４３ページの区営住宅管理費に関連して、連帯保証人について、３２９ページ、戸越公園駅周辺まちづくり事業に関わって、補助２９号線道路について伺います。区営住宅の連帯保証人についてです。現在、区営住宅に入居する際は、連帯保証人を求められています。区としても、この区営住宅の入居者に求めている連帯保証人を廃止することを求めますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"区営住宅の入居希望者に、身寄りのない単身高齢者等の増加を踏まえ、区営住宅への入居に際して、保証人の確保が困難になるケースが想定されますことから、平成１８年度から、区営住宅の入居の審査の際には、個人の連帯保証人。","voiceIndex":308,"id":"exchange-130"},{"speaker":"のだて委員","kind":"質問","question":"ちょっと私も調べまして、兵庫県では、公営住宅の趣旨を鑑みて、連帯保証人を確保できない場合に、自らの判断で入居を諦めてしまう方が残る懸念があると。やはりこうした姿勢が、区としても必要ではないかと思いますが、いかがでしょうか。実際に、入居できなかった人はいないというお話でしたけれども、区営住宅の入居に際して、連帯保証人が妨げになっていないという認識なのか、伺います。","respondent":"竹田住宅課長","answer":"現在、区としましては、現行の制度を維持していきたいと考えております。","voiceIndex":310,"id":"exchange-131"},{"speaker":"のだて委員","kind":"質問・要望","question":"入居の妨げになっていないかどうかという、そのような認識かということで聞きましたので、そこのところも答弁していただきたいと思います。区営住宅、公営住宅だからこそ、こうした視点が重要だと思いますけれども、いかがでしょうか。区としては、この利用者の１万円負担も大変だと思っていないのか、伺います。","respondent":"竹田住宅課長","answer":"本制度は平成１８年度から導入して、個人の保証人、法人の保証人、いずれも見つけられなかったというケースはございませんので、妨げになっているとは考えてございません。それから、保証料については、必要な経費だというふうに考えてあります。","voiceIndex":312,"id":"exchange-132"},{"speaker":"のだて委員","kind":"質問・要望","question":"手数料のほうは必要な経費だということですけれども、やはり、この低所得者の方が生活をしていく上で、年間１万円としても、これはやはり結構大変な額になるのではないかなと。これがなくなれば、より余裕を持って生活を送れるということになりますので、そうしたところで、ぜひ、区としても廃止していただきたいと思いますけれども、この連帯保証人の廃止について検討したことはあるのか伺います。","respondent":"竹田住宅課長","answer":"区では、東京都の動き、国の動き等を見まして、常に現行制度が適切かどうかということは検討しています。検討の結果、現在は連帯保証人は必要という結論になっているところです。","voiceIndex":314,"id":"exchange-133"},{"speaker":"のだて委員","kind":"質問・要望","question":"検討しているということですけれども、ぜひ、これは改善していただきたいと強く求めておきたいと思います。次に２９号線です。地域住民が提訴した、補助２９号線の事業認可取消しを求める裁判は、５月にいよいよ判決となる大詰めとなっています。この間の弁論の中、重大な事実が明らかになりました。東京都が専門家の意見を聞かずにいた事実を、計画当時区は知っていたでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"委員にご紹介いただいた詳細のところは、私当時は担当をしておりませんでしたが、認識していなかったというところだと思います。都のほうにも確認する機会というか、そうした機会もなかったのではないかです。","voiceIndex":316,"id":"exchange-134"},{"speaker":"のだて委員","kind":"質問","question":"区も知らなかったというところで、専門家の知見を踏まえずに、区内、２９号線は３.５km、３.５kmにわたって住民の生活を壊す道路を進めるということは問題だと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そうした意味では、基本的に、延焼遮断帯というものは防災性の効果が非常に高いという認識のもとで、区としては、都と連携して、周辺の耐震化、不燃化、それから、ソフト的な防災的な取組み、こうしたところを重層的に進めることで、やはり地域。","voiceIndex":318,"id":"exchange-135"},{"speaker":"のだて委員","kind":"確認","question":"専門家の意見を聞かずにやっていた、この延焼遮断帯構想ですから、その防災性についても疑問が生じるところです。シミュレーションについてもお話がありましたけれども、この中でも延焼に大きな影響を与える飛び火が考慮されていないというところでのシミュレーションとなっており、都議会では、地域全体の安全性を確認したものでもないということが明らかです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-136"},{"speaker":"大沢委員","kind":"質問","question":"品川区国民保護計画、それと３１１ページ、時間があったらシェアサイクル事業について伺いたいと思います。そこの中で品川区国民保護計画、ここを、もう一度考える１つのツールとして、私は今日この質問をさせていただきたく、質問項目に挙げさせていただきました。最初に、ここにいう国民保護とは一体何を指すのか、説明してください。","respondent":"五十嵐災害対策担当課長","answer":"武力攻撃事態等における国民の保護のための措置に関する法律、通称国民保護法により、具体的な措置が規定されております。","voiceIndex":322,"id":"exchange-137"},{"speaker":"大沢委員","kind":"質問","question":"その中で自治体などが実施する国民保護というか、保護措置というものは、これも具体的に何を指すのか教えてください。自治体です。今度品川区に移ります。","respondent":"五十嵐災害対策担当課長","answer":"もう一つの国民保護措置、避難住民への救援に関する措置においては、区は、都の実施する救援措置に協力するとともに、その一部を実施することになります。","voiceIndex":328,"id":"exchange-138","title":"町会・自治会支援"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、ここで今都ということ、東京都と品川区の実際の役割の違いというものがあると思うのですけれども、そこのところはどうなっているのか教えてください。","respondent":"五十嵐災害対策担当課長","answer":"区は、都の実施する救援措置に協力しております。その他３つの措置がありますが、それらについては、都は広範囲にわたる応急措置の実施や、警戒区域の設定などを行う一方で、区は具体的な区民などに対する措置を実施することとなります。","voiceIndex":330,"id":"exchange-139"},{"speaker":"大沢委員","kind":"質問","question":"国民保護に関わる事態が発生した場合、区はどのような体制で臨まれるのか。そこのところ、いろいろと体制をつくられていると思うのですけれども、そこのところを明確にというか、私たち理解はしていても、はっきりとした情報というか、はっきりとした知識がないものですから、そこのところを明確にお答えください。","respondent":"五十嵐災害対策担当課長","answer":"国が武力攻撃事態を認定した場合は、国民保護対策本部の体制に、緊急対処事態を認定した場合は、緊急対処事態対策本部の体制に移行いたします。なお、国民保護対策本部および緊急対処事態対策本部の体制は、実態として災害対策本部に準ずる体制で対応することとなります。","voiceIndex":332,"id":"exchange-140"},{"speaker":"大沢委員","kind":"質問","question":"災害対策本部に準ずる体制ということで今お話しいただきましたけれども、それはどのような理由があって、そもそも災害とやはり有事というものは別なように感じるのですが、そこのところは１つの組織でしっかりと対応できるのでしょうか。お答えください。","respondent":"五十嵐災害対策担当課長","answer":"体制の件でさらにお尋ねです。国民保護計画で実施する、区としての具体的な措置の内容は、医療の提供、区民の避難、そして避難収容施設の開設、避難者の生活の支援、災害の復旧に関することなど、災害時の対応とほぼ同一の対応になるからです。","voiceIndex":334,"id":"exchange-141"},{"speaker":"大沢委員","kind":"確認","question":"ほぼ同一の対応、それでももう１回確認しますけれども、同一の対応で十分組織として機能するわけですね。","respondent":"五十嵐災害対策担当課長","answer":"そのように理解しております。","voiceIndex":336,"id":"exchange-142"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは理解では駄目だと思います。しっかりとした検証をして、有事、これはもういとまがないわけですから、そこのところはスムーズにしっかりと組織が進むようにやっていただきたいと考えています。","respondent":"滝澤災害対策担当部長","answer":"そのほかに、国民保護の場合は広域避難であるとか、あと他自治体からの避難民の受入れというような業務が追加されますので、そのようなときは柔軟に組織を拡充して対応していきたいと思います。","voiceIndex":338,"id":"exchange-143"},{"speaker":"大沢委員","kind":"質問","question":"いろいろな有事の中にはテロリズムがあったり、ゲリラがあったりするわけでして、この品川区の近くには大井火力発電所というものがあります。近くに行けば、川崎にも火力発電所があります。そういった意味では、今ロシアで見られるような状態、起こり得るわけだと思いますけれども、そこのところは想定をされていて、それに対する対処の方法、危機感というものは持たれているのでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"大井火力発電所に関するお尋ねです。重要施設である大井火力発電所が攻撃された場合の措置についても規定されております。","voiceIndex":340,"id":"exchange-144"},{"speaker":"大沢委員","kind":"質問","question":"規定をされている、規定はされているのだ、今聞いて分かる。どのように規定されているのか、簡単でいいから教えてください。","respondent":"五十嵐災害対策担当課長","answer":"事態が発生した場合に対処するためのパターンを６パターン、品川区では用意しております。それに応じて対応しています。","voiceIndex":342,"id":"exchange-145"},{"speaker":"大沢委員","kind":"質問","question":"細かいことは、機密に関することなのでこれ以上は伺いません。ちょっと話は変わるのですけれども、私今手元にあるのが、改訂版で令和２年３月ということで持っているのですが、ホームページには平成１９年のものが載っていたりして、この令和２年の最新版というものはいかがなっているのでしょうか。教えてください。","respondent":"五十嵐災害対策担当課長","answer":"申し訳ございません。確認して修正したいと思います。","voiceIndex":344,"id":"exchange-146"},{"speaker":"大沢委員","kind":"質問","question":"載っていないのです。だから、すみませんけれども、なるべく早くに、いろいろと業務多忙で、このコロナ禍でいろいろあろうかと思いますが、なるべくなら速やかに、お手隙などと言ったらちょっと表現が悪くなりますけれども、なるべく早急に変えていただくことを望んで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":346,"id":"exchange-147"},{"speaker":"塚本委員","kind":"質問","question":"私からは３１１ページ、路面維持管理費、それから３４９ページ、初期消火体制強化費、火災のことについて伺います。火災の発生や出火の原因などについて伺いたいたいと思います。そうすれば、そもそも道路課がまた直しに行くというようなこともかなりなくなるわけなので、そこのところというのはどうなのでしょうかということをお伺いしたいと思います。","respondent":"稲田土木管理課長","answer":"道路課とも連携しながら、道路課は区内を巡回している、私どもは現場を見に行く、そのようなものをやりながらやるのですけれども、やはり区民生活上大きく、そのような振動や段差などが影響しますので、注意喚起、注意指導というのを行っておりまして、年に４回。","voiceIndex":348,"id":"exchange-148"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、きちんとやってもらえればしっかり戻るのだという、このような認識でよろしいのでしょうか。","respondent":"稲田土木管理課長","answer":"そのような温度管理もしっかり、それはきちんと基準に入っていまして、現場到着温度などを測らないといけないのです。そのようなことをしっかりやってもらえれば、きちんといくと思います。そのようなところを指導していきたいと思います。","voiceIndex":350,"id":"exchange-149"},{"speaker":"塚本委員","kind":"質問","question":"消火活動、懸命の消火活動をしていただいているおかげで、本当に木密地域等で起こっているのですけれども、最小限の被害で収まっているというような実態ではあるかと思うのですが、特に荏原地域の老朽木造住宅での火災の発生状況、そして主な出火原因等について教えてください。","respondent":"五十嵐災害対策担当課長","answer":"品川区に関してですけれども、令和元年までの過去３年の火災原因の第１位は、電気火災になります。第２位はたばこ、第３位はガステーブルの順になります。島しょ部を除く東京都全体では、令和３年中の火災原因の第１位は放火になります。","voiceIndex":352,"id":"exchange-150"},{"speaker":"塚本委員","kind":"質問","question":"今電気火災ということで、特に幾つか私の地域でも、火災が発生した後の原因等を聞くと、大体老朽住宅で、漏電という話を何件か聞きました。そういった器具等の活用によって、こういった漏電火災というものを防いでいくというようなことも考えられるのではないかと思いますが、もう一重の漏電火災等の対策強化、考えられることについてお伺いいたします。","respondent":"五十嵐災害対策担当課長","answer":"現在様々な電気火災に対応する器具等が、出回っている状況です。ぜひ、そういったものを使っていただきたいのですけれども、使うことと同時に、皆さん所有している電気器具等を確認していただきたいと思っています。","voiceIndex":354,"id":"exchange-151"},{"speaker":"塚本委員","kind":"質問・要望","question":"これと、今回のこの備蓄物資輸送・管理業務委託、ここについて、これはもともと品川区として備蓄したものをしっかり、先ほどどなたかの委員の質疑でもあったかと思うのですけれども、必要なところに届けるというようなことの業務というふうに伺いましたが、この受援で受け入れた物資と、もともと品川区として備蓄していた物資、こういったものがそれぞれうまく連携してというのですか。","respondent":"平原防災体制整備担当課長","answer":"新たな事業であります、こちらの事業ですけれども、令和４年度から行う予定となっておりますが、考え方といたしましては、先ほど委員ご指摘の、平成２８年度の熊本地震での物資の混乱、それを受けまして、平成３０年に品川区が行いました支援物資の再構築。","voiceIndex":356,"id":"exchange-152"},{"speaker":"塚本委員","kind":"質問・要望","question":"最後に生物多様性地域戦略策定について、簡単に確認をさせていただきたいと思うのですけれども、これは先ほども渡部委員からありましたが、基本的には国や環境省のほうが、生物多様性基本法というものを多分根拠にして進めているという中で、品川区もこれを戦略策定していくということだと思うのですけれども、この戦略策定の中で、先ほどのご答弁に加えて、いわゆる生態系の維持とか、生物。","respondent":"高梨公園課長","answer":"来年度の調査の中で、区民への意識調査等も考えてあります。そういった中で、区民の方々がどういったことを考えているのか、要望しているのか、そういったところを把握しながら考えていきたいと、このように考えております。","voiceIndex":358,"id":"exchange-153"},{"speaker":"塚本委員","kind":"意見","question":"ぜひ、そういった区民のいろいろな活動もきっとあるのではないかと思いますので、そういった際にはしっかり対応できるような形でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":360,"id":"exchange-154"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私からは、最初に公園管理というか、公園について、みなとが丘ふ頭公園について伺いたいと考えています。みなとが丘ふ頭公園、昭和４２年１月２０日に開園しました。そのようなことであれば、品川区で整備するといってどれぐらいまで整備できるか分からないけれども、使いたいなと思っているのですが、それは前にもお話ししたから、その状況がどのような状況なのかということを教えていただきたい。","respondent":"高梨公園課長","answer":"東京都のほうからの回答といたしましては、当該の公園、いろいろと今、利用の目的等のご案内がありましたけれども、都用地の拡張であったりとか、再整備、これは長期的な将来の話であろうと思いますが、そういった際に。","voiceIndex":362,"id":"exchange-155"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"コンテナばかりで。だから海を返して運動をやって、向こうを整備してもらって、向こうをコンテナヤードにしてもらって、品川区は海に面したところをそれぐらい、５万平米ぐらいくれというぐらいの感じを私は思っていて、ぜひそのような気合でチャレンジをしていただきたいと思うのだけれども、ぜひその辺の見解を教えてください。","respondent":"高梨公園課長","answer":"現在は、先ほど申し上げたような東京都の見解ではありますけれども、一部利用も含めた、今後のみなとが丘ふ頭公園の区利用の可能性については、積極的にというか、継続して東京都とは協議してまいりたい、このように考えております。","voiceIndex":364,"id":"exchange-156"},{"speaker":"石田（秀）委員","kind":"提案","question":"このようなことを踏まえると、様々そのようないろいろな提案をしていくし、地域の中でそのような提案が、しろというならいつでもそのようなことはできるので、そのようなことをぜひ取り上げていただいて、やっていただきたいということと、あとはやはり何か仕掛けが必要だと、例えば大阪の中之島などは、３０分に１回消防のホースのようなもので水をバーッと飛ばしているだけなのだけれども。","respondent":"栗原河川下水道課長","answer":"引き続き船舶とカヌー、それからＥボートといった非動力船が共存できる環境につきまして、地域の皆様、それから舟運事業者、港湾局、それから海上保安庁などと検討を進めてまいりたいと考えています。それから、水辺の景観に関しましてご質問いただきました。","voiceIndex":366,"id":"exchange-157"},{"speaker":"石田（秀）委員","kind":"提案","question":"それで提案はいいのですけれども、私は代表質問でもやったのですが、そのプロポーザルで選択をするときに、補助金の話を入れてほしい。勉強してほしい。ただ提案してくださいといろいろなお願いをするよりは、そのような補助金が取れるもの、このようなものをぜひ中に入れて、まず、そこから提案したほうがいいということは代表質問でもやったのだけれども、その辺のところの話だけ、最後にお聞きします。","respondent":"竹田住宅課長","answer":"空き家に関する東京都の補助金で様々なメニューがあります。そういったものを活用できるように、事業採用の検討をしていきたいと考えております。今回の提案事業ですが、空き家の所有者の方、いろいろな形態の方がいらっしゃいます。","voiceIndex":368,"id":"exchange-158"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひそれはよろしくお願いします。今の話は住宅課だけではなくて、障害者福祉課とか、いろいろなところで建て替えをしてくれてもいいわけです。そのようなものの事業から入っていくということも必ず必要だと思いますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":370,"id":"exchange-159"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1154#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":131731,"voices":371}}]);
